/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120306-3","meetingId":"h24-c-budget","date":"2012年3月6日","dateIso":"2012-03-06","committee":"予算特別委員会","time":"午前１０時００分～午後５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件整理しています。","topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"それから１２９ページの資源持ち去り防止過料、６２ページの歴史館使用料について、お伺いします。それともう１つ、５６ページの産業経済費負担金についてですけれども、説明を求めました。","respondent":"阿部経理課長、米田商業・観光課長","answer":"東京法務局の方と年１回会う機会がありますので、その際には区の意向としては移転は反対であることは、当然申し上げているところです。何か現状に変更があったら速やかに報告をお願いしたい旨も申し入れておりまして、現在のところ… そちらの修繕費等につきまして、来年度におきましては社会福祉協議会にかかる大きな工事がない関係で、その分が減っているです。３年にいっぺん、公有財産の使用料の算定について見直して、使用料をいただいているものです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"法務局に関しましては、やはり常にアンテナを張って、移転に反対であるという立場で、これからも明確に対応をしていってほしいと求めました。利用料を取って、また助成を出している意味というのは、どういうことなのか尋ねました。","respondent":"米田商業・観光課長","answer":"こちらで算定を行いながら、それから管理費ということで、管理を行っている部分についてのお金をいただいているものです。あるいは人件費に対する助成ということでやっておりまして、それぞれ別の意味での歳入と歳出ということでとらえているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"いろいろな減免をしているのは当然だと思うのですが、そういった考え方はどうなっているのかを疑問に思ったので、教えてほしいと求めました。","respondent":"米田商業・観光課長、榎本企画財政課長","answer":"全額いただく場合もありますし、減額あるいは免除ということがありまして、それはそれで別に計上している。いわゆる使用料については、もともとの財産として幾らもらうのが適切かということをまず算定した上で判断して… そういった中で、歳出の場合には目的別に歳出するということで、その目的に沿った歳出になっています。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"皆さんのいろいろな声をたくさん聞くのですが、中小企業センターから消費者センターに移ってきて、今の現状というか現状認識についてはどのように把握されているか尋ねました。","respondent":"米田商業・観光課長","answer":"利便性のある、あるいは品川の観光情報の発信ができるということでの取り組みを、現在進めているところです。これから、多様な品川区の観光情報をそこから発信し、あるいは訪れていただくことへの取り組みの途中の段階にあると考えているところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"羽田空港の案内所で品川区について一番問い合わせが多いのは何ですかという話が出たときに、やはり商店街の問い合わせが多いということで。商工会議所もありますけれども、その辺のほかの既存の団体との協力関係はどうなっているか尋ねました。","respondent":"米田商業・観光課長","answer":"少なくとも土日はあけるということで観光協会が取り組みをされているということで、そちらの状況についても聞いてまいりたいと考えています。には観光協会と他団体との連携をもっと密にしていく、できるところから取り組んでまいりたいと思っているところです。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"１２９ページの資源持ち去り防止過料について、お伺いします。現状５万円ということでありましたが、どういったことが、事件等ありましたら説明するよう求めました。","respondent":"太田品川区清掃事務所長","answer":"その命令に違反した場合に初めて過料５万円を科すという条文になっております。早朝からパトロール２台出てありますけれども、その命令に従うということで、今年度について過料は科したケースがございません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"やはりこういうごみは資源ですから、過料を徴収できるような制度をこれから進めていかなくてはいけないのではないかと思います。警察との協力とか、そういった資源略奪者の摘発をどんどん進めていかなければいけないと思うのですけれども、改めてそのお考えを説明するよう求めました。","respondent":"太田品川区清掃事務所長","answer":"１点、最初にご説明をします。連携して一緒に回っていただくようにはお願いしているのですけれども、さらに警察との合同パトロール等を実施していきたいと考えています。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"法律的には泥棒にならないみたいですけれども、泥棒と一緒だと思っていますので、ぜひとも、ごみは財産だと思って、資源を財産という認識で戦ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問・要望","question":"そして１３４ページ、時間があれば７２ページの自転車駐車場使用料について、お尋ねしたいと思います。平成２２年度との数字の大きな差と、それから平成２３年度、固定利用者がほとんどなのかというところの２つを教えてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"平成２２年度、平成２１年度とも、または歴史の自主グループ等が借りているところです。講堂は小講堂、大講堂ありますけれども、１つにまとめさせていただいて講堂として表示をしています。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問","question":"すみません、ホームページの部分は、何で講堂とかまとめてもらっているかではなくて、ホームページに掲載していない理由というところを説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"講堂については、利用の団体が、歴史館に訪れました小学校、または学校の団体へのレクチャーだとか館内説明、そのためにほぼ使っております。ほぼ講習会等で使われる程度でほとんど使用がないので、ホームページには掲載させていただいてません。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"次の観覧料なのですけれども、平成２２年度決算で有料の観覧者数が８,２３９人と出ていて、平成２３年度予算が７,７５０人。３７０人くらい増えて予算を計上しているわけでありますけれども、少し増の予算にしているのかどうか、この辺を説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"鉄道に関しては、平成２４年度に実施する予定ですが、一般の観覧料については、品川区の歴史伝統文化が徐々に区民の皆さんに広まってまいりました。そんな中で、一般観覧についても、徐々にニーズが増えていくと思いまして計上させていただいたものです。","id":"exchange-011"},{"speaker":"鶴委員","kind":"提案","question":"提案で最後終わりますけれども、歴史館サイドとしてそういったことで連携してアピールを強くしていくとかいうことも必要なのではないかと思います。「ラッキーセブン」だったか尋ねました。","respondent":"井浦土木管理課長","answer":"ロケーションにつきましては、まず平成２４年度予算ですが、実績見合いベースでこのような金額で約２０％アップということで見込んでおります。平成２２年度が１３０件で推移しておりまして、平成２３年度現在１月末ですが、８９件という実績です。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"今度３月だったか、３回目の委員会があるそうですけれども、品川区も間違いなく大井町を中心として観光スポットになる可能性はあるのかなと。そうした何か積極的な企画を立てていったらどうかと思いますけれども、何かもし考えがあれば説明を求めました。","respondent":"米田商業・観光課長","answer":"今、大田区等にとどまっておりますけれども、東京都内各地との観光の連携を進めていくことも重要だと考えています。その中で品川区の中に１つ、２つスポットをつくってルートの中に組み入れていく、フィルムの関係とあわせて取り組んでまいりたいと考えています。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"次、１３４ページの広告料収入について、お尋ねいたします。これも対前年９５.７％で若干の減となっていますけれども、その理由を簡単で結構ですので説明を求めました。","respondent":"荒井広報広聴課長","answer":"広告料収入についてのお尋ねです。減になっている主な理由といたしましては、バナー広告の予算配分を少し減らしたものによるものです。","id":"exchange-014"},{"speaker":"鶴委員","kind":"意見","question":"自分で考えていた理由とちょっと違ったので、バナー広告ということで、ありがとうあります。お尋ねしたら、広告掲載していただける企業が増えるような工夫をしてみたらどうかと思いますけれども、その辺のご見解を説明するよう求めました。","respondent":"荒井広報広聴課長","answer":"広報紙の役割は、一義的には区のお知らせ、広告掲載をこれ以上増やすところはなかなか難しいかと考えているところです。ただ、特集号への広告掲載であるとか、広告料の柔軟な対応であるとか、アイデアをいただきましたので、研究させていただきたいと思います。","id":"exchange-015"},{"speaker":"鶴委員","kind":"意見","question":"最後７２ページ、自転車が前年度比マイナス２,５００台なのですが、時間がないので切ります。すみませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"住民基本台帳事務、今年７月から外国人の方にも住民票をということで、かなりがらっと仕組みが変わってくると伺っています。品川区は今年１月１日現在で、おそらく１万１,０００人ほど外国人登録の方がいらっしゃるのではないかと思うのですが、説明を求めました。","respondent":"梶戸籍住民課長","answer":"こちらは今年７月９日から施行ですけれども、外国人登録に関係する諸法律および住民基本台帳法の一部を改正いたしました。住民票１つをとれば、全員の方のものをとれる形になってあります。","id":"exchange-017"},{"speaker":"向委員","kind":"質問","question":"先日伺ったところ、５月に入ってから仮の住民票ですか、仮の住民票は何の情報をもとに送られるのか。なので、送られないと考えられる理由、どう把握、認識されていらっしゃるか、そのあたりを説明するよう求めました。","respondent":"梶戸籍住民課長","answer":"我々といたしましては、その申出をした後に、例えばまた出国されているという状況もすべてリアルタイムには反映できないものがありました。","id":"exchange-018"},{"speaker":"向委員","kind":"確認","question":"なしとかを確認されているかと思うのですが、窓口で「ちゃんと在留資格とか行ってください」というのは、区でもされているのですよね。確認なのですが、それをお願いします。","respondent":"梶戸籍住民課長","answer":"もちろん、外国籍の方は戸籍はないわけですけれども、出生された場合については、最寄りの自治体に届け出ることになっております。オーバーステイの状況については、そういったご相談がありましたら、入国管理局に直ちにご相談するように伝えているところです。","id":"exchange-019"},{"speaker":"向委員","kind":"質問","question":"１つ、外国人集住都市会議とか、幾つかそういった外国人の子どもの日本語教育とか学校就学に関するシンポジウムに出てみたのです。希望申請関係書類ですか、教えていただければと思うのですが、いかがか尋ねました。","respondent":"和氣学務課長","answer":"入りたいということでお見えになりましたら、私のほうで相談させていただいて、ちゃんと学校に来られるということであれば受け入れます。例えば大使館の方たちは登録がございませんので、そういう形でも受け入れてありますので、それは心配なく受け入れるです。","id":"exchange-020"},{"speaker":"向委員","kind":"質問","question":"入管に１日、そのときにどうしても腑に落ちない子どもの様子とかを伺ったりすると、やっぱり子どもは学校に行きたいのだなと。参加者が２１８名で、実際に申し込んで参加できる方が２分の１くらいの数なのかなということで、そういう計画はあるのか尋ねました。","respondent":"齋藤庶務課長","answer":"見た目と実際の参加者が変わっておりますが、実際は応募者の方はほとんど参加できる形になっております。今後につきましては、お子さんとお年寄りの方が一緒に文化財をめぐるような形での新しいメニューを新年度は検討しておりまして、参加者がより幅広く。","id":"exchange-021"},{"speaker":"向委員","kind":"意見","question":"先日、独自にいろいろなメニューをつくって品川区を知りたいという区民の方が結構集まっていらっしゃるというのを知ったのです。やっぱりどういう文化財があるとかを調べていくと、引き続き、区民が文化に触れる機会の検討と実施をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"８４ページなのですけれども、感染症対策費ほか２事業、ご説明をお願いしたいと思います。それとあとは８９ページの補助金のほうの感染症予防費で、充当事業が健康診査と感染症対策費の２つの項目に分かれておりますが、示すよう求めました。","respondent":"小川健康課長","answer":"続きまして、８９ページの感染症予防費の健康診査ですが、こちらは緊急肝炎ウイルス検診のみの充当事業です。感染症対策費の中身ですが、性感染症診査とエイズ啓発経費という内容です。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最初の８４ページなのですけれども、結核というお話がありましたけれども、結核対策費は第２節になっているので、第１節と重複するのか尋ねました。","respondent":"伊津野保健予防課長","answer":"結核対策費につきましては、健康診断とか結核の公費負担とかで内容が違いますので分かれております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"これはとにかく１００万人も無自覚な、今後も予防啓発に力を入れていただきたいと希望するのですが、Ｂ型肝炎の発病を防げるわけです。１カ月健診それと３カ月健診で、Ｂ型肝炎に関して、Ｂ型肝炎のワクチンを積極的に啓発するというようなお考えはないのか尋ねました。","respondent":"伊津野保健予防課長","answer":"妊婦健診のときに母親が肝炎にかかっていれば、その赤ちゃんが生まれたときに肝炎ワクチンを打つことが広まっております。一般的にＢ型肝炎ワクチンをすべての人に打つかどうかにつきましては、今、それをもって検討していきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次は９６ページの国民健康・栄養調査費について質問します。これが６４万円から３２万円と、これはどういう理由なのかということと、これは具体的にはどういう内容なのか尋ねました。","respondent":"工藤生活衛生課長","answer":"こちらの減額の理由ですけれども、３年に１度、大規模調査という部分がございまして、昨年度はその調査の該当であったということ。今年度、いわゆる大規模以外の小規模という調査の年になっておりますので、対象が少し狭くなるといったところで減額をしています。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"３番目にまいります。これは３９８万８,０００円が計上されておりますが、これは昨年度は実際に支払いがされているのか尋ねました。","respondent":"伊津野保健予防課長","answer":"障害年金として１件、支給されています。","id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"もしわかれば、ワクチンの種類を教えていただきたいのですけれども。","respondent":"伊津野保健予防課長","answer":"痘瘡であります。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"所得の少ない人が増えている原因をどう考えていらっしゃるのか、平成２４年度はどう見通しているのか、伺いたいと思います。なぜ２０代にこのような特徴があらわれているのか、平成２４年度の見通しも含めて、ご説明ほしいと求めました。","respondent":"高森税務課長","answer":"７００万円以上の方につきましてはわずかに減少しておりまして、平均で８６万円ほどです。これはあくまでも税の統計上の資料から持ってきておりまして、私どもといたしましては、かなり厳しい区民の生活がそこにはあると考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"先ほど伺ったのは、なぜ２００万円以下の方々が増えているのか、どういう特徴があるのか。その原因と特徴をどう考えているのか、しっかりとした分析が、私は必要だと思うのですけれども、改めてお伺いいたします。","respondent":"高森税務課長","answer":"年齢別の扶養の数ですけれども、０歳から１５歳については４００人ほど増加しています。１６歳から２２歳につきましては１２０人ほど減少している状況です。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"数字がどう動いたということを伺ったのではなくて、改めて伺いますが、その原因や特徴をどう考えていらっしゃるのか。そこの原因や特徴をどうとらえているのか、区の考えをご説明ほしいと求めました。","respondent":"高森税務課長","answer":"ただ、昨年１０月の内閣府発表の月例経済報告によりますと、電力供給等のマイナス要因も存在すると。雇用情勢については、持ち直しているものの依然として厳しい状況でございまして、個人消費もおおむね横ばいという状況で分析しています。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"品川区はどうお考えなのか、伺いたいと思います。同時に必要な支援策をどう考えているのか、伺いたいと思います。","respondent":"高森税務課長、榎本企画財政課長","answer":"先ほどからの質問ですが、若い人につきましては、確かに非課税者が増えているという認識です。品川区の場合、予算マイナス０.１％という形で見込んでおりますけれども、全体的な傾向としてはマイナスという傾向が続いているという形です。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"労働者派遣法など、若者の非正規雇用化がこうした貧困状態を増やしているのではないかと思いますが、品川区はどう考えているのか伺いたいと思います。役割分担の話がありましたけれども、どういう方向を考えていらっしゃるのか、あわせて伺いたいと思います。","respondent":"高森税務課長、榎本企画財政課長","answer":"非課税者が増えているという、区内におきましても低所得者の方が増えているという認識でございまして、経済も好転していない。傾向としては、先ほどから申し上げているとおり、横ばい、もしくは若干下がっている状況だという認識です。区としての支援策の方向性という話ではありますけれども、就業センターを立ち上げていく形で、区全体の就業をまずはやっていこうという形です。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"労働者派遣法など、雇用の改悪が進んでいることが背景だと思うのですけれども、品川区はどうお考えなのか伺いたいと思います。消費税の引き上げを行ったら、区民の暮らしへの影響がどうなっていくと見通しているのか、この点も改めて伺いたいと思います。","respondent":"高森税務課長、榎本企画財政課長","answer":"平たく言ってしまえば、区民の方の収入減です。 この間、景気状況は、やはり平成２０年秋からは決して上がっている状況ではありません。消費税の話がありましたけれども、消費税につきましては国で鋭意検討しておりますので、それに従ってという形になろうかと思います。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"現場の最前線だと思うのですけれども、そういう自覚を持った対応が私は必要ではないかと思うのですけれども、改めて伺います。しっかりと影響を見るべきだと思いますけれども、改めて伺います。","respondent":"高森税務課長、榎本企画財政課長","answer":"２０代のというお話ですけれども、私は２００万円以下というお話はしましたけれども、２０代の話はしてございません。それと、考えられるのは大学生の就職困難等々がまたここにも影響しているのではないかと考えているところです。確かに３％から５％に引き上がったのは大分前でありますけれども、今後、注視していかなければいけないかと。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問・要望","question":"予約抽選ですか、この抽選倍率を天王洲の部分の野球で１つ教えていただきたいのと、テニスコートも品川区はいろいろな場所にあります。抽選の倍率と、実際の利用率、このあたりを最初に数字で伺えればと思います。","respondent":"安藤文化スポーツ振興課長","answer":"区民公園のテニスにつきましても、５月２６日の例えば１５時から１７時という時間帯ですと、１枠に４５件申し込まれています。ですから、４面ありますので、１１.２５倍という形になってあります。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"言わんとしているのは、これから触れていこうと思うのですが、施設の部分で伺おうと思います。まず人工芝の点を１つ伺いたいのと、コート改修等の目安、耐用年数を伺えればと思います。","respondent":"稲田道路公園課長","answer":"それから平成１８年３月にＣ面も張りかえております。利用状況等によって変わる部分もあるのですが、一般的には１５年から２０年というところで、人工芝というところでは考えております。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"そういう意味で、耐用年数のところはもう１度、基準等があれば教えてほしいと求めました。この点について、どう考えるか、最後、伺いたいと思います。","respondent":"稲田道路公園課長","answer":"耐用年数なのですけれども、きちっと決まった、はっきりした耐用年数はないと私どもでは考えております。そういうところで長寿命化を図りながら、そういう需要には対応していこうと今、考えております。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"次に、しながわ区民公園の中の屋外水泳場という表記の中で、これは夏だと思います、冬の間、釣り堀という点で１つ伺えればと思います。あるのであれば、料金等、仕様があると伺えればと思います。","respondent":"稲田道路公園課長、冠木指導課長","answer":"公園関係の釣り堀ですが、しながわ区民公園の１カ所です。 学校が釣り堀を利用することは授業としてはやっておりません。魚に親しむということで、魚を揚げて、その後プールを掃除するというような作業をするという事例はあります。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"子どもの遊びという視点だと、東西南北、品川区も結構広いですから、それぞれ地域バランスで何かそんな拠点があればと思います。やはり昔の遊びとかそういう視点もすごく子どもの要望の中にあるような気がしますので、ぜひともご検討いただければと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"そして１３４ページの雑入の広告料収入、１３８ページのリサイクル資源売払収入、この点について質問させてほしいと求めました。ここの開きの要因、なぜそのようなことになったのかということで、まずご答弁をお願いしたいと思います。","respondent":"榎本企画財政課長","answer":"高齢者の人口だったり、そういうもので区別算定が行われまして、各区の算定は今年８月に出る予定になっております。その金額の見込みということで、今現在、この当初予算ではこういう形で見込んでいる形です。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"これからということなので、その算定に当たって、そうはいっても各区の思惑がいろいろ働く中でのこれからの算定かと思われます。特に力を入れていくというか、算定に臨んでいく上での基本的な考えというか、そういうものを確認の上でご答弁ほしいと求めました。","respondent":"榎本企画財政課長","answer":"ただし、その中で２３区共通経費としての財源保障でありますので、その中での全体的なバランスをとりながら、こういう算定がされていくという形です。品川区としても、毎年、区として重点を置きたい部分は積極的に算定項目として出せるような形で努力していきたいと考えています。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"では続きまして、７２ページの自転車駐車場使用料につきまして質問したいと思います。どういう見通しのもとでなされたのかということと、今のこの料金を決めている考え方、この２点についてお願いします。","respondent":"藤木交通安全担当課長","answer":"一時利用につきましては、現在、五反田あたりに新たに駐輪場を増設できないかということで検討を進めているところでございまして。次に２点目の料金体系の考え方ですけれども、民間の駐輪場の利用料金ですとか、そのようなものを総合的に勘案して決めているものです。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"今、料金の考え方をお伺いしました。そういった施策、どのようにお考えをもっていらっしゃるか、お伺いしたいと思います。","respondent":"藤木交通安全担当課長","answer":"１財団法人が運営してやっているものですので、現在、民間の自転車保険も昨年あたりからいろいろなものが販売されております。そういう中で、このＴＳマークのみを優遇するとなりますと、いろいろ慎重な判断が必要ではないかと考えております。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"本年度、１億７,６８９万９,０００円ということで、昨年に比べて大幅に予算が増額されたと伺いました。この理由についてお伺いしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"昨年度に比べて約３,３００万円余増えております。それから、予算編成上は前年の１０月１日の基準を用いていますので、その間に経済状況が動いてきて、単価の変動があった結果です。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"その１７のメニューの中の１つに、レアメタルのリサイクルというのも入っておりました。東京都の補助制度なんかも大いに利用して積極的に取り組んで、税外収入の確保に努めてはと思いますけれども、お考えをお聞きしたいと思います。","respondent":"太田品川区清掃事務所長","answer":"現在、国においてリサイクル制度の仕組みを構築できないかということで検討しています。審議会の答申がこの２月に出て、３月に閣議決定をして、そうした流れを注視しながら今後検討していくことになろうかと思います。","id":"exchange-046"},{"speaker":"塚本委員","kind":"意見","question":"よろしくお願いしたいと思います。貴重な資源ですので、長きにわたって大きな税外収入につながるのではないかという期待を持っておりますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは１０８ページ、１０９ページ、そして１１０、１１１ページで質問させてほしいと求めました。昨年度の予算では２６５万８,０００円、今年度が１９５万円と減っていますが、予算減の理由を説明するよう求めました。","respondent":"小川健康課長、福島荏原保健センター所長","answer":"医療保健政策包括補助金ですが、こちらの任意予防接種ほか２事業についてですけれども、猫の不妊・去勢手術費助成と、高齢者見守り事業です。それから、新しく在宅療養推進事業という事業が充当されたものです。今年の予算額が１９５万円に減っているということで、これは東京都の地域自殺対策緊急強化補助金が去年は２６５万８,０００円でした。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"１０９ページのほか２事業のほうで、今年は不妊・去勢の分はどうなっているのか教えていただきたいのと、いい取り組みなのではないかと感じています。よかったのかというところがわかれば教えていただきたいのと、庁内だとどういった方たちが参加しているのかを教えてほしいと求めました。","respondent":"工藤生活衛生課長、福島荏原保健センター所長","answer":"飼い主のいない猫の不妊・去勢手術につきましてのお尋ねです。来年度に関しましては平成２３年度と同様、頭数等も３３０頭分という部分で予算立てをしておりまして、平成２３年度同様２４０万円です。これは株式会社エフ・ビー・アイという会社とまた相談をしながら、その内容については適宜変更を加えていきたいと考えています。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"幅広くいろいろな方が参加して、少しでも自殺の予見とかができるように、これからも取り組んでほしいと求めました。実際、件数とか成果とかはどういったところか、わかれば教えていただきたいのですが。","respondent":"工藤生活衛生課長","answer":"当初２９件の助成ということでありましたけれども、昨年度は２３０件くらいの助成を実施したところです。そして、やはり急には成果は出てきませんけれども、そういった形で引き続き対策を練っていきたいと考えています。","id":"exchange-050"},{"speaker":"大倉委員","kind":"意見","question":"そうですね、猫も人生を全うしていただけるように、そうした助成も、地域猫はえさをあげている人にはなつくのですけれども、それ以外の人にはなつかないので、そういった部分で去勢はなかなか難しいのかなという思いもあるので、もう１歩前に進んでやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"あえて税務課にお伺いしますが、いわゆる滞納があってはいけないことですから、教えてください。類似の施設と比べてどうなのかということを教えていただきたいのと、これに比べて、今の現状ではどうなっているのか説明を求めました。","respondent":"高森税務課長、榎本企画財政課長、福島ものづくり・経営支援課長、原高齢者福祉課長、安藤文化スポーツ振興課長","answer":"普通徴収につきましては２,２００人減少しておりますけれども、これにつきましては非課税者が増えたという認識です。… 今現在、平成２４年の税収見込みで行きますと、予算規模から行くと平成１８年ごろとほぼ同じくらいの税収見込みと予算総額は思っています。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１つ、さっきの「ほか」というものに関しては、金額ではないとさっき高齢者福祉課長もおっしゃいました。事業内容なので、これは次の予算書には少し考慮してほしいと求めましたが、いかがか尋ねました。","respondent":"榎本企画財政課長","answer":"この間、交付金に変わったということの経緯がわかるように細かい項目を入れております。土木費補助金については、この項目がないと１項目だけになってしまいますので、そういった意味でわかりやすさを目指しています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"私からは７２、７３ページの学校施設使用料の中で、特に校庭の部分に関して質問をします。３点目は、小中一貫校と中学校の中で、部活のことなのですけれども、日曜日の校庭を使っている学校は何校あるのか、その辺を説明するよう求めました。","respondent":"安藤文化スポーツ振興課長、齋藤庶務課長、冠木指導課長","answer":"学校施設の使用にかかわる校庭の利用についての一般団体ですけれども、昼間の校庭については、９６％少年少女団体が利用しているところです。大人の場合は… 伊藤学園は部活がありますので行っておりません。それ以外の学校すべてで校庭開放をしております。 部活ですけれども、中学校、小中一貫校ともに、そのときどきの状況もありますけれども、部活で学校の校庭は使用しています。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後の部活のところなのですが、日曜日の校庭の状況を教えていただきたいので、後で教えてください。大前提になるかと思う部分を確認させていただきたいのですが、委員会は、そこの確認を先ほどのこととあわせて、答えるよう求めました。","respondent":"安藤文化スポーツ振興課長、冠木指導課長","answer":"それで今、委員ご指摘のとおり、教育上支障がないと認める限りはすべて地域の開放になるです。各学校の部活ならびに教育等に支障があれば、それは学校の利用ということで、それ以外を私どもの地域スポーツが利用させていただいているで… 日曜日の部活ですけれども、各学校の部活のあり方、それから年間の行事等々を勘案して、計画的に使用しています。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして大人の部分でも社会教育団体が大きな期待を持っていて、私は大いに活用していただきたいと思っています。私は本来の教育施設のあり方ではない、本末転倒ではないかと思っているのですが、この点はいかがか尋ねました。","respondent":"齋藤庶務課長","answer":"校庭開放の部分についてご説明申し上げます。昨日もＰＴＡ会長と、どのような考えであるか、今後、調整しましょうというお話をしています。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１回、表を確認していただきたいのと、使いたいときには使えています。は全部貸し出し施設になっているということでは、やりたければやれるのだということではないと思いますが、もう１度、答えるよう求めました。","respondent":"齋藤庶務課長","answer":"学校を中心に考えます。このときにＰＴＡとの話し合いで、ＰＴＡが使うというのであればお使いいただけるということで説明させてもらっております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"確認書の資料の別表第２のところにも、９時から１９時、少年少女のスポーツ団体に貸すと明確に書いてあります。そこのところをもう１回お答えいただきたいのと、地域振興事業部と子ども未来事業部と教育委員会との３課が確認しているのですが示すよう求めました。","respondent":"齋藤庶務課長","answer":"日曜日は低学年用庭は学校が使う、使わないの判断をします。２０人、３０人の生徒のクラブ活動に支障のない範囲で使用できるということで確認をしてお貸しするものですので、ご心配はご無用です。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"確認","question":"ほかの学校と同じということであれば、日曜日使えるのか。部活にもきちんと使えるのかどうか、そこをもう１回確認します。","respondent":"齋藤庶務課長","answer":"日曜日の校庭開放はＰＴＡに委託する事業です。自主的にＰＴＡの方がやる、やらないを一義的にご判断されますので、区のほうでやる、やらないをお示しするものではありません。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"だから、やれる下地がきちんとあるのかということと、部活が日曜日できるのですか。日曜日、使えるのか尋ねました。","respondent":"齋藤庶務課長","answer":"日曜日、低学年用庭でできます。部活も大会の前については、学校が優先で使用できます。","id":"exchange-060"},{"speaker":"金野委員","kind":"質問","question":"そして１３７ページの歴史館講座等という、もう１つが１３３ページの受託事業の中の大森駅歩道橋、この２点をお伺いします。品川歴史館のほうからお伺いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"歴史講座、古文書入門講座、それと特別展の記念イベント、または特別展の記念の茶会もここには入ってあります。人数的には平成２２年の実績では３０４名の方に参加していただいております。","id":"exchange-061"},{"speaker":"金野委員","kind":"質問","question":"先ほどうちの会派の鶴委員からもこの歴史館の使用料を伺いましたけれども、その中で、先ほどのご答弁では。なぜ一般利用ではなくて団体利用で、講座だけに絞っているのか、そこら辺のお考えを説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、伝統文化事業だとかそういうものに限っていますと、非常に少なくなっております。ですから、学校の生徒たちがそこへ来て勉強していただいたり、または講演会だとか講座等をそこでやっている状況です。","id":"exchange-062"},{"speaker":"金野委員","kind":"意見","question":"でも今、課長のご答弁の中に、いろいろなお問い合わせというところで、何に使えますかと。今後は現状のままで行こうというお考えなのか、こういう使い方はどうされていこうとされているのか、お考えを説明するよう求めました。","respondent":"安藤文化スポーツ振興課長","answer":"書籍から生活用品に至るまで、多様な郷土があります。区民のための、区民の思いを酌んで、事業を展開していきたいと思っています。","id":"exchange-063"},{"speaker":"金野委員","kind":"質問・要望","question":"多くの方に知っていただきたいということで保管をしている、費用対効果という言い方がどうかわかりませんが、単純に比較できるものではありません。大事な財産ですから当然保護するためにはそれなりのお金が必要だと思うのですが、財政を確保するという観点から見たら、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"歴史館自体が非常に貴重な価値のある文化遺産だと考えています。そういうものも時代に残していく、継承していくという我々の努めもありますので、そこら辺も踏まえて、今後の展開を考えていきたいと思っています。","id":"exchange-064"},{"speaker":"金野委員","kind":"質問・要望","question":"そのお金をかけるだけの価値をやはり多くの方に知っていただきたいですし、そのためには講堂を使っていくというのは１つの観点ではないかと思うのですが、最後にいかがか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"講堂の使用に関しましても、基本的な伝統文化的な貸し出し等を視野に入れて、また利用の方法等を工夫しながら考えていきたいと思います。","id":"exchange-065"},{"speaker":"金野委員","kind":"質問・要望","question":"お勉強される機会にされることを期待しておりますので、どうか、さらによくできるように頑張ってほしいと求めました。もう１つの質問をしたいところでしたが、歳出の款でしますので、これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"山内委員","kind":"質問","question":"７３ページで、午前中に鶴委員から質問がありましたけれども、そのあたりを伺いたいと考えています。１回分の料金形態と、その料金形態の根拠といったところ、それから場所によって料金形態が違ってくるのかというところを伺いたいと思います。","respondent":"井浦土木管理課長","answer":"土地の標準価格に一定の定数をかけてm2当たりの単価を出すわけですが、このような価格設定をさせていただいているところです。１時間当たり１時間３,０５０円ということでは統一的に行っているということで、長期についての優遇措置は現在のところございません。","id":"exchange-067"},{"speaker":"山内委員","kind":"質問","question":"この５８４万何がしという金額なのですが、これは計算すればわかるのですけれども、何回分を想定した予算なのかということを伺います。要は営業をかけるというのか、そういったことを考えているのか、それを伺いたいと思います。","respondent":"井浦土木管理課長、米田商業・観光課長","answer":"ロケーションにつきましては、年間２７０件を想定しておりまして、３５２万３,５００円です。単価１,４７８円の２１０回、３１万円余を想定しておりまして、このような予算見積もりになってあります。確かに品川区の魅力、情報をメディアによって発信することは１つあるとは思うのですけれども、地域でのご理解がまず大前提だろうと考えています。","id":"exchange-068"},{"speaker":"山内委員","kind":"質問","question":"しかしながら今回、ドラマをやっているということで、いろいろな話を伺うことがあります。ですから、その辺のこれからの考え方を伺いたいと思います。","respondent":"井浦土木管理課長","answer":"法律論的にはそのようになります。円満な利用調整ということとロケーションということの意義も踏まえまして、調整という部分については意識的に頑張っていきたいと考えています。","id":"exchange-069"},{"speaker":"山内委員","kind":"質問・要望","question":"今のご答弁、期待しておりました。やはりこれからの、いわゆる行政からの貸し出すに当たっての配慮をしっかりと考えて、これからもこの施策に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"お伺いしていた明晴学園のところで、例えば本年度予算になりますと、どこの款のどこの項の目に入ってくるのか。明晴学園の件で、どこに入っているのかと幾らなのか。","respondent":"阿部経理課長","answer":"明晴学園の土地の貸付の件ですけれども、１２２ページの財産貸付収入、２目財産貸付収入の３節に地所賃貸料があります。この中に入ってあります。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問","question":"算定の形と今までの金額との相差ですとか、その辺、今年はどうなるかというのをもう１度、説明をお願いします。","respondent":"阿部経理課長","answer":"貸し出しの金額といたしましては、年額で１,３８２万４,０００円です。これは当初貸し付けたときと変わりございません。","id":"exchange-072"},{"speaker":"渡部委員","kind":"質問","question":"昨日、子どもの人数に応じて７割減額とかというのは、１年間、平成２４年は丸々この額でいいのか尋ねました。","respondent":"阿部経理課長","answer":"昨日も申し上げましたけれども、当初１００人予定していましたけれども、それまでいってございませんでした。平成２４年度につきましても、人数が当初と比較して飛躍的に増えているわけではございませんので、引き続き７割減額しているものです。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"その減額団体が反映されているのかどうかを教えてほしいのが１点。これは相当数増えると思うのですけれども、それなりの数、把握をされているのかどうなのかというところを先に説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"そうやって考えてみますと、総合計は、体育館、校庭、夜間校庭も含めまして、平成２２年度実績で７２万９,９３８人の利用者がございました。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問・要望","question":"校庭においては９６％免除という話で、やはりいろいろな意味で支援を続けていただきたいので、そっちを先にやろうかな。この考え方はどうでしょうかという言い方は変ですけれども、立派な教育活動だと思いますけれども、いかがか尋ねました。","respondent":"齋藤庶務課長","answer":"土日、一生懸命子供たちを育てる。そういったところに大人が集まって、荏原地区と含めて切磋琢磨する場面というのは大変大きい教育活動であり、青少年活動の結合だと考えております。","id":"exchange-075"},{"speaker":"渡部委員","kind":"意見","question":"時間がなくなってしまったのであれなのですけれども、聞きたいのは、この学校の教育施設に限らず、いろいろなやり方がある中で、何か統一できることがあるのであれば、そのほうが、例えば払い忘れとかもなくなりますし、いいのかなという思いでお話をさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"７２ページの土地建物使用料と、もう１つは１３７ページのすまいるスクール参加費について、お伺いします。７２ページの土木使用料の中の土地建物使用料なのですけれども、どんなものがあるかを教えていただきたいので、お願いします。","respondent":"井浦土木管理課長","answer":"それから大きなところでは、大井町駅周辺地区再開発事業用地が６９０万円余の使用料になってあります。ガス制圧管、区営住宅の敷地に埋設しているというものの使用料になってございまして、総件数で２６件という状況です。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"その大きな２つについてご質問させていただきたいのですけれども、どのくらいの駐輪のスペースというか、台数とかはあるのでしょうか。ご存じか尋ねました。","respondent":"藤木交通安全担当課長、三宅都市開発課長","answer":"１点目のお尋ねでありました大井町の再開発地区の駐輪場の関係です。こちらは民営の駐輪場でございまして、自転車、バイク合わせまして６２２台の収容台数があります。 こちらのまちづくり事業用地の今後の活用ですけれども、再開発を今後促していくべき地区と位置づけております。まだ具体的な動きはないのですけれども、そういう動きが出てきたときに、開発に活用していく考えです。","id":"exchange-078"},{"speaker":"吉田委員","kind":"意見","question":"６２２台という台数を収容している中で、ご存じかと思いますので、お願いしますとの意見を述べました。","respondent":"藤木交通安全担当課長","answer":"百貨店ですとかそういう大規模な小売店の場合は、２０m2ごとに１台ということで条例で定められております。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問・要望","question":"ということは、なかなかこの台数を収容することは、私も調べたところ無理ではないかと思うので、その辺、どうなのでしょうか。その辺をお伺いしたいので。","respondent":"三宅都市開発課長","answer":"用途によって何m2につき何台というのは義務になっておりますので、プラスどのくらいの台数を確保すべきかというのは、その計画の中で配慮していきたいと考えております。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問","question":"五反田の水辺広場のカフェレストランについてお伺いしたいのですけれども、こういうような区立広場の中に、ほかには施設はありますでしょうか。その辺をお伺いしたいのですけれども。","respondent":"井浦土木管理課長","answer":"したがいまして、公園内に品川区の建物があるという位置づけになっております。まちづくりの情報の発信と、ギャラリーがありますので、そこでそのような催しを企画している状況です。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"それで、水辺広場は防災船着場に隣接していますね。それに関しての区と連携しての緊急時対策や地震対策等に関して、どのようになっているのかお伺いしたいのですけれども。","respondent":"井浦土木管理課長","answer":"この施設の計画につきましては、レストハウスとギャラリーだけではなくて、防災のための倉庫ということでも充実しまして、地域の防災力の強化というためにも役立つという位置づけで運用しているものです。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"その備蓄倉庫として、具体的に安心という意味で、どのような形でどうなっているのかをお伺いしたいのですけれども、お願いします。","respondent":"三宅都市開発課長","answer":"防災倉庫の活用につきましては、地元の町会などと協力し合って使うことにしておりまして、すみません、具体的に何を備蓄しているかというところまでは把握しておりませんが、そのような形で地域の方も使えるような形での活用を考えております。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問","question":"やはり一般質問でも私、質問をさせていただいたのですけれども、お伺いしました。１３７ページなのですけれども、お伺いしたいのですけれども、その辺が気になってお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"昨年度から、１週間当たりコマ数が２時間ほど増えていますので、学校の勉強が充実してきたことで、勉強会に来られる方が減って来ているのだと思います。","id":"exchange-084"},{"speaker":"稲川委員","kind":"質問","question":"水路敷以外で区内に売り払う、売却できる財産というのですか、土地がどの程度あるのか。それと、そういった公共性のない土地に関して売り払うことになったとして、その売払までの流れというのですか、それを説明するよう求めました。","respondent":"井浦土木管理課長","answer":"私ども平成１３年から平成１６年にかけて、財産権が地方分権一括法で区に移管しておりますので、数年かけて調査をしてまいりました。そして契約が整いましたら、所有権の移転登記を行うという手続になってあります。","id":"exchange-085"},{"speaker":"稲川委員","kind":"質問","question":"多分、昨日も多少、経理課長がご答弁されたと思うのですが、土木管理課が一括してというか、土木管理課がご契約をされて、それを売り払いますと言ったら経理課に移るような形になるのか、どういう形でまたぐのかを説明するよう求めました。","respondent":"井浦土木管理課長","answer":"行政財産として公の用に供しているものについては売払ができませんので、まず行政財産としての用途を廃止すると。そうしますと普通財産になりますので、普通財産の管理の部局である経理課が取り扱うという仕組みになってあります。","id":"exchange-086"},{"speaker":"稲川委員","kind":"質問","question":"隣接している区民の方にどうですかと声をかけるというケースもあると思いますし、実際にどういうケースが多いか、説明を求めました。","respondent":"井浦土木管理課長","answer":"年間ベースで平均しますと５件ほどあるのですが、ほとんどが区民の方から私どもの窓口に相談があるといったケースです。","id":"exchange-087"},{"speaker":"稲川委員","kind":"質問・要望","question":"次に１３８ページ、２つ、もう１点が財団法人東京都区市町村振興協会の２点についてお伺いいたします。今回、２５０万円という予算がついておりますので、おそらく一般コミュニティ助成事業であると思いますが、この辺の確認をお願いします。","respondent":"武内地域活動課長","answer":"委員の言われるとおり、一般コミュニティ助成事業で申請をしております。","id":"exchange-088"},{"speaker":"稲川委員","kind":"質問","question":"この助成事業の要綱というのですか、その中の要件を見ますと、事業主体が区市町村が認めるコミュニティ組織となっております。さまざまな区内の、区が認める団体だと思いますが、何でこれは品川区が事業主体になっているのかを説明するよう求めました。","respondent":"武内地域活動課長","answer":"私のほうではこのように理解しております。あくまでも申請者は区になると認識しておりまして、地域コミュニティの町会、自治会等が利用するという認識をしております。","id":"exchange-089"},{"speaker":"稲川委員","kind":"質問・要望","question":"どうぞ、そういうコマーシャルというのですか、もっと区民にアピールしていただきたい。葛飾区の１町会が事業主体になって受けているケースも実際にあるので、区民の皆様にしっかり周知をされるべきだと思うのですが、いかがか尋ねました。","respondent":"武内地域活動課長","answer":"それぞれの地域センターでの地域ニュース等もそういう中で、今後ＰＲを進めていきたいと考えています。今後、そのような体制で１町会の物品を申請できるのかどうかという部分については、研究するということでよろしくお願いします。","id":"exchange-090"},{"speaker":"稲川委員","kind":"質問","question":"以前、１年前にも質問させていただいたのですけれども、宝くじの助成で購入したものに関しては。」とクーちゃんのステッカーを貼るとか、区民の方が、これは宝くじの助成で買ったのだとわかるような表記は実際やられているのか、お伺いします。","respondent":"武内地域活動課長","answer":"それぞれの品物に、そんなに大きくはなりませんけれども、そのような形態で物品に表示はしています。","id":"exchange-091"},{"speaker":"稲川委員","kind":"意見","question":"それで、今年度もまた２５０万円が上限ですが、これは実際に、今回これを申請するときに平成２４年度にどういうものを購入するかというのを明記して、多分申請を出すと思うのですけれども、今年は何をご購入されるか、もう決まっていますかとの意見を述べました。","respondent":"武内地域活動課長","answer":"昨年１１月に申請を出させていただきました。綿菓子機、その他コインソーターというのですか、そのようなものを一括してトータルで２５０万円以内におさまるということで申請を出しています。","id":"exchange-092"},{"speaker":"稲川委員","kind":"意見","question":"同じことがここにも書いてあるのですけれども、平成２４年度も今おっしゃったものを購入するということでいいのでしょうね、きっと。共生の地域づくり助成事業とか８項目あるということなのですが、この２５０万円だけを申請しているのか、説明を求めました。","respondent":"武内地域活動課長","answer":"実際に、この申請の手続は東京都を経由してやるということで、コミュニティということで地域活動課が窓口になっておりまして、委員が言われるとおり、地域コミュニティ関連の申請しかしておりません。","id":"exchange-093"},{"speaker":"稲川委員","kind":"質問・要望","question":"１個しか選択できないというのなら、ぜひこれは活用していただきたいと思うのですが、いかがか尋ねました。","respondent":"武内地域活動課長","answer":"この要綱を今一度、よく確認させていただいて、多数のものが申請できるようでしたら、大いに利用していきたいと考えております。","id":"exchange-094"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ、地域の皆様に資するような事業をしてほしいと求めました。結構大きな額がついているのですが、これについてはどういう形で利用されているのか、簡単に。","respondent":"榎本企画財政課長","answer":"この東京都区市町村振興協会が配分しておりまして、実際にはこれは都内の６２区市町村、それから人口割で全体の都からの交付額を割っているという形。申請する際にはリサイクル活動に充当するということで申請をして、このお金をもらっているという形です。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"次に７１ページ、時間があれば７６ページ、印鑑証明等についてお伺いいたします。国や都からの補助金はあるのかどうかということと、何らかの動きがあれば説明を求めました。","respondent":"齋藤庶務課長","answer":"非構造部材の国からの補助制度ですが、公立学校施設につきまして、それぞれ大規模改造、老朽の改造、耐震補強等、耐震の割合があります。非構造部材につきましても一定の割合で補助金がもらえると、現在聞いております。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問","question":"国からは出るということで伺いました。始まったばかりなので、検討されているのかどうか、この状況がわかれば説明を求めました。","respondent":"齋藤庶務課長","answer":"国からは、繰り返しになりますが、天井材や照明器具落下防止につきまして、それぞれ３分の１を助成していただけると聞いておりますが、都からの補助制度については、今のところ聞いてございません。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問・要望","question":"補助を求めていくべきであると考えますが、声を大にして都に進言していってほしいと求めましたが、いかがか尋ねました。","respondent":"齋藤庶務課長","answer":"非構造部材の耐震化を進めるためには、国だけではなく、都の補助金も活用することが大事だと考えています。都に申し入れをしてまいります。","id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"平成２０年度からこの２００kmという数字が続いております。ここらへんの正誤関係につきまして、教えてほしいと求めました。","respondent":"井浦土木管理課長","answer":"反省いたしまして、平成２４年度予算では埋設物件の種別を洗い出しまして、決算書に対応した分類に是正しています。なお、本件は内訳の分類の仕方でございまして、道路占用料の歳入歳出の総体の額はぴったりと整合しているものです。","id":"exchange-099"},{"speaker":"浅野委員","kind":"確認","question":"このようなミスがあったということですけれども、このミスに対しての責任の所在というのは、課にあるのか、それとも事業部にあるのか、それともまとめている、先ほどありました企画財政課にあるのか、このようなことについても確認のためにお願いしたいと思います。","respondent":"井浦土木管理課長、榎本企画財政課長","answer":"分類コード等、識別記号を振りまして、入り繰りのないように努めているところです。第一義的には所管の課長の責任です。 今、そういう答弁がありましたけれども、やはりこれを編集するほうの責任はこちらにありまして、中身をよく確認して、予算編成のときにきちんと区分してやっていくという形で、今後気をつけていきたいと思います。","id":"exchange-100"},{"speaker":"浅野委員","kind":"意見","question":"大切な予算書ですけれども、１,３００億円以上の中の一部といえども、やはりしっかりとミスのないようにしていってほしいと求めました。この点についても、明細書の訂正をぜひともお願いしたいと思いますが、いかがでしょうとの意見を述べました。","respondent":"井浦土木管理課長","answer":"道路法に基づく正式な、法律的な占用ですので、きちっと占用者の法人の人格という部分につきましても、登記等で確認いたしまして、適正に処置をしていきたいと考えています。","id":"exchange-101"},{"speaker":"浅野委員","kind":"質問","question":"平成２３年度は地下埋設物の中に東電とＮＴＴの部分が含まれていましたけれども、平成２４年は電柱・電線類の中に含まれているのですね。この点について、お伺いします。","respondent":"井浦土木管理課長","answer":"意図ということはございませんで、決算ベースに合わせまして、きっちりと同じ種別のものを同じ中項目ということで分類をするという考え方です。","id":"exchange-102"},{"speaker":"浅野委員","kind":"意見","question":"こちらのほうはかなり細かい数字の積み上げということで、大変な作業かと思いますけれども、やはりわかりやすい記載、そしてまた場所が変わるのであれば、何らかの説明といったら、そこまであれしたら大変かと思いますけれども、わかるような記載をぜひとも心がけてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"大沢委員","kind":"意見","question":"バイクが５,０００円ということですけれども、手元にあります事務事業概要の中の平成１８年度から放置台数がすべて減っております。私自身が考えている予想に対して、現場を見ていらっしゃる区はどのように考えているのか、まず説明を求めました。","respondent":"藤木交通安全担当課長","answer":"放置自転車の状況ですが、その日その日によって若干のばらつきはあろうかと思いますが、総じて見ますとこの１０年間くらいずっと減少しておりますので、今後も減少を続けるのではないかと考えているところです。","id":"exchange-104"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこで、また次の質問なのですけれども、この３,０００円と５,０００円なる金額は、いつ金額については決められたのか。その後、そのような金額についての検討を、さまざまな面で検証あるいは検討されているのかお知らせほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"資料はないのですが、近隣の区市町村などのいろいろな使用料とか保管料などを見ましても、平均的な金額ではないかと考えております。逆に１万円くらい取った場合は自転車の価値もそんなにない、今、この辺が妥当かと考えているところです。","id":"exchange-105"},{"speaker":"大沢委員","kind":"質問","question":"これはいつ決まったのかおわかりにならないということで、おわかりにならないくらい、検討なり検証されていないのですか。どうでしょう。","respondent":"藤木交通安全担当課長","answer":"正確な日にちがわからないというところでございまして、おおむね平成１４年ごろではないかと考えております。こちらの金額につきましては、常に検討はしているつもりではあります。","id":"exchange-106"},{"speaker":"大沢委員","kind":"意見","question":"先ほど検討作業はされていないということで、今、言葉の違いはどこからどう出てこられたのか、もう１回説明を求めました。","respondent":"藤木交通安全担当課長","answer":"具体的に金額を３,０００円から幾らにするだとか、そういう具体的なものはございませんけれども、常に区のそういう財政状況だとか、そういう保管・撤去いろいろな状況につきまして、いい方向に向かうよう総合的に検討しているです。","id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"この事業をしっかりと行ってほしいと求めましたし、区の中で行っている２５０以上の事業の中でも、見直しをしながらお願いしたいと思います。二者択一は難しいかもしれないのですけれども、どちらに重きを置いて、今後この条例を運用し、過料を定めていくのか教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"条例の趣旨は先ほど午前中に申し上げたとおり、区民の信頼に応えていくことです。抜き取りを防止していくことですから、やはり条例で定めております以上、ゼロに近づけていくことが条例の目的だろうと考えているところです。","id":"exchange-108"},{"speaker":"大沢委員","kind":"意見","question":"確かにごみの持ち去りは非常に地味な行為なり場所ですけれども、これに対して、だから余計に区民と接する場所が密であると思います。余計にこの事業に対するやる気、本気度をもっとアピールしなければいけないと思うのですけれども、いかがお考えになりますかとの意見を述べました。","respondent":"太田品川区清掃事務所長","answer":"各１台、パトロールを２人１組で早朝から、早朝からパトロールをしています。ここの地域はパトロールだという、私ども先ほども申しましたように、きめ細かに粘り強くパトロールを実施していきたいと考えているところです。","id":"exchange-109"},{"speaker":"大沢委員","kind":"質問・要望","question":"品川区のコマーシャルをする放送の中で、ＣＡＴＶと品川区の中で、放映するに当たっての何か規則とか指針とかおありでしょうか。教えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"ケーブルテレビの番組放送ですけれども、ケーブルテレビといろいろと、どういった番組を流すかを協議しながら決めているところでございまして、それぞれ個々の番組等に基づいて、放映をしていくところを話し合いながら決めているところです。","id":"exchange-110"},{"speaker":"大沢委員","kind":"質問・要望","question":"マスメディアというのは先ほどうちの山内委員も言いましたように、区長が１０露出しているところ、議会は１あるいは１.５だと思っています。この違いは一体何に基づくものか、教えていただきたい。","respondent":"荒井広報広聴課長","answer":"それぞれの内容に合わせて、出演あるいはカットを選んでおりますので、ご理解いただければと思います。よろしくお願いします。","id":"exchange-111"},{"speaker":"大沢委員","kind":"確認","question":"今あえて質問させていただいているわけで、そうですかでは、議論にならないわけでありまして。だからさっき最初に指針とか何かあるんでしょうかと聞いたんですが、そこのところはないということで、確認をさせていただいていいわけですよね。","respondent":"荒井広報広聴課長、日下部企画部長","answer":"おっしゃるとおり、特に恣意的な編集などをしていることはございませんので、ご理解ください。 そうなりますと当然、そこで大体、区長はいろいろなイベントに積極的に出席をしまして、区としての考え方をいろいろアピールすると。そういう面もありますので、一つご理解をいただきたいと思います。","id":"exchange-112"},{"speaker":"高橋委員","kind":"質問","question":"この拠点室というんでしょうか、具体的な貢献の例、活動の例などを通じてお話ししていただけるとありがたいと思います。ここは登録しないと使用できないとお聞きしていますので、またそういう登録団体は当初よりも増えていて、今後も増えていくんか尋ねました。","respondent":"今井協働・国際担当課長","answer":"毎月１回活動会議を持ちまして、例えばこの間、２月２５日に行いました社会貢献活動しながわの中心的な実行委員会のメンバーともなっております。今後、３月１８日のイベントを通しまして増えていくことを期待しております。","id":"exchange-113"},{"speaker":"高橋委員","kind":"質問","question":"８団体とおっしゃったんですが、どのぐらいの団体が応募されて、この８団体になったのか。そして、今後また新たにそういう団体を募集していく予定はあるんか尋ねました。","respondent":"今井協働・国際担当課長","answer":"昨年の４月に再度募集をかけまして、７月から２団体にご利用いただいておりますが、その際の申し込みは５団体でございました。事務所として使いたいという直接の問い合わせは１団体、そちらの団体も含めて、利用を進めていただいているところです。","id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"今、活動拠点室と交流スペース、協働推進のお話を伺ったんですが、ちょっと話が変わりまして、同じこみゅにてぃぷらざ八潮で講習室、多目的室ですね。お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"そこの講座もそこで行いまして、また、うるおい塾もそこで開催しまして、まずそこの施設を知っていただくと。バスの案内にも、こみゅにてぃぷらざ八潮のご案内をさせていただいたり、いろいろ検討しています。","id":"exchange-115"},{"speaker":"高橋委員","kind":"質問","question":"所管が文化スポーツ振興課、地域活動課という２つの所管にまたがっているんですが、例えば今のようなお話で使用団体が増えていく。そういうときの調整というか、そういうことというのは、どのような流れになっていくのか尋ねました。","respondent":"中川原地域振興事業部長","answer":"私が両方の課を所管しておりますので、そこら辺は調整して、今後、八潮ならではの特色を出しつつ、この施設の有効活用については今も話し合っているところですが、今後も話し合って検討してまいります。","id":"exchange-116"},{"speaker":"高橋委員","kind":"意見","question":"スペースに机を置いて話をする、あるいは交流スペースという形でも、私は可能なのかなと考えています。まだ１年というところですので、今後の展開の中で、ぜひ判断の材料にしていかれるとありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８６ページの子育て支援交付金についてお伺いさせてほしいと求めました。それと、ショートステイのキャパシティーと利用率、どんな場合がまた多く利用されているのかについてもお聞かせほしいと求めました。","respondent":"安井子育て支援課長","answer":"こちらについては、約６００万円ぐらい入っていると思いますので、それ以外の部分が持ち出しになっているという形になろうかと考えています。ちなみに今年度につきましては、１７人の延べ利用者数でございまして、５５泊という形になっているところです。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はここにぜひとも利用できるようにしていただきたいと思って質問するわけですが、今、事業についても簡単にご説明ほしいと求めました。品川区でこの事業を利用されている方がどれぐらいいらっしゃるのかも説明を求めました。","respondent":"安井子育て支援課長","answer":"ひとり親家庭の方の就労支援を、その資格を取る際の生活費相当を支援するという制度でございまして、これは全国的に行われている制度で。ですので、逆にそういう方たちに占有されてしまう形になりますので、望ましくないんではないかなという考え方のもとで行っているところです。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかも、すごい努力をしてこの資格を取ると。そういうところに対して、やはり就労をできるようにしていくのが行政の役割ではないかと思うんですけれども、その点に関してはいかがか尋ねました。","respondent":"安井子育て支援課長","answer":"やはり子育てにおいては重要なんではないかなと私どもは考えておりますので、そういう就労形態も今、病院では用意しているように聞いております。すべて、そういった方たちをすべて受け入れられるかというのは、また別問題ではないかなと私は考えておるところです。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この思いにぜひとも応えていただきたいと思うんですが、いかがでしょうか。品川区がショートステイで受け入れられない、だけど助産師をやっていきたいといった場合に、どういう方法があるのかもお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"お子さんは非常に小さいと聞いておりますので、そこら辺をまず考えるべきなのではないかなと考えているところです。それをすべて受け入れるのは、なかなかこのショートステイ、５人の枠の中ではとても無理なのではないかなと考えているところです。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"助産師になるのは、区は支援できないからやめなさいということなんでしょうか。ショートステイで受け入れていただきたいと思うんですが、区長、いかがか尋ねました。","respondent":"安井子育て支援課長","answer":"あれは定期的な利用も、夜勤が入っているからという話になってしまうと、非常に難しいかなと。個別の事情の中で受け入れる場合があることは、全くないとは言えませんけれども、基本のラインは決して崩さない形になろうかと思います。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１日５人受け入れられるのにもかかわらず、こんな少ない利用率です。品川区でも柔軟な対応を、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"山元委員","kind":"質問・要望","question":"これは両方から助成をしてもらえるのかどうか、１つ目、教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"品川シェルターの利用条件ですが、６５歳以上の高齢者、もしくは障害等級で２級以上の方がいる世帯です。それで、世帯の年間所得の合計が６００万円未満という世帯に対して助成ができるようになっています。","id":"exchange-124"},{"speaker":"山元委員","kind":"質問・要望","question":"品川シェルターは５０万円が限度、低所得世帯が２００万円未満と６００万円未満ということでありましたけれども、もし件数がわかれば。品川区としては、目標としてはどのぐらい設置したいという思いがあるのか、その辺も教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"このマニュアルを、１月に区内の業者を集めまして、マニュアルの説明会をやっております。今後、この業者を登録制等でやっていきまして、簡単に品川シェルターを設置できるような形で、これからも広めていきたいと考えております。","id":"exchange-125"},{"speaker":"山元委員","kind":"質問","question":"２件という、この５０万円限度額の助成をしていただいても、なおかつ自己負担はかなりあるんでしょうか。だから少ないんか尋ねました。","respondent":"品川防災整備担当課長","answer":"品川シェルターの設置ですが、１部屋に設置するのに５０万円程度で大体設置ができます。それで補助が５０万円ですので、実質、ほとんどは補助で負担ができるというふうになっております。","id":"exchange-126"},{"speaker":"山元委員","kind":"質問・要望","question":"そうしますと、負担ゼロということであれば、本当に品川区にも危ない箇所はたくさんありますので、ぜひとも周知をしていただきたいし、現実的に助成でできる件数、今３件とおっしゃっていましたが、あと何件ぐらいまでは設置ができるんか尋ねました。","respondent":"品川防災整備担当課長","answer":"リビングに設置したいだとか、あとは８畳に設置したいとか７.５畳に設置したいとか、なかなか設置に至らないケースもあります。この辺も今後検討していきながら、進めていきたいと考えております。","id":"exchange-127"},{"speaker":"山元委員","kind":"質問・要望","question":"次、１０３ページの国民体育大会開催準備経費ということで、私自身も東京で国体が行われたというのは全然記憶がありません。昭和２４年と昭和３４年にあったということでありますが、どのような思いで計画を立てているのか、その辺をお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"国民体育大会ですけれども、国民体育大会は平成２５年に行います。品川区立総合体育館において１０月の３、４日ということでハンドボールの競技、グラウンドゴルフという競技を天王洲で９月ごろ予定しております。","id":"exchange-128"},{"speaker":"山元委員","kind":"質問・要望","question":"来年の話をすると鬼が笑うと言いますが、いずれにしましても、本当にこのいいチャンスを逃さず、品川区を子どもたち、またお年寄りにこのスポーツの大切さというものを、ぜひともアピールしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"伊藤委員","kind":"質問","question":"今５５が２３区に来るけれども、財源対策をしていく必要があると思うんですが、いかがでしょうか。品川区の見解を説明するよう求めました。","respondent":"榎本企画財政課長","answer":"金額でも２番目、順位でも２番目という形で、まちづくりを進めていくという形もやっております。今、都区のあり方検討もやっておりますけれども、引き続き財調協議会の中でもきちんと確認をしていくという形になっております。","id":"exchange-130"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのことの説明をいろいろお伺いしたんですけれども、復興のために４,８０４億円の市債の発行をした。こういう一定規模の基金を、品川区は大きな災害に備えるために持っていく必要もあると判断するんですが、いかがか尋ねました。","respondent":"榎本企画財政課長","answer":"その４本が大きな柱になっておりまして、柔軟な対応ができるような形で条例を組み立てておりますので、その部分をまずは活用していきたいと思います。","id":"exchange-131"},{"speaker":"井上委員","kind":"質問","question":"私からは、１１０ページの緊急雇用創出事業補助金と、１０ページのやさしいまちづくり推進費についてお伺いをしたいと思います。これがまた東京都で復活した経緯をまずはお伺いしたいということと、どういう見直しを検討されて、実際に行ってきたのかをお伺いします。","respondent":"榎本企画財政課長、川崎生活安全担当課長","answer":"それから２つ目が重点分野の雇用創出事業で、これは２４年度末までということで、新たにできたものです。そういった中で、実際にどれを活用していくかという中で、これは都経由の国の補助という形で財源が確保されている事業です。 今、１日１２時間回っていただいているところを減らす。これを減らすなどしまして、現在のマナーアップのレベルを落とさないように推進していこうと考えているところです。","id":"exchange-132"},{"speaker":"井上委員","kind":"質問","question":"事務事業評価でＣで、見直しというところで、その部分は、効果が同じかどうかわからないですけれども、やることは同じにして費用を落とすということが、見直しの項目なんか尋ねました。","respondent":"川崎生活安全担当課長","answer":"委員がおっしゃるとおり、効果を落とさないように内容を変えて、見直していくです。","id":"exchange-133"},{"speaker":"井上委員","kind":"質問","question":"マナーアップ啓発事業と巡回指導と、時給換算どのぐらいでされているのか、ちょっと説明を求めました。","respondent":"川崎生活安全担当課長","answer":"現在、警備会社に依頼している部分につきましては、主任は時給１,３５０円のところ、これを１,２２８.５円と。そして一般の方、主任以外の方は１,３００円のところ、１,１２３.５円に減らすものです。","id":"exchange-134"},{"speaker":"井上委員","kind":"質問","question":"一般の方というのは、マナーアップ啓発事業のことを言っているんですか。その方たちの時給と、巡回指導というのは注意をする人たちなんだろうと言葉では思うんですが、そこをちょっと別に説明を求めました。","respondent":"川崎生活安全担当課長","answer":"オレンジのジャンパーを着まして、駅前で吸い殻のポイ捨てを拾ったり、空き缶やペットボトルなどを拾う方々。先ほど言いました警備会社に依頼しているほうにつきましては、喫煙禁止地区以外における注意・マナーアップなどの事業をしていただいております。","id":"exchange-135"},{"speaker":"井上委員","kind":"質問・要望","question":"だから、その方たちの時給換算を教えてくださいということ。それぞれで教えていただきたいということで、先ほど１,２２８円とか１,１２３.５円とか言われたんですが、それをちょっと整理していただくよう求めました。","respondent":"川崎生活安全担当課長","answer":"シルバー人材センターにつきましては、時給が１,０００円です。そして警備会社のほうは、先ほどのお話のとおり主任が１,３５０円、一般の方が１,３００円となっているものであります。","id":"exchange-136"},{"speaker":"井上委員","kind":"質問","question":"一昨年の予算特別委員会でも伺ったんですけれども、この目的は何かというところで、喫煙者のマナーアップの向上だと。本当に緊急雇用で創出をされない人たちはどこなんだということで、検討すべきだというふうに、そのことについて何かお考えがあれば説明を求めました。","respondent":"川崎生活安全担当課長、榎本企画財政課長","answer":"今これをやめてしまうと、ポイ捨てが増えてしまうと考えておりますので、この事業は続けていきたいと考えております。今のレベルを落とさないように、限られた財源の中で、この事業を続けていきたいと考えております。ですから、当初考えていたような、ある程度縮小した形での最低限のものにせざるを得なかったのかなというところです。","id":"exchange-137"},{"speaker":"井上委員","kind":"質問","question":"これからもずっとこういう形で進んでいくのか、これを考えていくのかということは、慎重に検討しなければいけない課題だととらえています。今年の都の支出金では７５６万円で、昨年が２,８７８万円と、この差について理由を説明するよう求めました。","respondent":"山崎マスタープラン担当課長","answer":"本年度、りんかい線の大井町駅に内方線ブロックを設置する予定でございまして、４００万円が補助金の歳入として計上させていただいているものです。ホームドアを設置させていただいたり、都の包括補助金の歳入を見込んでいるということで、金額的な違いが出ております。","id":"exchange-138"},{"speaker":"井上委員","kind":"質問","question":"ハードの部分での予算だということで、わかりました。どういった方がメンバーで、そして推進協議会はいつ、年何回行われているのかを説明するよう求めました。","respondent":"山崎マスタープラン担当課長","answer":"警察関係、道路管理者等々で、総勢４５名という構成になってあります。現在は年度のやさしいまちづくりの推進状況について、確認をして協議をする場ということでございまして、年１回開催しているものです。","id":"exchange-139"},{"speaker":"井上委員","kind":"確認","question":"前に伺ったときに２月に開催されるということだったんですが、本当に今言われたような報告・確認でしか終わらなくて、時期的な問題で何か考えはないか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"ここ２年は２月に開催しておりまして、特に開催時期を２月に固定しているものではございませんので、ここは改善あるいは研究する余地があるです。ただ、目的が、その年度の進捗状況の確認ということもありました関係上、年度末にということになってあります。","id":"exchange-140"},{"speaker":"西本委員","kind":"質問","question":"そうすると、その意気込みはどこであらわれるんですかということなんです。これから下がる考えなのか、そうすると品川区として、ここはどういう形で予算立てをしていくのかということについてお聞きします。","respondent":"高森税務課長、安藤文化スポーツ振興課長、齋藤庶務課長","answer":"予算上２５％ということで、実は去年も同じ数値でございまして、予算上の数値ということでご理解いただきたいと思います。… １年間ここをやっていきまして、美術工芸室を使う方は本来的にすぐ、いきなり美術工芸室を利用して粘土をいじるということができないと思います。若干… 勉強会に参加されるお子さんの数が少なくなっているので、その分の諸収入が減っている見込みで算定をしております。","id":"exchange-141"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺の区の見方といいますか、分析というのが、どういう形でされているのかをお聞きしたいと思います。都のほうの考え方としては、この事業に関しては前向きに考えて、予算はきちっと補助という形では来るのかということだけ、お願いします。","respondent":"安藤文化スポーツ振興課長、高森税務課長、齋藤庶務課長","answer":"それで１年返って、我々も試行錯誤を繰り返しながら、皆さんに周知をしていきながら、いろいろな手を使って事業の効率を上げてきたところです。… そういうことも勘案しまして、財政当局と調整を行いながら、予算については組み立てているということでご理解をいただきたい。このように思います。ちょっと説明が足りなくて失礼をいたしました。","id":"exchange-142"},{"speaker":"武内委員","kind":"質問","question":"それから９３ページと１１３ページにそれぞれ出ています、住宅・建築物耐震化支援事業の２つについて、お伺いしたいと思います。密集住宅市街地整備促進事業ですと、国のほうが約３倍、都のほうは２億円ぐらいですかね。","respondent":"品川防災整備担当課長","answer":"用地の取得、何とか見込みが立ちそうなので、今回予算要求で上げております。先ほど国のほうで説明したようなものと思っていただければと思います。","id":"exchange-143"},{"speaker":"武内委員","kind":"質問・要望","question":"都の事情もあると思いますけれども、頑張っていただいて、安く購入していただきたいなと要望しておきます。少なくともこの２年の間に達成できるような形で予算化はしなきゃいけないと思っているので、その辺のところだけもう１回お聞きしたいと思います。","respondent":"品川防災整備担当課長","answer":"東京都と連携しまして、東京都と一緒にこの特定緊急輸送道路の説明会等を行いまして、いろいろ啓発に努めております。それから、かなり費用は高額になりますので、東京都が銀行といろいろ締結しまして、融資等もご用意しているという状況で進めていっている状況です。","id":"exchange-144"},{"speaker":"松澤委員","kind":"質問","question":"残りを都が２分の１、区は２分の１だけれども財調で補完されてゼロというお話も伺っているんですが、それが正しいのかどうか。３年ですか４年ですか、期限が来てしまうというお話も伺っているんですけれども、その辺についてもお伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"補助率ですが、密集住宅市街地整備促進事業のほうは、用地購入費としましては国費が２分の１、都費が４分の１です。片や防災生活圏の促進事業につきましては、国が３分の１、東京都も３分の１という内訳となっております。","id":"exchange-145"},{"speaker":"松澤委員","kind":"意見","question":"区の持ち出しについて、財調で補てんされるかどうかとの意見を述べました。","respondent":"榎本企画財政課長、品川防災整備担当課長","answer":"まちづくり事業費の中で、ここの部分の補てんが入っております。 防災生活圏のほうの期限ですが、戸越、豊町地区に関しましては、平成２７年度までとなっております。","id":"exchange-146"},{"speaker":"松澤委員","kind":"質問","question":"やはり用地取得ですから、質問しているんですけれども、三丁目。実は２月１９日に西品川地域の密集住宅市街地整備についての、これが説明会ですか、懇談会ですか、開かれたというお話も聞きました。","respondent":"品川防災整備担当課長","answer":"それから、西品川地区の密集事業ですが、こちらは委員おっしゃるとおり、長期計画で予定をしております。平成２１年で終了予定を考えていたんですが、これを一つの出発点としまして、今後の密集事業も少し考えていきたいとは思っております。","id":"exchange-147"},{"speaker":"松澤委員","kind":"質問・要望","question":"防災広場は広ければスペースがあっていいわけですから、サッカーでボール遊びしても、何ら広場としての外観は変わらないと思うんですね。そこについてのご意見を伺いたいと思います。","respondent":"品川防災整備担当課長","answer":"それから鳥かごの件ですが、こちらは具体的に西大井の用地が取得できた後に、地域の皆様と公園検討会というものを行います。ここで、どういう公園にしていったらいいかということを十分議論しまして、検討をしていきたいと考えております。","id":"exchange-148"},{"speaker":"松澤委員","kind":"質問","question":"次に、木密地域不燃化１０年プロジェクトについてお聞きしたいと思います。やはり区長は施政方針の中で、さらに今後は東京都の木密地域１０年プロジェクトと連携し、これの内容と概要についてお伺いをしたいと思います。","respondent":"品川防災整備担当課長","answer":"それから２点目の、こちらはおおむね東京都施工の予定になっている都市計画道路を行っていくという形で東京都が言っております。それから３番目は、西品川で東京都と一緒にやりました、東京都の方が地域の意見を聞いてみたいという場をつくってやっていくものになります。","id":"exchange-149"},{"speaker":"松澤委員","kind":"質問・要望","question":"３つの地域に最初に選ばれるかどうかというのはまだわからないですけれども、その次には５０カ所あるということで、あるいは林試関係でしょうか。温水プール使用料について、温水プールがある場所は何カ所あるかをお教えほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"学校の温水プールといたしましては、日野学園、戸越台中学校、伊藤学園、八潮学園、品川学園です。荏原文化センターに温水プールがあります。","id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、６カ所ということですね。これを管理というんですか、委託というんですか、どういう形で運営されているのかについてお聞きしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"それと伊藤学園、八潮学園、品川学園については、それぞれビル管理業者に委託をしております。荏原文化センターについては、監視員のみ、監視員の業者に委託をしております。","id":"exchange-151"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、民間とスポーツ協会と、荏原文化センターが監視員のみ。費用は安くていいんだという考え、２通りあると思うんですけれども、品川区はどのように考えているんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"やはり費用対効果も考えながら利用料を徴収していきたいと考えています。","id":"exchange-152"},{"speaker":"松澤委員","kind":"質問","question":"当然２カ所あるわけですから、それの利用率というんですかね、どっちが効率よく運営されているか。こっちのほうがはやっているなとか、こっちのほうが内容がいいなというのはあると思うんですが、それはどうお考えか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"今お答えしました６カ所についてそれぞれ、実際には窓口の運営だとか、それから監視員もいます。ですから、地域に近い人たちが、地域の方を指導しているということにもなろうかと思います。","id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"水泳連盟というのは品川区全体の団体なんでしょうか、これと同等なんでしょうか。その辺の考え方、お願いします。","respondent":"安藤文化スポーツ振興課長","answer":"品川区水泳連盟ですけれども、水泳連盟は財団法人品川区スポーツ協会に加盟をしている加盟団体です。ですから、水泳に関して品川区全体を網羅したと申しましょうか、そんな団体です。","id":"exchange-154"},{"speaker":"松澤委員","kind":"質問","question":"それともう１つは、一般開放をやるのに、効率を考えるならば半分でいいんじゃないかと。このような思いは課長のところに届いているんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"区内６カ所それぞれに、形として一般開放、それから団体貸切、教室をやっております。それを、バランスを考えながら設定しています。","id":"exchange-155"},{"speaker":"松澤委員","kind":"質問","question":"お互いにそれぞれの団体が一生懸命、区民のためにということで頑張っているんでしょうから、調整をよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"もし所得制限ができてしまって９６０万円以上の世帯の数、割合でもいいんですけれども、教えていただけたらと思います。子育て世帯から、こういったものが減らされて困っているとか、そういった声がもしあればお聞きしたいんですけれども。","respondent":"安井子育て支援課長","answer":"新しく４月から、２万７,０００世帯ぐらいが対象なのではないかなと考えていますが、約１５％ぐらいをとりあえずは見込んでいる状況です。そういうところからしますと、約４,０００世帯ぐらいが所得制限にひっかかる可能性があるかなと考えています。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問","question":"子育て世帯から届いている声があればと思ったんですけれどもあるんか尋ねました。","respondent":"安井子育て支援課長","answer":"２月に特別措置法分の支払を行いましたけれども、「これから来年もこのまま行くんですか」みたいな話をお問い合わせのときにいただいています。早目に区民の皆様、子育て世帯の皆様にご通知を差し上げたい、お知らせをしてまいりたいとは考えております。","id":"exchange-158"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、これが６００万円の世帯であれば１２万円削られていくということで、経済全体の低迷にもつながりかねないといった指摘もしているんですね。これからそういうふうになっていく子育て世帯をどう見て、どう考えるか、お聞かせほしいと求めました。","respondent":"安井子育て支援課長","answer":"現在こちらは国で議論がされているところですので、私どものほうでこれについてコメントするというのは、ちょっと控えするのが適当じゃないかと考えています。","id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、区の職員の皆さんも本当にご苦労されているという話も伺ったんですけれども、あらゆる子育て支援を充実させていくことが必要だなと。経済的に支えていくことが必要だなと思うんですけれども、いかがか尋ねました。","respondent":"安井子育て支援課長","answer":"それについては、まず国のほうで、はっきりとした形で決めていただくのが大事なんではないかな。それ以降、私どもで現物給付であるとか、そういった部分について考えていくという形になるんではないかと考えております。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"未来ある子どもたちですので、未来の宝として、いろいろな支援を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"私は歳入全般についてお伺いします。予算を見直すべきだと考えておりますが、何か事業の削減等をしているのか、それについてまず説明を求めました。","respondent":"榎本企画財政課長","answer":"やはり事業の見直しというのは継続的にやっていかないと、なかなか一つの事業が１００％要らない、１００％要るという形にはなりません。もしくはパソコン、ＩＴ機器の再リースをやはり継続することで、費用を生み出してきているところです。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"だってお金がないじゃないですか。それに備えた対策というのは、企画財政課でも私は考えておられるかと思うんですが、その辺についてご見解を説明するよう求めました。","respondent":"榎本企画財政課長","answer":"委員から、その破綻をしないように進めていかなきゃいけないというのが自治体の立場であり、国の立場だと思います。そのような形での対応を考えていきたいと考えています。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"それよりももっと心配なのは、基金の大半は国債じゃないんですか。国がどうなるか、どう変わるかわからないけれども、それにならないようにただ努力するということだけで済むんか尋ねました。","respondent":"榎本企画財政課長","answer":"基金の中で国債を持っているのは、それなりの利率があるからということと、安心な国債であるからということで持っているわけです。そうでなければ、やはり基金の利子収入というのも大事な財源でありますから、そういうもので運用しているという形です。","id":"exchange-164"},{"speaker":"須貝委員","kind":"意見","question":"毎年約１億円ぐらいの歳出、これは特定の人に多額の金額を、数十万単位の金額を補助している。私はぜひ、この品川区だけはしっかり守って、これからもやっていってほしいんですが、それだけ最後に述べさせていただきまして、私の話は終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-165"},{"speaker":"阿部委員","kind":"質問・要望","question":"この総合交付金の評価と課題と言ったら何でしょうか、自治体としてこういう形で交付金が入ってくるということの評価、それから課題。そういったお考えがあれば教えてほしいと求めました。","respondent":"榎本企画財政課長","answer":"それから平成２４年度につきましては、当初は区市町村への交付という形を予定されていたんですが、全体としては増額の形になっております。国ではなく都道府県がその全体枠の配分をある程度やっていく形になりますので、その辺での調整が課題になろうかなと感じております。","id":"exchange-166"},{"speaker":"阿部委員","kind":"質問","question":"この交付を受けているということなんですが、品川区としては、これは独自につくるような仕組みにはなっていないんでしょうかね。そこに品川区の意思はどの程度かかわっているものなのか、その計画のつくりようについて教えてほしいと求めました。","respondent":"榎本企画財政課長","answer":"ここのメリットの一つでありますけれども、事業実施計画を都道府県が出すことで、いわゆるひもつき補助金にはなっていないという形です。計画の都道府県のもととなる事業について、都に選んでもらいたいという形でのいろいろな工夫をした事業を出していくという形です。","id":"exchange-167"},{"speaker":"阿部委員","kind":"提案","question":"品川区としてここに重点を置きましたとか、こういうものは品川区独自で提案しましたとか、そういったものはあるんでしょうか。わりとそれは、むしろ東京都のほうでまず枠組みをつくって、それにできるだけ多く乗っかっていくというスタンスになっていくのか、説明を求めました。","respondent":"榎本企画財政課長","answer":"例えば今回たしか、なくなってしまっていますけれども、大井林町の整備のときにはこの社会資本整備総合交付金を使いまして、その整備についてやると。","id":"exchange-168"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういった意味で、東京都あるいは２３区という中で、自治体としての意思が反映されるような都との関係になっていっていただきたいと考えています。簡単に解説してほしいと求めました。","respondent":"榎本企画財政課長","answer":"再開発組合についてはその地域の中でしか整備ができませんので、周りの整備を区が発注して行う、という事業がこの中に入っております。それがほとんどのものです。","id":"exchange-169"},{"speaker":"阿部委員","kind":"質問","question":"国債の満期の償還差益で７,０００万円ももうかるんだったら、多分この雑入はこれだけで７,０００万円というわけではないかと思います。これは主にどういったものがあるのか、簡単に説明を求めました。","respondent":"榎本企画財政課長","answer":"ここの部分で、国債満期に伴う償還差益の分につきましては１,１９３万円という形です。は自動販売機の設置の運営事業収入ですとか、そのほか、ほかの今までの節に区分できないものをまとめて「等」という形で表現をしています。","id":"exchange-170"},{"speaker":"阿部委員","kind":"質問・要望","question":"雑入、なかなかこれがどういう性格のお金なのかがわかりにくいものが多いですので、そこは説明の部分を拡充して表記をしてほしいと求めました。いかがか尋ねました。","respondent":"榎本企画財政課長","answer":"最終的に区に入ってきているお金をどう区分してあらわすかということなので、そのことについてはまた十分検討して、工夫を図っていきたいと思います。最後の雑入の雑入に入ってくるという形なので、その時々に応じてわかりやすい工夫を図っていきたいと思います。","id":"exchange-171"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後に、幼稚園保育料についてお伺いしたいと思います。その前に、区としての認識をまず教えていただきたいということと、その対応について説明を求めました。","respondent":"吉岡保育課長","answer":"アッパーが３５人ということになってありますので、平成２４年度につきましては最大限３５人まで広げて対応をとったというのが１つあります。","id":"exchange-172"},{"speaker":"阿部委員","kind":"意見","question":"私立というのは直接手を入れることがなかなか難しい面もあると思いますので、今後きちんとした対策を考えていくべきであると考えます。この後は教育費でまた続けますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-173"},{"speaker":"若林委員","kind":"質問・要望","question":"平成２２年、平成２３年が今どうなっているのか、金額等で教えてほしいと求めました。当然これに対する平成２４年度の歳入に関して、対策をどのようにしっかりととられているかを併せて確認します。","respondent":"榎本企画財政課長、高森税務課長、柏原住宅担当課長","answer":"平成２３年度の各区算定のときに大きく下がった関係がありまして、平成２４年度の見込みがどれぐらいで見込めばいいのかというところがあります。… １人当たりの単価につきましては、平成２３年度より２,０００円減るという見込みを立ててございまして、１１万円という予定です。… 昨年、同じ時期で今の形を申しますと、５００万円ほど建設型のほうで若干増えつつある状況があります。","id":"exchange-174"},{"speaker":"若林委員","kind":"質問","question":"そこで、ちょっと唐突ですが、今まで品川区でマラソン大会の企画を検討されたことがあるかどうか、お聞きしたいと思います。これも一つ、今具体的にどういう検討をして進められて、しようとしているのかというのはお聞きしておきたいと思います。","respondent":"柏原住宅担当課長、安藤文化スポーツ振興課長","answer":"民間賃貸住宅の検討です。特に、区の中で住宅にお困りの方については、民間賃貸住宅空きストックがありますので、これを有効に活用していこうということで検討しています。 マラソン大会ですけれども、品川区は区民スポーツ大会の中でマラソン大会をやっております。しかし、距離にしまして１０km、５kmということで、フルマラソン、ハーフマラソンはやっておりません。","id":"exchange-175"},{"speaker":"若林委員","kind":"提案","question":"これはどっちに向かっていくかな、課題になると思います、今後。そういう意味では、これから２６号線も通りますので、そういった品川区の回遊性という意味で提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-176"},{"speaker":"須藤委員","kind":"質問","question":"減災、そういうものに対して国とか都で、トータルではどのくらいの金額が補助金として計上されたんでしょうか。国で７項目、都で５項目という形で、そんな計算でいいのかどうかということを聞かせてもらえればいいと思います。","respondent":"榎本企画財政課長","answer":"国と都を合わせて、大体たしか３０億円ぐらいあるかなと感じております。","id":"exchange-177"},{"speaker":"須藤委員","kind":"意見","question":"そうした中で見ていったときに、１つは先ほど稲川委員が言ったかな、それがストレートにうまく区の事業と合致するのかどうか。そういうことをやっていらっしゃるのかどうかということを聞かせてもらいたいと思いますとの意見を述べました。","respondent":"品川防災整備担当課長","answer":"補助金のほうで国と直接というお話かと思いますが、基本的に補助金は東京都を通じて、国ともやりとりをしているということで、あまり直接、国と補助金のやりとりというのはしてございません。","id":"exchange-178"},{"speaker":"須藤委員","kind":"意見","question":"参考資料で見てくると、都からの補助金が１億円幾らで、委託金が６,０００円ですよと。そのあたりを聞かせてくださいとの意見を述べました。","respondent":"榎本企画財政課長","answer":"最終的には都を経由してくるという事業もありますので、その辺は大分、国も柔軟になってきたのかなという形です。ある程度そういうパイプづくりもしながら、情報交換しながら、よりよい事業ができるようにという形での工夫を図ってきているところです。","id":"exchange-179"},{"speaker":"須藤委員","kind":"意見","question":"１４０ページの災害救助負担金というので、１千万円余の金額なんですけれども、このあたりはどういう計算で考えられてきているのかなと。このあたりを聞かせてくださいとの意見を述べました。","respondent":"榎本企画財政課長","answer":"国がこの求償で支援をするものについては、被災地の直接的な支援、もしくは被災者を支援した場合という形でのものに限られています。今までのこの分については第４回求償分までの請求で、１月３１日までの分が入っておりますけれども、さらに求償を続けていくという考え方です。","id":"exchange-180"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほど企画財政課長が国の動向がはっきりわからないと、予算の上でなかなか難しい点があるというお話もされていました。常にアンテナを張りめぐらして、また補正でもしっかり持っていけるような仕組みをつくっておいていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":115687,"voices":422}},{"id":"h24-20120308-3","meetingId":"h24-c-budget","date":"2012年3月8日","dateIso":"2012-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"私は、それから１４７ページの情報システム運営費、それから１７８ページの防災対策費に関連して質問いたします。これはこのとおり読めば、歳入の欄にはこの売却したお金が入っていないんですが、それはなぜでしょうかということをまずお伺いいたします。","respondent":"久保田行財政改革担当課長","answer":"さまざまな観点から検討を重ねてまいりましたが、区の方針としては、現在売却を視野に入れた検討を進めているです。売却仲介料と書いてありますけれども、今後売却に向けて検討を進めていく上の事前調査ということで予算計上させていただいているというものです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"提案","question":"ちゃんと議案を提案していただいて、仲介料にこだわって申しわけないんだけど、この表現がいけないんですよ。このことについてはきちんとこれからについての対応策をお伺いしておかないと、改めてこういうことに対する品川区の対応の確認をお願いいたしますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"条件が整いましたら、議会への報告なしに売却等を進めるものではございませんので、そこの点はご理解をいただければと思います。今後このような誤解を招くことのないよう十分注意をしていきたいと考えています。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"それから１４７ページ、情報システム運営費に関連をしてですけれども、品川区のデータのバックアップに関連してお伺いいたします。すみません、総務委員会で視察にお伺いした市では、それから外部委託ですから外部との回線の接続も避けることができたという話を聞いたんですよ。","respondent":"秋山情報システム課長","answer":"その辺を使いまして、万が一のときには運用ができる状態であるということは考えてあります。データセンターにつきましても、庁舎とデータセンターでのバックアップの体制というので現在のところ対応しているというふうに考えてあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認するんですけど、それから外部にもちろん委託するのはいいんだけど、回線で結ばれているわけじゃないですか。わざわざ外に出すよりは、耐震化になったというふうに品川区が言っているわけですから、もう一つ踏み込んだ答弁を改めてお願いいたします。","respondent":"秋山情報システム課長","answer":"データセンター内でのバックアップは当然リアルタイムでとられているですけれども、庁舎のほうでは、１日分を夜間にという形で運用しております。バックアップを庁舎のほうで１日おくれですけれども、万が一、そちらのほうで対応ができるということで考えてあります。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"そうしたら、現状でも１日おくれなんだけれども、品川区内で対処できるという確認がとれましたので、わかりました。この対象が品川区民３５万人のみならず、その瞬間に品川区にいる方々すべてに対して対処していかなきゃいけないという大きな課題なわけですから。","respondent":"中山防災課長","answer":"委員ご指摘のとおり、私どももそう思っておりますし、そう願ってあります。共助が２で、公助が１という割合が取りざたされておりますけれども、自助の割合を多くしていただくということが一番だろうかと思います。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"すごく言っていることは正しいんだけど、もっと、今挙げたのはいろんな方面に出て、いろんな方面の課題があるわけじゃないですか。だから、そのことについて、今の答弁、もちろんあるんだけど、さらに進んでいくという決意というかな、思いを聞かせてください、お願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"確かに委員おっしゃるように、ハードだけではなかなか難しい。そういう意味では、各関係機関との連携を引き続き強化して、拡大していくという考え方の中で一応きちっとした対策を進めていきたいと考えています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"具体的なことを２点お伺いしますけど、災ステと言っているらしいんですけど、これが都内で８,８００カ所ある。お願いいたします。","respondent":"中山防災課長","answer":"そこに災害時帰宅支援ステーションにリンクを張ろうというふうに考えてあります。それで、なおかつ帰宅支援ステーションなどを記した主要駅付近の地域ごとに拡大地図については張り出すことを意識しておるところです。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"だから、やっぱり紙ベースと言ったらいいんでしょうかね、ここだったら区役所のところに吉野屋がありますよね。これは品川区内のことですから、ぜひ関係部署等の確認をとっていただいて、そのことについての答弁もあわせてお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、いろんな角度の中でそういう紙情報としてもきちっと伝えられるようにという方向で検討してまいりたいと考えています。それと、首都高の話ですけれども、状況を把握して、きちっとした情報を伝達できるようにしていきたいと思います。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問・要望","question":"３が出て、完結をしたというふうに確認をしておりますけれども、困難な中で編集方針をさまざま工夫して完成させた。そこでお尋ねなんですが、民間事業者の斬新なアイデアと企画編集力を活用とありますけれども、その主な特長を教えていただきたい。","respondent":"諸岡総務課長","answer":"特にデジタルメディア等を検討いたしまして、統計等もその中に入れるために収録いたしまして、区民生活のアーカイブ的な性格を持ったようなものです。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"そういう観点で幾つか確認をさせてほしいと求めましたが、品川区のツイッター、昨年の１２月１日から本格開始でありました。予算書のどこに反映されているのかなという確認と、メルマガも今４種類行っていると思うんですが、その辺をまず説明を求めました。","respondent":"荒井広報広聴課長","answer":"現在特に予算書に反映するところではないのですが、ホームページ等経費の中に含まれているというふうに考えていただければいいかと思います。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"それからあと一つ確認なんですけれども、情報発信としての運用ということで今確認できましたが、あそこに今何が記載をされているか教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"予算の枠組みといいますか、そういったものとしては、ホームページ等情報発信の部類ということで、先ほどお話をさせていただきました。ツイッターのプロフィールですが、プロフィールについては、確認をいたします。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"そのうち１６区がプロフィール欄のところにこのような記載があるんですね。実施されている１７区中１６区、ここにもそうした丁寧なご案内を入れたらどうかなというふうに思いましたけれど、どうか尋ねました。","respondent":"荒井広報広聴課長","answer":"早速ご意見を参考にいたしまして、プロフィール欄について充実させていきたいと思います。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"ぜひ品川区でもフェイスブックを活用したらどうかというふうに要望しておきたいと思います。代表質問で確認しましたけれども、その検討状況、今何か変化があれば教えてほしいと求めました。","respondent":"中山防災課長、高山防災計画担当課長","answer":"備蓄品の備蓄場所については、それぞれ１２カ所に異なって置いておりますので、細かい説明は少しできない状況にあります。再開発組合、北品川五丁目第一地区市街地再開発組合につきましては、協定が最終段階に来ているところです。 マークについては、現在のところはまだ検討の途上ということで、検討の課題とします。それから分散備蓄に努めておりますので、若干のスペースを確保しておりますので、分散備蓄を一層進めてまいりたいと考えております。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"主なものがもし今現段階である程度あれば、加えて、新たに何か盛り込まれるものがあるかどうか。それからあと、地域防災計画の内容を反映とありますので、配付時期、大体で結構ですので、わかれば教えてほしいと求めました。","respondent":"中山防災課長","answer":"現在のものを基本的には踏襲しながら改訂を進めてまいりますけれども、委員からもご提案のありました家庭内ディグも掲載を考えているところです。配付時期につきましては、年度末になろうかと思います。","id":"exchange-014"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区の平成２４年度の予算も、前年から比べましてマイナス３.８％、５２億８,７５９万７,０００円の減。１４億１,２６０万８,０００円ということ、この防災対策費、ちょっといろんな項目があるのでわかりやすく教えてほしいと求めました。","respondent":"中山防災課長","answer":"それから、医療救護体制整備費、これは区内１３カ所の救護所に配備する医療機器の購入費および医薬品のランニングストックに要する経費です。それから、災害時要援護者支援経費、これは要援護者支援にかかる経費が中心です。","id":"exchange-015"},{"speaker":"木村委員","kind":"意見","question":"そして、消化剤、薬剤詰め替えですけれども、３種類あります。品川区内には区が設置している５,８００本の消火器があるですが、どの地域にはこの中身がいいとか、そういうのはありますかとの意見を述べました。","respondent":"中山防災課長、片田防災まちづくり事業部長、山口防災安全担当課長","answer":"薬剤の詰め替えのあっせんも行っております。区民の方が既に……。消火器、平成２２年度末現在で約５,７００本強ということで、その数字です。ただ、一定のスパンの短い状況の中で設置しているというような状況で… 先ほど消火器の年限の話、最近の製造されたものは１０年で交換したほうがいいというような決まりになっております。","id":"exchange-016"},{"speaker":"木村委員","kind":"意見","question":"８年から１０年ということですけれども、５,８００本と言いましたが、５,７００本ですね。せっかく５,７００本という消火器を区が配置していても、このことに対して、区はどのように対処しているのか説明を求めました。","respondent":"中山防災課長","answer":"消火器の使用方法については、各地区で毎年行われております総合防災訓練において、必ず模擬消火器による消火体験ができるコーナーを設けてあります。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問","question":"そして、本会議の２日目に一般質問で、区長は木造密集地域にもっとたくさんの消火器の設置を考えているとの答弁があったと思います。このことに対して区のほうの見解というんでしょうか、間に合うのかどうかということを説明するよう求めました。","respondent":"片田防災まちづくり事業部長","answer":"それに対してきちっとした対応がとれるように日頃からの準備をしておかなきゃいけないと、やはりきちんと一つずつその課題に対して考え方を示して対応を行っていきたいと、このように考えております。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"標準価格で１万２,０００円以上するものが、あっせん価格で５,９００円、そこからまた品川区が１,４００円を補助してくれる。４,５００円と言わずに、木造密集地区に対しては行政のほうですべて負担をするようなお考え、そういうのはいかがか尋ねました。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"木造密集地域といいますと、約１１万の世帯があります。これに５,９００円のものを掛け合わせますと６億５,０００万円ほどの経費を要するということになりますので、現実問題としては困難かと思われます。特に密集地域については８０ｍから１００ｍの間隔で、それ以外の地域よりも現実問題としては密度を高めて消火器を街頭消火器として配置してあると。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"品川シェルターのほうは５０万円の補助金がありますけれども、今のところ執行しているのが３件ですが、これが３０万円ですか。そういうこともできましたら、もっともっと密度を濃くするというお考えがあるかどうか、それを最後に聞きたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"区のほうとしては、さまざまな政策を地域ごとにバランスよくやっていると。それぞれの施策を有効かつ的確にＰＲしながら、区としては進めていきたいと、このように考えております。","id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"もしそういう気持ちの、どのような気持ちで毎日の生活をこれから送らなければならないかということを考えますと、大変なお考えだと思います。終わりにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は一般会計の１５１ページ、１５９ページの人権関係と１８３ページの防災体制についてお伺いいたします。第１３期の男女共同参画行動計画推進会議は今年で終了のはずなのですが、新しく第１４期が立ち上がるということなんでしょうか、ご質問いたします。","respondent":"中山人権啓発課長","answer":"お尋ねの男女共同参画行動計画推進会議ですが、第１４期、来年度の６月からスタートの予定です。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２２年度と平成２３年度の男女共同参画センターの共同参画会議室の午前、利用率はどのぐらいだったのでしょうか、お尋ねいたします。平成２３年度は暫定的な数字でも結構です。","respondent":"中山人権啓発課長","answer":"暫定的な今時点、平成２３年度の数値ですが、すみません、中間で、前半期でとっているものでよろしいでしょうか。これは午前が４７.７％、午後が５４.０％、夜間が２５.６％ということになっております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２４年度の予算額の微増というのは、実績見合い上の計上なのでしょうか。１５９ページに記載してあります人権の花運動というのは一体何なのでしょうか、それもあわせてご質問したいと思います。","respondent":"中山人権啓発課長、荒井広報広聴課長","answer":"この男女共同参画センターの活性化についてということで諮問させていただいたところです。随分ＤＶ相談が増えてまいりましたので、来年度は毎週１回ということで、その分の増えた経費が予算上反映されているものです。 人権の花運動につきましては、昭和５７年４月より開始されたものです。人権の花ということで、花を植える、その花の種のための経費となっています。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に、１８３ページの防災対策についてお伺いいたします。このアレルギー用の粉ミルクなんですが、これは具体的にはどのような商品なのか尋ねました。","respondent":"吉岡保育課長","answer":"今アレルギーをお持ちのお子さんが増えている状況ですが、中にはミルク、牛乳に対するアレルギーのお子さんもいらっしゃいます。アレルゲンとなるようなものを除去した形のアレルギーのお子さんでも飲めるような形になった粉ミルクというふうに理解しております。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"なぜこのようなことをお聞きしたかといいますと、今保育課長がおっしゃったように牛乳アレルギー用のミルクということとしまして話を進めします。あるいは昭和大学とか医師会とか薬剤師会とかというような専門家とよく相談して、連携して、きめの細かい対策をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私からは１８３ページの災害時要援護者支援経費にかかわって、防災計画上の福祉避難所の位置づけを中心に伺いたいと思います。伺いたいのは、まず学校ではなく、直接に福祉避難所もよいとした理由、ここに込められたこの間の教訓や理由を伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"地域の方はどういった行動をとるかということを考えた場合に、こういったところも日頃の生活の中で地域の方は、そういった認識をしております。そういう実態をかんがみて、特別養護老人ホーム等でも来た方についてはお預かりするというような考え方です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、この福祉避難所に避難される高齢者や障害がある人の人数をどう見込んでいらっしゃるのか。二次避難所の収容人数が１,６５０人、現時点でどのぐらいの受け入れを見込んでいるのか、どこを目指していくのか伺いたいと思います。","respondent":"高山防災計画担当課長","answer":"１,６００名というのは、当初見込んでおる施設で割り振った上で、１,６００名程度の収容が可能だろうといった考えに基づくものです。災害の対応、また避難者の状況に応じまして、順次開設する二次避難所の規模を拡大すると、そういった余地は残しています。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう中で、３４０人分の備蓄とはどういう意味なのか、今後どこを目指していくのか、その目標を伺いたいと思います。地域の高齢者や障害がある方は避難を希望すると思うんですけれども、シルバーセンターにも備蓄が必要だと思いますが、この点も伺いたいと思います。","respondent":"高山防災計画担当課長、原高齢者福祉課長","answer":"福祉避難所の考え方ということで、発災直後の状況に対応できるような形で最低限のものを備蓄する方向で、今分散備蓄を進めているところです。要介護状態の方が来ましたときに、なかなかベッドを当初から何百人分も施設の中に置くというのは現実的な対応ではございません。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"運営体制についても伺いたいんですけれども、火災ではなくて大震災を想定した福祉避難所の運営訓練というのは行ったことがあるのか伺いたい。そもそも福祉避難所の運営計画や運営マニュアルというものが、各法人や品川区に存在しているのか伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"それから今回の３.１１を受けまして、施設のほうでも機敏な対応をとったところですけれど、日常的に想定でき得る訓練を積んでいるです。我々職員だけでは対応できませんので、今検討中です、一定応援が来るまでの間対応できないかというようなところも具体的に検討。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる施設火災を想定した訓練はしているけれども、大震災を想定した福祉避難所の運営訓練というのは行われていないということなんでしょうか。まずそこが大事だと思うんですけども、しっかり進めてほしいと求めましたが、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"福祉避難所の関係は、区の職員が救助２部ということで、現場に出向いて福祉避難所を開設するという形になってあります。そういった意味では、マニュアル等をさらに準備する形でいざというときの対応ができるように準備をしてまいりたいというふうに思っているところです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"しっかりとそのまずマニュアルをつくって、それに基づいて訓練を行って、いざ震災が起きた際の福祉避難所の運営を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"１９０万円余の予算は去年と変わらずというところで、それでこの質問をしてみたいなと思ったんですが、高齢者の婚活ということなんですよ。というのは、６５歳以上の方々がこういったところになかなか相談しづらいという部分もあるし、現状とそれから今後の展開を伺いたいなと思います。","respondent":"武内地域活動課長","answer":"過去に５０歳代の方が実際に抽選で当たった方もいらっしゃるんですけども、そういった意味で、非常にいいアイデアだなというふうに思います。平成２４年度につきましては、さまざまなやり方を今検討していく中で、参加できるような形をとれればなというふうに考えます。","id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"もちろん今もそうなんですが、そういった状況で、税収に大きく響いてくるということで、今後の品川区の人口の推移というものを伺いたいと思います。若い人が６５歳以上の方をしっかりと支えるという中で、それから人口をどうやって確保していくか、そのあたりも伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"数としましては、３５万７,０００人ほどというふうに見込んです。平成２２年にまた国勢調査を実施いたしまして、改めて人口動向調査を行いまして、今後の施策に生かしていきたいというふうに考えてあります。","id":"exchange-034"},{"speaker":"山内委員","kind":"質問・要望","question":"すべての品川区の施設で使っている電気の、電力というものが、平成２４年度でどれだけを考えられているのかを伺いたいと思います。もちろんこれは今庁内で考えられているということだと思うんですが、この場で改めて答弁をほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"このたびの第１回定例会の本会議のほうの一般質問等でもいただきまして、私どももＰＰＳの導入については検討を進めてきたところです。今回の施政方針でもございましたけども、行財政改革を推進しまして、そうしたものにもきちんと対応していきたいというふうに考えております。","id":"exchange-035"},{"speaker":"山内委員","kind":"質問・要望","question":"最後に、防災対策費を伺いたいと思います。ちょっと視点を変えて伺いたいんですが、品川区では地盤調査はしているんですかね。","respondent":"片田防災まちづくり事業部長","answer":"区として独自に地盤調査は行っておりません。地盤情報は一応集約していますので、それは建築をする場合に区民の方、あるいは業者のほうにも情報提供しているという状況です。","id":"exchange-036"},{"speaker":"山内委員","kind":"質問","question":"その先、１km行かない、要はホテルがある、ニューオータニのあたりですか、あの辺になると震度５になる。そのあたりをどうお考えなのか、というか、今後考えていけることなのかどうなのか説明を求めました。","respondent":"片田防災まちづくり事業部長","answer":"地盤のところはなかなか難しいので、一応わかりやすく言うと、沖積層、洪積層、特に掘ったときに赤土が出ると。シェルターの話については、地盤が弱くてもかたくても、これは有効だと考えておりますので、そういうことでＰＲしていただければと思います。","id":"exchange-037"},{"speaker":"山内委員","kind":"提案","question":"そういう提案をさせていただいただけなので、その地域だけではなくて、しっかりと理解をしておいていただきたいということです。例えば、本当に大きな地震が来たときに、その辺をどのように行政とそれからケーブルテレビとの話し合いがされているのか説明を求めました。","respondent":"荒井広報広聴課長","answer":"ケーブルテレビにつきましては、幹線の部分については二重化をしておりまして、一定程度安全対策をとっているものだというふうに認識しています。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"私のほうからは、１５７ページの広報広聴費の中で、世論調査およびまたホームページ等経費について質問をさせてほしいと求めました。聞くべき内容、どういったことを聞いていくのか、ここについてまずお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"平成２２年度に実施いたしました世論調査を踏まえて、大綱につきましてもほぼ概要的には同じものを考えているところです。平成２５年度には、長期基本計画の改定を予定しておりますので、そちらに関連した項目も入れていく予定を立てているところです。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"区内の２０代、３０代というのは、こういった方々との貴重なコミュニケーションの機会というふうにとらえていきたいなというふうに思っております。この辺の２０代、今回この辺に対してどのような対策をとられる予定とかがあるかどうかも含めてお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"２０代、３０代、若い世代への回答を求めていく方法の工夫ということのお尋ねだと思います。前回の調査の反省を含めまして、ここは夜間訪問であるとか、休日等の訪問であるとか、そういったことも考えていきたいというふうに思っております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"３０代の方々というのは、なかなか批判的な見解が行政とかについては多いんじゃないかというふうに、そんな印象を持っております。こういった手法も考えてはどうかというふうに思いますが、この点に関してどのようなお考えをお持ちかお聞かせほしいと求めました。","respondent":"荒井広報広聴課長","answer":"ご提案のソーシャルネットワークなどを使った簡易に若い世代の意見を伺うということにつきましては、今後の充実等を含めまして検討を進めていきたいと思います。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に、先ほどちょっと鶴委員のほうからもツイッター等についての質問がありましたけれども、これも区として情報発信の媒体として開設をいたしました。ちょっと数字がわかれば教えていただきたいんですけれども、数字の現状、この辺をどのようにとらえていらっしゃるか教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"現時点のフォロワーの数ですが、約７７０人です。１２月１日に開通といいますか、ツイッターを開始しますというお知らせをしたところですので、ほどよい数かなというふうに考えているところです。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"そうですね、人によって見解が分かれるかとも思いますけれども、７７０名までのフォローが広がったと。そういったことも含めまして、より一層ツイッター発信に努めていただきたいというふうに思いますけれども、その点についてお考えを説明するよう求めました。","respondent":"荒井広報広聴課長","answer":"現在１週間に２回か３回程度発信をしています。そのときには、ツイートというのですか、今後さまざまな情報をさまざまなタイミングで流していくように心がけていきたいと考えています。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"平時の利用で今までお聞きしたんですけれども、かなり活用できたというようなことがこの前の３.１１の経験からいわれております。そういったことを含めて、どういった災害時に情報を発信していくという中身について、どういうお考えを今お持ちであるのかお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"区内の状況であるとか、避難勧告、避難指示に一定程度特化した内容になるかと思います。品川区内の状況といいますか、避難勧告、避難指示にしばられずに少し広い意味での内容を発信していくというようなことを考えているところです。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"昨年行政視察で行った敦賀市なんかの消防なんかでは、実際にそんなこともやっておりました。なので、こういったことも必要かというふうに思いますが、どのようにお考えになりますか尋ねました。","respondent":"荒井広報広聴課長","answer":"消防、警察等の連携についてですが、今後の検討課題にさせていただきたいと思います。３.１１、そういった方々からいただいた情報もあわせて災害対策本部、品川区として情報発信をしたものです。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問・要望","question":"現在の品川区の避難所のペットに対するお考え、また一緒にペットを連れてきた方がいたときの対応がどうなっているのか教えてほしいと求めました。改訂とは別で、見直しが何年に１度行われているのか、行われていないのか教えてほしいと求めました。","respondent":"中山防災課長、高山防災計画担当課長","answer":"避難所連絡会議などで避難所における動物の適正な飼育方法について対応策を検討していくこととなっています。受け入れる意思のある避難所と連絡をとって、ペットの保護… ２点目のお尋ねの地域防災計画の改訂にかかわる決まり事についてお答えします。大きく上位計画である東京都の地域防災計画の見直しを注視しながら、その都度直近の時期に改訂をしてきた、そういった状況です。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"さまざま混乱等も生じると思いますので、ぜひ各地域に、ぜひそういったお考えがあるか教えていただきたい。協定は現在何個あって、１個の計画で複数のところと協定を結んでいる部分があるので、その数とその協定自体の数を教えてほしいと求めました。","respondent":"中山防災課長","answer":"じゃあ人間はどうするのかと、その辺のこともこれから考えて、その辺も十分考えてまいりたいと思ってあります。協定の数ですけれども、２４８団体と協定を結んです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"防災協定に関しては、２４８団体ということでしたが、団体と協定の中身について確認をされているのかどうかお伺いします。古いのと、できれば制定したのが古いのではなく、改訂された最も古い協定を教えてほしいと求めました。","respondent":"中山防災課長","answer":"最初のペットの件ですけれども、当然のことながら、獣医師が参りまして、その動物の健康面等々の面倒を見ることになってあります。それから、協定ですけれども、古いものでいきますと、昭和５１年に協定を結んだものが一番古うあります。","id":"exchange-048"},{"speaker":"大倉委員","kind":"意見","question":"ほかの業者の方、民間の方でも、そういった部分ともぜひ連携をとってほしいと求めました。お話にあったとおり昭和５１年、その中でどの程度、協定を結んでいる方々との協定自体の周知というのを行っているのかもう一度お答えくださいとの意見を述べました。","respondent":"中山防災課長","answer":"ただ、古いものについては、今委員がおっしゃいましたように、再協定を結んでいるということです。ですから、また向こうに失礼のないような形で認識をしていただくためにも再協定をしてまいりたいと思ってあります。","id":"exchange-049"},{"speaker":"大倉委員","kind":"確認","question":"確認でこの時代に合っているか、合っていないかというのを確認しながら、そのところのお考えをお聞かせほしいと求めました。再検討して、また協定を結んでいただくことが必要なんではないかなと思いますので、もう一度ご答弁をお願いいたします。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"やはり委員ご指摘のように、顔の見えるような存在にならないと協定というのは何の役にも立たないと思っていますので、数年に一度確認の意味を込めて協定を相互で確認し合うことを進めてまいりたいと思ってあります。 この協定というのは今回の３.１１を含めて、宮古市あるいは富岡町との関係も含めて、すごく大事なことだと考えています。そういう中で、その都度タイミングを図って確認をして、周知を図るような方向で考えていきたいと思っています。","id":"exchange-050"},{"speaker":"藤原委員","kind":"質問・要望","question":"一般質問でもお伺いしましたが、またスケジュールはどうなっていて、平成２５年の事業にどういうふうに反映していくおつもりかお伺いします。これは大きい意味で教えていただきたいのと、印刷の８６万４,０００円と載っていますが、これは高くないか尋ねました。","respondent":"武内地域活動課長、荒井広報広聴課長、久保田行財政改革担当課長","answer":"平成２４年度については少子化という部分については、ちょっとペンディングというか、そのような認識でおります。… 平成２５年３月に開館する予定の平塚小学校跡地の施設への駅からのアプローチについての案内板を設置あるいは改修するものです。… 新たに中長期的な政策を検討していく上で、平成２４年度は平成２２年の国勢調査をもとに改めて人口の推計を行っていきたいというものです。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問","question":"その辺についてはいかがでしょうか。特に待機児等のことに関しては、そういう人口動向で施策をしていくわけですから、この辺についてはいかがか尋ねました。","respondent":"武内地域活動課長、久保田行財政改革担当課長","answer":"この４年間継続して実施しているわけですけども、区のほうから発信するというところに、非常に大きな力が発揮されるというふうに考えております。１回５,０００円という、そういう機会が設けられるということについては… １万人の誤差ということではなくて、あくまでも人口推計ですので、前回やったときは、中位推計でとっています。人口には上位、下位の推計がありますので、その範囲の中ではほぼ合っているかなというところもあります。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要望書を一昨年に出しているんですけれども、こういう要望書が出されているということは、区として把握をされていますでしょうか。お答えがあったんですけども、施設のほうからは、トイレの洋式化の要望が上がっているか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それで、計画では平成２７年までにやっていくということになっておりますけれども、具体的な年度につきましてはこれからです。そんな中で、大規模改修に合わせてすべて改修ができるところは改修をしていこうというような計画にはなっております。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしましたら、平成２７年までには耐震改修をしていくと。そして、その耐震改修のときにはトイレの洋式化ということもしていくということで確認させていただけますか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"これから耐震を含めた改修につきましては、耐震がまずメインとしまして、どこまでそれと合わせて改修ができるかということを今後庁内のほうで検討しまして、実施していきたいと思っています。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてあと、子どもたちはほとんど和式を生まれたときから使っていない子が多くて、プールのところには洋式が１個しかないんですね。そういうところでは、ぜひとも和式トイレの洋式化ということで、この耐震改修のときに一緒にぜひともお願いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"全体的な改修の計画の中で、あわせて考えさせていただきたいと思いますけれども、区民の皆さんの利用しやすいような形で常に考えていきたいと思っています。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は８０ｍから１００ｍということで、こういう木造の密集、そのことを一つ求めたいと思います。地域からここは本当に危険なのでぜひつけていただきたいという要望があったところには、その点についてもお聞かせほしいと求めました。","respondent":"中山防災課長","answer":"５０ｍ間隔でつけられないかというようなことも考えました。それで、今家庭用消火器がありますので、もし家庭内で火が出なかった場合は、そういうものも活用していただければと思ってあります。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昭和４７年以来見直されていないこの要綱を、こういう要望にはぜひこたえていただきたいと、そのことに対してのお答えをぜひお願いしたいと思います。公共施設に１本だけでなく、公共施設に集中して設置するということも必要なのではないかと思うんですが、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"ですので、やはりきちっとそういう状況を踏まえて、地域の状況を含めて検討したいと考えています。それとあと、あと消防法に基づいた対応も行っているところですので、きちっとその辺は状況を確認しながら対応してまいりたいと思っています。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"町会の訓練で消火器ラリーということで、みんなで消火器の位置を確認して歩くというような訓練をどんどんほかの町会でもやっていくように。ミニポンプの操作なんかも含めて、私はそういう訓練の方法を区としても誘導していただきたいということで、終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"沢田委員","kind":"質問","question":"それから１６９ページの品川区民芸術祭、それから１６５ページの地域環境整備等助成金についてお伺いします。額も１６８万８,０００円ということですけども、１人当たりの給付額と支給の方法や申請の仕方について説明するよう求めました。","respondent":"諸岡総務課長","answer":"補助金の額ですが、１人当たり月額７,０００円です。今回予算に計上しております２０名というのは、今後の見込みと推計ですけれども、予測が立たない分もありますが、２０名ということでの計上です。","id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"朝鮮学校が５名ということでけれども、なぜこの３国だけなのかということと、ほかの国の学校の方にも補助金の支給の可能性というのはあるのかどうか。そもそもこの補助金を区が行っている意味と、今までの経緯とかがわかれば説明を求めました。","respondent":"諸岡総務課長","answer":"昭和５５年には、２３区で最初というふうに思いますけれども、大田区で助成制度を開始しております。要望があったということと、中華学校まで拡大して助成を実施していた、このようなことから品川区としても制度の拡大を図ったというものです。","id":"exchange-060"},{"speaker":"沢田委員","kind":"質問","question":"ほかにも今お話があったようにあるということですし、中国はもはや世界第２位の経済大国でありまして、また韓国も経済大国だと。拉致についての問題をどう扱っているかを検証するということでしたけれども、区としての今後の考え方というのは今どうなっているんか尋ねました。","respondent":"諸岡総務課長","answer":"そして、今後学校運営、また教育内容について徹底した調査を進めると、このように東京都はしております。区といたしましても、このような東京都の動向、そしてまたこの徹底した調査の結果等について注目してまいりたいというふうに考えております。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、品川区民芸術祭についてお伺いします。これは２回目が去年終わりまして、反省というか、そういうところをお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"一例ですけれども、オープニングで実施した子どもたちの活躍と発表のイベントにつきましては、非常に評価をされているところです。このような中で、今後の芸術祭をまた充実するものに考えていきたいと考えています。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は４点確認をさせていただきたいんですけれども、期間がちょっと長過ぎるという話もありますので、そういったこと。それから、区民優先をまたさらに拡大していただきたいと、この４点についてどういうお考えか説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"開会式のあり方ですけれども、また３年、それを開会式としていこうという実行委員のお考えです。それから、区民優先ですけれども、これも好評ですので継続してやっていきたいと考えています。","id":"exchange-063"},{"speaker":"沢田委員","kind":"質問・要望","question":"これを今後さらに周知をしていただきまして、大分認識も高まっていますので、ぜひともいい芸術祭にしてほしいと求めました。そういった会計の透明、監査をちゃんとしていくところが重要だと思うんですけども、その点について区としてはどう考えられているか尋ねました。","respondent":"武内地域活動課長","answer":"平成２１年度から町会の今言われた会計の透明性だとか、会計のノウハウをしっかり勉強していただくと、そういう事業を行っております。","id":"exchange-064"},{"speaker":"沢田委員","kind":"質問・要望","question":"いろいろありましたけども、やっぱり一部の町会では外部監査を入れたり、そういったことをやられているところもあると思います。こういったことを区としてもさらに後押しをしていく施策を行ってほしいと求めました。","respondent":"武内地域活動課長","answer":"基本構想にもあるとおり、協働の最大の相手は２０４の町会・自治会と位置づけしておりますので、それにつきましては、今後も一層努力して町会と連携を図りながらやっていく所存です。","id":"exchange-065"},{"speaker":"金野委員","kind":"質問","question":"それから１７９ページの防災会議費、そして時間があれば１８１ページの職員参集システム経費をお聞きしたいと思います。いわゆる地方の、この品川区防災会議条例に基づいて会長と、そして委員によって６１名以内で構成される組織というふうに一応条例ではなっております。","respondent":"高山防災計画担当課長","answer":"素案のほうを提示しました後に、区民の意見聴取などを図りまして、年度末の策定に向けて計画の進捗を図れればと、このように考えております。","id":"exchange-066"},{"speaker":"金野委員","kind":"質問・要望","question":"基本的なところを確認させていただきたいんですが、いわゆるその構成と人数で、それともこのまま今までのとおりでいくのか。６１人以内というこの人数、自治体によって決められているものなのかなと理解しているんですが、この６１人の根拠も説明を求めました。","respondent":"高山防災計画担当課長","answer":"６１名の根拠につきましては、把握してございません。申しわけございません。","id":"exchange-067"},{"speaker":"金野委員","kind":"質問","question":"６１名の根拠はないと、把握をされていないということで、そうですか、わかりました。今回の改訂に当たっての調査の内容、それから委員はどういった方を起用していくのか、そこら辺のところを説明するよう求めました。","respondent":"高山防災計画担当課長","answer":"調査の内容ですが、今般の地域防災計画の改訂にかかわる主な審議ということで考えてあります。そして、メンバーの部分につきましては、やはり委員のご指摘のような専門的な知見などの活用などが図れればというふうに考えております。","id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"ちょっとあまり、ご説明があれだったんですが、現状そういうことだとしておきます。今まではこの防災計画は成人男子、男女共同参画のこちらの所管では、具体的に防災という取り組みは何かされておりますか尋ねました。","respondent":"中山人権啓発課長","answer":"災害時要援護者支援や避難誘導ワークショップなどへの女性の参加促進ということで、防災課のほうと連絡をとりながら進めていきたいと考えています。","id":"exchange-069"},{"speaker":"金野委員","kind":"質問・要望","question":"具体的にそのことがどのようにされているのか、もしお答えできればしてほしいと求めました。もっとその中に女性を含めていただきたい、このように思いますが、いかがか尋ねました。","respondent":"高山防災計画担当課長、片田防災まちづくり事業部長","answer":"男女双方の視点をマニュアルなどにというお尋ねです。こちらのほうは、国の防災基本計画の中にも改訂されたもの……。 今委員おっしゃるとおり防災会議は、防災計画を決定する最高の機関です。一応６１名のメンバーの中にも区長が必要と認める者ということで書かれておりますので、その中で検討してまいります。","id":"exchange-070"},{"speaker":"向委員","kind":"質問","question":"１９０から１９３ページにかけての戸籍および住民基本台帳全般、あと住民基本台帳カード、そのあたりでお尋ねしたいと思います。どういった警備をされているのか、いろいろいらっしゃると思うんですが、そのあたりを説明するよう求めました。","respondent":"阿部経理課長","answer":"警備の話ですけれども、実は２階に警備室というのがございまして、警備室に常駐している警備員がおります。経費につきましては、４,２００万円の予算を計上しております。","id":"exchange-071"},{"speaker":"向委員","kind":"確認","question":"そのあたりで一々身分証を確認できないというのは重々承知しているんですが、私は以前民間に１０年ぐらい勤めていたので、最近やはり。注目される品川区であってほしいという願いもあるので、例えば、庁舎の中のお手洗いとかに防犯ベルは設置されていますか。","respondent":"阿部経理課長","answer":"結婚の届出とか、その場合にはちゃんと警備員が案内するという形になっていますので、だれでも自由に入れるということではございません。すべてついておりまして、何かあった場合には、押せば警備室に通報するという形になってあります。","id":"exchange-072"},{"speaker":"向委員","kind":"質問","question":"結構６時半とかまでおそくなるときもあって、そこに出てしまうと機械警備に体の反応がないのか、それ以上早く出てくださいと言われなくなる。１９０ページから１９３ページの戸籍および住民基本台帳カードの件なんですが、去年、何人ぐらいの方が実際お持ちなのか説明を求めました。","respondent":"梶戸籍住民課長","answer":"大体５.５％程度がお持ちということでございまして、平成１５年から発行してございまして、１月末現在で２万５,０１７枚発行しています。それは無効になりますので、有効な件数としましては、１月末現在で１万９,６３６件という形で発行しています。","id":"exchange-073"},{"speaker":"向委員","kind":"意見","question":"私の年代というのは、日頃、平日はおそくまで働いている方が多いんですね。ちょっと残念だったという話も聞いたりするので、このあたりというのは、窓口とか転出届につけ加えたりとかしていただけたらなと思うんですけどとの意見を述べました。","respondent":"梶戸籍住民課長","answer":"ホームページでも……。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"１８３ページ、学校避難所のことを聞きたいです。一時集合場所の意味合いと必要性をまずちょっと教えていただけますか尋ねました。","respondent":"中山防災課長","answer":"その際に無事を確認し合うということもあるんですけど、集合場所に集まって、みんなで避難所へ行こうというところが一時避難場所となっています。ただし、直接行っても構わないというような状況です。","id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"やめるんじゃなくて、例えば一時集合場所も指定されている学校避難所、ここが一時集合場所ですよというような形に明確にすべきだと思います。ふだん見るふれあい掲示板にも、ここの町会はどこどこ小学校ですというような書き方をされているわけですから、いかがか尋ねました。","respondent":"中山防災課長","answer":"じゃあ、町会長が被災していたら、そこに集合なんかはできないわけですね。ですから、その辺はやっぱり臨機応変に動かなきゃいけないですので、私どもももう少し研究してまいりたいと思ってあります。","id":"exchange-076"},{"speaker":"渡部委員","kind":"質問・要望","question":"より安全にというのが求められると思いますので、その辺は本当に研究に研究を重ねていただいて、わかりやすい方法にしてほしいと求めました。だれがどこに入っても、どういう形になっているよというのがわかる必要が僕はあると思うんですが、その辺はどのようにお考えでしょう。","respondent":"中山防災課長","answer":"ですから、私どもは用務主事にお願いしたんですけれども、これで終わらないで、全部の備蓄倉庫の検証をしてまいります。とりやすいかどうか、それに合わせて用務主事に再度お願いしてまいりますので、よろしくお願いいたします。","id":"exchange-077"},{"speaker":"渡部委員","kind":"質問","question":"それと、１６５ページで、町会のことを少し伺いたいんですけど、ふれあい掲示板です。緊急のお知らせとかも張れるような仕組みに持っていければいいと思うんですが、その辺、いかがか尋ねました。","respondent":"武内地域活動課長","answer":"ふれあい掲示板が４８８本ありまして、過去の４８８本の中で、役員の声を聞きながら進めてまいりたいと思います。","id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"一緒に１５９ページの区民相談経費、そして１６９ページの品川区民芸術祭経費、１６７ページの生活安全推進事業をお願いいたします。３０分で１回の説明をしていただいて、３回まででしたかね、そういうことをちょっとお伺いしたいんですけど。","respondent":"荒井広報広聴課長、中山人権啓発課長","answer":"法律相談につきましては、１回３０分を目安にお一人の方１件というか、案件１件につきまして３回までということでお願いしています。ただし、それから相談内容がどういうものであったかという件名につきましては… やはりこちらも１回３０分ということで、お一人の方１案件につき１回ということで、男女共同参画センターのほうはしています。これはやはり、相談される方のプライバシーの保護ということを最優先に考えているからです。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問","question":"外国人生活相談で家族問題に関して１４件ということで、９.９％、それを心配しているんですよね。プライバシーの問題もありますが、横のつながりがあるのかどうかということをちょっと、これはと思う案件に関してはいかがなものか尋ねました。","respondent":"中山人権啓発課長","answer":"あるいはこれは虐待ではないかというような相談があったときには、それぞれの所管がありますので、そちらをご紹介するなどの手だてはとっています。最初にご質問のあった法律相談というのは、やっぱり１件１回限りということで、継続ということはしていないということになります。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問","question":"そして、それはちょっとどうかなと私は思うんですけど、やはりここをＤＶの相談ですよというふうに広報にも書いてございました。ここで本当に２４時間体制ではないですけれど、もう少し時間を広げていただけたらという気持ちがあるんですけれど、いかがなものか尋ねました。","respondent":"中山人権啓発課長","answer":"警察のほうに対応していただくのが一番かと考えていますので、警察とそれから区の相談とということで役割を分担しながら対応しています。どちらかというとじっくり話を聞く、あなたは悪くないよというふうに気持ちをほぐしてあげる、そういうような相談になっているところです。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問・要望","question":"ほかのいろんな部署のほうからもフォローしていただいている、時間帯に関しては、もう少し広げて、私の要望ですけれど、いただけたらと思います。今年で２年目だということで、この経費の内容と、それからチケット代の説明をお願いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"そして、今言いましたコンサートの事業の中で、低廉な価格で区民の皆さんに提供しているところです。そのチケットの収入は、ここで相殺をしまして、ここの開催の一部として相殺をして支出をしています。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんにたくさん来ていただきたいということで、第１弾から第３弾の３枚を買うと５,０００円ですか、わかりました。区民の皆様の希望は入っているのかなということをちょっとお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"第１回目を行いました、その結果によって我々はアンケートをとっております。そして、もう一つの質の高いコンサートについては、プロデュース等、企画等を得意としております品川区文化振興事業団、そこが行っているところです。","id":"exchange-083"},{"speaker":"原委員","kind":"質問・要望","question":"先ほど補助金を伺ったんですけれども、そういったところの考えというのがあるものですから、中長期ということでお聞かせほしいと求めました。同じく１４９ページ、これは聞こうかどうしようか迷ったんですけど、それから逆に区長サイドからの要望等が入っているかどうか。","respondent":"諸岡総務課長、阿部経理課長、武内地域活動課長","answer":"基本的には直ちに制度を拡大するという考えはございませんけれども、幅広い観点から今後の課題とさせていただきたいというふうに考えております。… それが一番大きいものです。旧第一日野小学校の維持管理費ですが、これにつきましては、機械警備とか樹木の剪定、あとは自動火災報知機を設置していますの… 平均して１００万円ということですけども、９８万円だとか１１０万円だとかという金額の、規模によって若干その辺の差はあります。","id":"exchange-084"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、逆にそういう意味合いを込めますと、しっかりと逆に頑張っていただきたいというのが私の意見です。やはり区民の方々からの要望が大きいというか、１地区１００万円ということなんですけれども、よく足りないよという意見が出るんですね。","respondent":"武内地域活動課長、阿部経理課長","answer":"委員言われるとおりさまざまなやり方がある中で、ある地区では総経費が２８０万円で、実行委員会が１７０万円を負担しているという地区もあります。本来１回を３回やっているだとか、そういう地区もある中で… 校舎の機械警備につきましては４４万円、あと校舎の自動火災報知機につきましては１３万円等の支出を予定しているものです。","id":"exchange-085"},{"speaker":"原委員","kind":"質問・要望","question":"当然、区資産の売却には鑑定士とか評価委員ですかね、鑑定士は多分１人じゃなくて、２人とか３人とかをお願いしてやっていらっしゃると思いますので。ですから、実際に先ほどの会計のほうでお伺いしたところでは、その辺のところのご意見があればお聞かせいただきたいと思うんですけど。","respondent":"阿部経理課長","answer":"今の古くなった机とかいすとかロッカーという件ですけれども、これにつきましては、区内の社会福祉法人のほうで、まだ使えるものについては欲しいという話がございましたので、私どものほうで区内の社会福祉法人に無償で差し上げたというような形で活用しているものです。","id":"exchange-086"},{"speaker":"原委員","kind":"質問・要望","question":"できることであれば、そういったものを活用していっていただきたいという、これもちょっと一部要望なんですけども。最後に質問といたしましては、こういったものに関する、その辺のところをちょっと教えてほしいと求めました。","respondent":"阿部経理課長","answer":"実は庁内全体で不用品の交換市というのをやってございまして、各課で不要なものを出し合って、必要なところ、これは出先も含めてですけども、必要なところが持っていって使うという形で、そういう備品類、什器類の有効活用を図っているというものです。","id":"exchange-087"},{"speaker":"原委員","kind":"意見","question":"これは私が直接聞いたわけではないですけど、そういう買い取り業者が、「うわー、厳しいな、品川区は」と言っておりますので。品川区にとっては非常に、逆に一部でもそれが資金化できるのか、この辺を検討していただいて頑張ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"稲川委員","kind":"質問","question":"私は１４９ページ、品川区史編さん経費について、１８３ページ、区民消火隊の助成というか、むしろ区民消火隊についてお伺いをいたします。大体Ａ５判で１,０００ページという流れだったのが、今回４００ページですから、なぜこういう形になったのか。","respondent":"諸岡総務課長","answer":"４００ページ程度を予定しています。それにつきましては、昭和５０年度に完了しておりまして、その時点についてはちょっと今即答できない状態です。","id":"exchange-089"},{"speaker":"稲川委員","kind":"質問・要望","question":"本当に昭和２年ぐらいからずっと出ていますので、１回確認をしてみてください。そういったものも区史に載せるべきではないかと思うんですが、いかがか尋ねました。","respondent":"諸岡総務課長","answer":"それ以外の部分につきましても、昭和５０年の前回の区史編さん以降、そういったものについては積極的に触れていきたいというふうに考えております。","id":"exchange-090"},{"speaker":"稲川委員","kind":"質問・要望","question":"ここにあるように６８隊ありまして、そしてその中で多分防災部の方なんでしょうか、消火隊に従事をしています。この消火隊の皆様の被服というんでしょうか、活動服、そして防火服がどのように支給されているのか、簡単に示すよう求めました。","respondent":"中山防災課長","answer":"基本的には、私どものほうで区民消火隊は６８隊ありまして、それに８人ぐらいですね。ですから、５００人以上になると思いますけれども、そこに私どもで支給しているです。","id":"exchange-091"},{"speaker":"稲川委員","kind":"質問","question":"非常にスタイル性を見たときに、消防団も１年前か２年前ぐらいに防火服ががらっと一新されて、単刀直入に言えば格好よくなったと。いつになるかは別にしても、そういう思いが必要だと思うんですが、いかがか尋ねました。","respondent":"中山防災課長","answer":"私どもへ直接申し出ていただければ新しいものとお取り替えしますので、その新しいものを身につけてモチベーションを上げていただきたいです。在庫がなくなったときには、区長に相談して、何とか考えてまいりたいと思いますので、よろしくどうぞお願いします。","id":"exchange-092"},{"speaker":"稲川委員","kind":"質問・要望","question":"もう１点は、そういった防火服というんですか、そういうのも私は必要だと考えています。もし、今在庫があるんであれば、そういう古いものを全部排出していただいて取り替えてほしいと求めましたが、いかがか尋ねました。","respondent":"中山防災課長","answer":"今後の研究課題とします。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問","question":"１７９ページ、応急活動対策費から何点かお伺いしたいと思います。最高の８回線を超えて、同時接続のトライというんでしょうか、ここら辺についてお伺いしたいと思います。","respondent":"中山防災課長","answer":"新たにＪＲの５駅にデジタル無線を配備しています。８回線が輻輳したということはございません。","id":"exchange-094"},{"speaker":"浅野委員","kind":"提案","question":"さいたま市では２５６カ所の避難所に入れたという情報もありましたが、これも昨年の決算特別委員会のときに提案をさせていただいたものです。これも一つ視野に入れていくという回答は前回もいただいておりますけれども、積極的に検討してほしいと求めましたが、いかがか尋ねました。","respondent":"中山防災課長","answer":"それならいっそ携帯のＰＨＳのほうがいいんじゃないかということでございまして、実は携帯電話でａｕのものを防災課の職員用に１０台持ってあります。これを来年度ＰＨＳにかえまして検証してまいる予定です。","id":"exchange-095"},{"speaker":"浅野委員","kind":"提案","question":"この点について１点お伺いしたいと思います。防災と緊急というものは一緒でも私は構わないのではないかなと思いますが、あわせてこの点、２点についてお伺いしたいと思いますとの意見を述べました。","respondent":"中山防災課長","answer":"最初のご質問ですが、今回の防災ＧＩＳデータの中には、防災の分としては２０項目程度入れてありますので、また必要なものがあれば、これにどんどん追加していこうという考えです。","id":"exchange-096"},{"speaker":"浅野委員","kind":"提案","question":"前にも提案しました電話をかけて再聴できるような、そういうシステムもぜひとも考えていただければなと、そのように思います。緊急時はやはりスピードが命でありますので、ぜひとも専用番号を設置してはどうかと思いますが、いかがか尋ねました。","respondent":"中山防災課長","answer":"今後研究してまいりたいと思います。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"商店街放送設備接続工事、今１０８の商店街があるわけですが、放送設備がない商店街というのはどのぐらいあるのかなということをお伺いします。そしてあと、モデル商店街選定の考え方、３地区はまずスタートするわけですけれども、これについても説明を求めました。","respondent":"米田商業・観光課長、中山防災課長","answer":"商店街の数は１０８カ所です。放送設備については、私どものほうで把握しているところでは、１９カ所ということで把握しています。 それから、荏原町商店街につきましては７月に、予定ですけれども、放送接続を開始いたします。３番目に、９月に戸越銀座商店街の接続を開始するという予定になってあります。","id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"ここにつきましても、やはり住民の方の意識も高い、そしてまたマンションですから、高級マンションになればなるほど密閉性が高くて外から聞こえない。これからもマンション、課題というものは多々出てくると思いますので、この点についてのご見解をお伺いします。","respondent":"中山防災課長","answer":"さまざまな民間マンションとのお話し合いを持って協定を結ぶわけですので、向こうの状況を見ながら検討してまいりたいと思います。向こうの言い分も聞きながら検討してまいりたいと思います。","id":"exchange-099"},{"speaker":"浅野委員","kind":"質問","question":"次に、広報紙発行、ホームページ等経費ですが、過去にも質問が出ました。区内標高図が出た１月２１日号、過去にこのようなケースはあったのかどうかということと、過去の例を教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"１月２１日号につきましては、大変好評で、特に駅のスタンドなどからはほとんどなくなったという経緯があります。過去にこういう経過があったかということですが、私の聞いている限りでは把握しておりません。","id":"exchange-100"},{"speaker":"浅野委員","kind":"質問","question":"この一つの案としてスマートフォン、こちらが平成２３年の上半期は、携帯の新規契約の半数以上を占めているわけですね。ご見解をお伺いします。","respondent":"荒井広報広聴課長","answer":"広報紙をめくる、電子書籍化、デジタルブックというものかと思いますが、実は広報広聴課では、平成２２年の下半期に実証実験を行いました。今後につきましては、少し研究をさせていただきながら、方向性を考えていきたいと思います。","id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"火曜延長時間というんでしょうか、大変ご利用される方が多いとお聞きしているんですが、区民サービスの向上に大変役立っていると思います。そういう書類をとりに行く数がどうなっているのか、その傾向、そして今後どういう状況になっていくんか尋ねました。","respondent":"梶戸籍住民課長、武内地域活動課長","answer":"２月末現在、この前終わった段階で２万２,８２０人ということですので、着実に増えてです。ちなみに、昨年の途中の７月からは税務関係、そして国民健康保険関係も広げてやってありますので、ご好評いただいているところです。 地域センターの住民票の発行で言いますと、平成１５年度と平成２２年度を比較しますと、発行の証明枚数は約３０％マイナスになっております。","id":"exchange-102"},{"speaker":"高橋委員","kind":"質問","question":"その反面、地域センターでは今お話があったように、住民票というお話ですが、３０％ほどでしょうか、そういった手続が減った。これは地域活動課の１０６名の方で、すべて地域センターでお仕事をされている方になるんか尋ねました。","respondent":"武内地域活動課長","answer":"１０６名は地域センターに配置している職員です。","id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"ということは、この方々はすべて正規の職員でしょうか。そして、そのほかに地域センターで働かれている方の立場というんでしょうか、どのような勤務形態でお仕事をされているんか尋ねました。","respondent":"武内地域活動課長","answer":"２人ほど再任用の職員がいます。勤務時間は８時３０分から５時１５分までです。","id":"exchange-104"},{"speaker":"高橋委員","kind":"質問","question":"ということは、地域センターでお仕事をされている方は、この１０６名と２名の再任用の方、それ以外の方は地域センターの業務、清掃とかそういうのはなしで、事務所の中でというんでしょうか、働いている方はどうなんか尋ねました。","respondent":"武内地域活動課長","answer":"すみません、今再任用を２名と言ったんですけど、３名でした。失礼いたしました。","id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"ということは、１０６名の方が地域センターでお仕事をされている。常勤の職員の方が１０６名、それが１３のセンターにいらっしゃるわけですけれども、そちらのほうに力を注ぐというお考えはいかがか尋ねました。","respondent":"武内地域活動課長","answer":"現在のところ、地域センター業務につきましては、そのような民間のほうに仕事をお願いする予定はございません。","id":"exchange-106"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成２０年の決算特別委員会でお尋ねをしたんですが、どこまでが例えば民間活用が可能かということについて十分研究してまいります。十分な研究とさまざまな検証についてご説明ほしいと求めました。","respondent":"武内地域活動課長","answer":"この間さまざまな住民票の改正等もある中で、日曜開庁のあり方等の中で、窓口のあり方検討を毎年行っていく中で整理をしています。その結果、今後もうしばらく様子を見て、また今後研究課題ということになっております。","id":"exchange-107"},{"speaker":"高橋委員","kind":"質問・要望","question":"様子を見て検討課題ということなんですが、民間委託をした場合のプラスとマイナスについてのお考えをご説明いただきたい。民間委託というのはできないのかどうかという点ですね。","respondent":"久保田行財政改革担当課長","answer":"平成２０年１月に内閣府のほうから地方公共団体における窓口業務で民間委託ができる業務ということで、２４事業が提示されております。","id":"exchange-108"},{"speaker":"高橋委員","kind":"質問","question":"その中で正規職員の方が１人、地域センターで１人というので、正規職員の方がいらっしゃれば民間委託ができる。今４年間たったんですが、なかなか検討の内容が出てこないんですが、今後の見通しはどのような状況なんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"窓口のあり方検討につきましては、火曜延長等を取り入れてきまして、いろんな窓口で住民の方がサービスを受けられるといったところです。","id":"exchange-109"},{"speaker":"高橋委員","kind":"質問・要望","question":"多用な検討ということで、地域センターでその事務をやらないわけではありませんので、そういった多用な窓口事務を円滑に行うために、そして行革の視点でぜひ積極的に導入する検討をさらに進めていって、何らかの具体的な結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問","question":"１４７ページの職員給与費、退職手当、１５３ページの健康管理、全庁的な、広くお伺いしますので、よろしくお願いします。２点目は、直接雇用のところで、非常勤職員の数、臨時職員の数、再雇用職員の数、派遣職員の数、ここも総数と予算の総額を説明するよう求めました。","respondent":"堀越人事課長","answer":"委託についてですが、人数について委託しているものではございませんので、把握する必要はないというふうに考えてあります。経費については、私どもでは今手元に資料はございません。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一般質問のところでも、リーセントワークを目指していただきたいと質問させていただいたんですけれども、正規雇用が非正規に置きかわっています。こういった状況が広がっていますけれども、どちらも改善が必要と考えますが、いかがか尋ねました。","respondent":"榎本企画財政課長、堀越人事課長","answer":"人件費、職員給与費等の表記の問題ですけれども、これはやはり款別に全体事業費を出すということで工夫を図ってまいりました。かからないもの、さまざまな委託料の種別がありますので… 区の職員の配置の考え方ですが、基本的には最小の経費で最大のサービスという考え方を基本にしております。これは民間も同じですし、品川区といたしましてもそのような形で組織を運営していくというものです。","id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと具体的に現状をお伺いしたいので、１点目は長時間労働のことですが、残業が月８０時間を超える方は何人いらっしゃるのか。辞退者が増えているといったこともちょっと伺っているので、この辺、何人採用で辞退者がどのくらいいらっしゃるのかも説明を求めました。","respondent":"堀越人事課長","answer":"退職者につきましては、平成２３年度１６２名と見込んでおりますが、そのうち普通退職、いわゆる早期にやめられる方については４１名です。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何とかこういった仕事は分けて、１.５人分しているんですから、正規雇用を増やして、分けて働くのが当然だと思っています。私はぜひ時給は１,０００円を超えてほしい。","respondent":"堀越人事課長","answer":"先ほど申しました考え方でやっていきたいと思っています。","id":"exchange-114"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１８１ページの初期消火体制強化費、そして１６５ページの青少年対策費の２点を伺おうと思います。消火器の有効性がやはり４６.９％という記載があり、くみ置きの水等の効果率というんですか、３４.５％という数字が記載されていました。","respondent":"中山防災課長","answer":"やはり、一番多いのは例えば夕刻の時間帯に火を使っているときに油が延焼するというようなことが一番発生率としては大きいのではないかと考えています。","id":"exchange-115"},{"speaker":"渡辺委員","kind":"提案","question":"ただ、玄関口にあったり、あるいは２階の寝室にあったり、複数ある家庭はまだ現実的には少ないかと思っています。震災時のみならず有効かと思い、ぜひとも提案をしたいと思っていますが、行政のお考えを伺えればと思いますとの意見を述べました。","respondent":"中山防災課長","answer":"委員の新たなご提案ですので、十分検討してまいりたいと考えております。","id":"exchange-116"},{"speaker":"渡辺委員","kind":"質問","question":"どうしてももらってしまうという、これもやはり個人責任を超えたことを公共、あるいは共助の観点からカバーしていかなければならない。先ほどもう１点聞きたかったのは、消火器の設置の拡充の点とスプレーと、あわせて全体でもう一度伺えればと思います。","respondent":"片田防災まちづくり事業部長","answer":"そういう意味では、延焼を防ぐために初期消火はすごく大事なことと考えております。消火器の活用等で訓練していただいておりますけれども、有効な活用ができるかどうかということも含めて十分に検討させていただければと考えています。","id":"exchange-117"},{"speaker":"渡辺委員","kind":"質問","question":"次に、青少年対策費のところで一つ伺いたいと思います。今後の展開で平成２４年度のまず核となる事業であるかと思いますが、対象者、地域力の活用という点で考え方を伺えればと思います。","respondent":"小林青少年育成課長","answer":"今般、２月７日に開催されました青少年育成協議会で、来年度、再来年度の育成方針を定めた点もそこがポイントとなっております。その中での育成を考えてまいりたいと考えております。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"一般管理費で１５３ページの庁舎等維持管理費について、それから地域振興費で１７３ページ、総合区民会館運営費についてお伺いをいたします。東京電力が電気料金を当初発表のように１７％の値上げをしたとすれば、区の影響は幾らぐらいになる見通しなのかまず、答えるよう求めました。","respondent":"榎本企画財政課長","answer":"今現在電気料は平成２４年度予算でいきますと、平成２３年度は節電がありましたので、ざっと概算すると６,０００万円ぐらい足りなくなるんではないかというのが今現在の試算です。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"そうすると、実際には原発の事故の後処理の費用までが値上げに含まれているとすれば、到底値上げは受け入れられないというふうに思うんですね。品川区は東京電力の値上げに対して今までどのようなスタンスで東京電力に対して主張してこられたのかお伺いいたします。","respondent":"桑村総務部長","answer":"これについては丁寧な説明が東京電力は必要だということを主張してまいりました。そういった東京電力が今後電気についてどういうことをこれから考えられるのか、そういったことを検討していくというようなお話をしています。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問・要望","question":"公園児童遊園では４９０万円、学校では５,５００万円、実際には１億４００万円ほどの削減ということで予算書には明示をされています。これについて、根拠を説明するよう求めました。","respondent":"榎本企画財政課長","answer":"平成２３年度の節電した分がありましたので、その部分を差し引きまして、それとまだ予算編成の段階でも電気料が上がるかもしれないということで、そのプラス分として下げた後の５％を予算として見ているという形です。","id":"exchange-121"},{"speaker":"井上委員","kind":"提案","question":"学校では環境教育とともに電力の節減というだけを求めるのではなくて、前にも私は提案をさせていただきましたフィフティー・フィフティー制度のような、そういったことの検討というのは何か進められているんか尋ねました。","respondent":"和氣学務課長","answer":"今回特に震災関係で節電を進めてまいりましたけれども、それぞれ日々節減に努める、省エネに努めるということをやっていただいているというのが現状です。","id":"exchange-122"},{"speaker":"井上委員","kind":"質問・要望","question":"次は２点目、総合区民会館のほうなんですけれども、きゅりあんで今私たちも利用させていただいている駐輪場の台数と利用状況を教えてください。稼働率でいいです。","respondent":"安藤文化スポーツ振興課長","answer":"７２台ですけれども、理論的には７２台が可能なんですけれども、それがマックス７２台は不可能だというお話でした。それで、大体５０台から６０台ぐらいというお話です。","id":"exchange-123"},{"speaker":"井上委員","kind":"確認","question":"満車というところで確認を、警備をしている担当の方に伺ったら、３６台しか稼働していない。あれだけの建物で３６台を回しているというのは、それで１日置いておけるという、改善に向けての取り組みは今どのように進んでいるんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"ただいまのご指摘の駐輪場の問題ですけれども、１回１００円です。そして関係機関、西友だとかヤマダ電機も含めて今検討に入っているというお話でございました。","id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"一点、違うほうの建物のところにも駐輪場があるわけですが、今閉鎖をされていて活用されていない。ぜひそういう情報もいただきながら考えていくというところに力を入れてほしいと求めましたけど、一言覚悟をお願いします。","respondent":"安藤文化スポーツ振興課長","answer":"今ご指摘の駐輪場につきましては、ＪＲの線路のところのご指摘だと思うんですけれども、それについてはＪＲの所有ということで認識しています。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"幼保一体とか就学前教育を公立としてもやっているんですから、民生費でもいいんじゃないかなというふうに思うんですが、その考え方をお聞きします。１６５ページの青少年対策費、「家庭の日」啓発事業という私も非常に期待はしているんですが、これは子どもたちの対象は何歳か尋ねました。","respondent":"榎本企画財政課長、小林青少年育成課長、高山防災計画担当課長","answer":"そういう形で、実際上決算統計上は教育費のほうに区分して決算上は出すという形のルールになっているところです。ですから、いろんな科目が考えられる場合… 「家庭の日」啓発事業の対象者は、子どもはもちろんですが、主力はご家庭、保護者、そしてそれを取り巻く地域すべてが対象になると考えております。小中一貫校などもありますので、倉庫の数としては５８個ありますので、そういった形で指定避難所に分散備蓄をする予定です。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ来れない子たちに対してどうやってフォローしていくかということの観点からいうと、その辺の考え方をお聞きします。そこら辺はどういう運用の仕方として考えられているのかお聞きします。","respondent":"高山防災計画担当課長、小林青少年育成課長","answer":"これにつきましては、あと区営施設の活用なども今後引き続き図ってまいりたいと考えています。そしてまた、発災直後の対応にもよりますが、混乱などが生じないような形で事前のルールづくりについて努めてまいりたいと考えております。そのために新しい事業としては例えば青少年お役立ち隊等の地域での活躍の場も多様な形で設定していくことが必要と思います。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"できれば、私は中高生にターゲットを合わせたものを、ぜひ何か１本つくっていただきたいなというふうに思ってあります。ここまでやっているんですから、しっかりと該当者がわかっているんですから、そこから情報をアクセスできるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"武内委員","kind":"質問","question":"いわゆる個別支援計画というんですかね、避難のときに助けるんだという個別支援計画、この進捗状況を教えてください。本会議で質問したときに、どのような対象、６,０００円助成の方の対象がどういうふうに考えているのかというのを説明するよう求めました。","respondent":"堀越人事課長、高山防災計画担当課長、中山防災課長、片田防災まちづくり事業部長","answer":"それぞれ１年間派遣の予定をしております。庁内で公募を実施いたしまして、その中から選考を進めているところでございまして… 個別支援プランの推進ということで、現在３町会をモデル地区としまして、そこからノウハウの吸収ということで、現在鋭意進めているところです。… 助成対象ですけれども、基本的には情報入手が困難な高齢者や障害者世帯等を考えていることに変わりはございません。本会議のほうでは、ＩＴ機器を利用して情報入手することが困難な高齢者や障害者世帯等ということでご説明しています。","id":"exchange-129"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望で結構です。それから、いつごろまでにこれをお決めするのかなというのを教えてほしいと求めました。","respondent":"堀越人事課長、片田防災まちづくり事業部長、諸岡総務課長","answer":"公募の応募の人数ですが、合計で２０名応募があったものです。職種につきましては、基本的に宮古市のほうからご希望をいただきまして… そういうことを含めてご家族の中でそういうきちっとした対応ができるとか、一定の避難行動がとれるとか、そんなことも意識して考えております。… 被災地に派遣された職員と、それから意見交換会、これは区長にも入っていただきまして、過去３回にわたり実施しております。","id":"exchange-130"},{"speaker":"武内委員","kind":"質問・要望","question":"最後に要望ですけど、私たちにも参考になるように教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"そこで質問をしますけれども、その人権啓発課の仕事、どんなことをしているんでしょうか。課長以下５人でやっているということですが、お伺いしたいと思います。","respondent":"中山人権啓発課長","answer":"人権啓発課の所掌事務のお尋ねです。そして同和対策、そして男女共同参画の推進と、この三本柱でやらせていただいているところです。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"人権擁護委員でしょうか。なかなか使われていないというんですかね、そういう問題の相談が来るかと思うんですが、その辺についてお伺いしたいと思います。","respondent":"中山人権啓発課長","answer":"私の人権の部署では、同和生活相談ということで、同和問題のほうを対応させていただいています。どこの窓口にいらしても、その方の悩んでいることの直接的な原因のところにつながるように庁内で連携して対応していきたいと思っているところです。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"防災対策費、１８３ページ、実はつい先日、小学校へ行って備蓄倉庫を見てきました。そこからとるということですけれども、改めて学校での飲料水の確保、どういうふうにしているのかお聞きしたいと思います。","respondent":"中山防災課長","answer":"これが全部で１０９万４,０００ｌあります。ただ、想定外のことを考えまして、１人１ｌではありますけれども、３年計画で区民全体に１ｌが行き渡るように配備を進めているところです。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"乾パンと水、それさえあれば１日しのげるわけですから。初日はとにかく１個のおにぎり、１本のペットボトルですから、実際の本当に困ったときの対応というのを考えていただきたいというふうに思います。","respondent":"早津選挙管理委員会事務局長","answer":"一般的に言いまして、選挙が特定されている時期に氏名の入ったたすきということであれば、事前運動に当たる可能性があります。今回それをお認めになったという記事だというふうに受けとめております。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"これもやっぱり確かに違反ですよね。例えば区民の方が写真を撮って、これは違反ですよと選挙管理委員会に持ってきた場合、選挙管理委員会はどういう対応をとるんか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"先ほど対応によってという言葉を使いましたが、個人名のほかに何かがあるのかというようなことで、かなり微妙な判断になってくる場合があるようです。選挙管理委員会というよりも司法の段階での問題になってまいりますので、警察等の判断が必要になる微妙な問題もあり得るです。","id":"exchange-136"},{"speaker":"松澤委員","kind":"確認","question":"写真を撮って、それを持っていけば、それを警察に選挙管理委員会から上げてもらえるということなんですね、確認をしたいと思います。","respondent":"早津選挙管理委員会事務局長","answer":"お届けいただければ、警察にお届けすることはできます。","id":"exchange-137"},{"speaker":"南委員","kind":"質問","question":"ふ頭のところの耐震性というのはどうなのか、ちょっと八潮という地域に住んでいる、そういう立場上非常に気になるところなので伺いたいと思います。この地域での、前回の３.１１では液状化があったというふうには聞いておりませんけれども、どういうことなのかも説明を求めました。","respondent":"武藤都市整備下水道課長","answer":"現在１００％今必要な高さが整備されておりまして、今東京都のほうで委員会を立ち上げて検証しているというふうに聞いております。液状化が起きた場合についてどういった影響があるのかということも含めて、その委員会で検討しているというふうに聞いております。","id":"exchange-138"},{"speaker":"南委員","kind":"質問","question":"したがって、これらの施設の耐震性については、どういうふうに承知をしているのか。火力発電所のところでは、とりわけパイプライン等もありますので、そこについての耐震性についてもどうなのか伺います。","respondent":"山口防災安全担当課長","answer":"そういったものが１５３カ所、これは今から５年ぐらい前のデータなので、おそらく今区内に製造所というのはなくなっていると思います。そういう形で危険物施設の状況を把握しているという次第です。","id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"耐震性があるのかどうかも伺ったんですけれども、あとパイプラインも含めてですね、あと二つの発電所の部分の耐震性も含めて説明を求めました。","respondent":"山口防災安全担当課長","answer":"そういう項目の中に当然耐震的なもの、そういったものの審査も入っております。そういうものを通ったものは、一応法令上は耐震性があるという位置づけです。","id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"やっぱり検討しているからと、それ待ちじゃなくて、必要な情報は区がしっかりとるべきだというふうに思っているんです。必要な発言もするべきだというふうに思っているんですが、その点についてはどういうふうに考えているか尋ねました。","respondent":"山口防災安全担当課長","answer":"委員のおっしゃるとおり、やっぱり品川区、許認可の権限がないから知りませんよというわけにはいかない。そういった高圧ガスの規制官庁からデータをいただいて検討するとか、そういったものは柔軟に対応していきたいというふうに思っております。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、やっぱり品川区として必要な発言をしっかりしていただきたいということ、この点についても強く求めておきたいというふうに思っています。それから、耐震性の部分でちょっと再確認なんですが、その辺についてはどういうふうに考えたらいいのかをちょっと最後に確認しておきたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"５００m2以上のものについては、昭和５６年以前の旧耐震でつくられたもの、それの耐震化状況を把握してきてあります。平成２７年までに耐震化目標ということで決めてありますので、そういう中で区としても現状を把握していきたいと、このように考えております。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"ここに死者数を１０年間で減らすこと、あと経済被害額も減らすことということで、目標の中に、家具の固定化も入っているんですね。その家具の固定化というのは３０％を６０％に引き上げると、対象拡大になりますけれども、その数字をちょっと教えてほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"家具転倒防止につきましては、私どものほうで平成２０年度より制度として実施しています。平成２２年が１０５件、２月末現在で１８４件ということで、３.１１後については急増しているというような状況です。","id":"exchange-143"},{"speaker":"南委員","kind":"質問","question":"１６万世帯のうちの４００世帯ぐらい、そういう感じですかね。一刻も早くやってください、そういう立場に立つべきだというふうに思うんですけれども、改めてのこの点の見解を伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"南委員","kind":"質問・要望","question":"伺ったわけですけれども、そういうことを言っていたら耐震診断だって耐震改修だって、みんな同じじゃありませんか。命を守る、そういう方向にぜひ足を踏み出していただきたいということをお願いして、もう時間がありませんのでこれで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"私は１７８ページ、防災対策費全般についてお聞きしたいと思います。いまだに大勢いますが、特に住民の生活再建がおくれていることに対して、防災課ではどのように分析しているのかお考えを説明するよう求めました。","respondent":"高山防災計画担当課長","answer":"分析ですが、今回の東北大震災につきましては、世界で歴代４番目の大規模地震ということでございました。東北３県を中心に広域的な被害をもたらしたといったところで、再建などがおくれていると、そのような分析をしております。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"ここでお聞きしますが、整えられる支援制度というのは、この品川区にあるんでしょうか。今国の、例えばいろいろな支援制度がありますが、ここにも何か被災後生活再建をできるような支援というのがあるんか尋ねました。","respondent":"高山防災計画担当課長","answer":"品川区独自のそうした制度、仕組みというのはございません。こういったものは国や都、そういった広域的な支援がまずは基本であろうかと考えております。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"でも、１年たってこの状態ということは、本当にあるんでしょうかね。でも、多くの方がそのままいるということは、ないんじゃないか尋ねました。","respondent":"高山防災計画担当課長","answer":"基本的には国の災害救助法に基づく支援体制ということで、こういったものは組まれるものと考えております。国費を投入して復旧復興に努める、そういった形になろうかと思います。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"前の質問でも申し上げましたが、区民に対して民間の地震保険の加入を積極的に進め、普及啓発を図るべきだと思うんですね。ですから、誠意があっていいと思うんですけど、その辺についてご見解を説明するよう求めました。","respondent":"高山防災計画担当課長","answer":"火災保険と同様な考え方でよろしいかと思うんですが、個人の判断で加入する、しないの判断をしていくことが最適かと思います。自治体として推奨すべき性質のものではないと考えております。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は区でこの制度をやれとは言っていない。でも、こういうものを普及させるということは私は区の使命だと思いますので、ぜひその辺は再検討して考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"阿部委員","kind":"質問・要望","question":"職員給与費は、これは防災計画を立てられる期間限定ということなんでしょうか、それとも恒常的な定員増として考えられているのか教えてください。区の見解をお伺いいたします。","respondent":"堀越人事課長、中山防災課長","answer":"防災課の職員の増ですが、防災対策の強化を目的といたしまして、こちらにつきましては、時限的ではなく、定数として１名増をこの４月から行うものです。 それと、第一には、第一にはと言いますけれども、やはり親御さんが迎えに行くのが一番だと思います。備蓄品もないような場合には、それは近隣の避難所へ行っていただいて、それなりの処遇をしていただければと思います。","id":"exchange-151"},{"speaker":"阿部委員","kind":"質問・要望","question":"現実問題としてどういうことが起こるか、そのために事前に何を考えておかなければいけないのかということをぜひ今後ご検討ほしいと求めました。ご検討いただけるかどうかということだけ端的にご答弁ほしいと求めました。","respondent":"中山防災課長","answer":"検討いたします。","id":"exchange-152"},{"speaker":"阿部委員","kind":"提案","question":"次に、戸籍事務費なんですけれども、１階の法務局に行きますと、記載台のところに、土地家屋調査士の名札の掲示板があります。以前も要望したことがありますけれども、それを記載台の周辺に設置することを提案いたしますが、お考えとしていかがか尋ねました。","respondent":"梶戸籍住民課長","answer":"そういった方々にお金を払ってすることはもちろんできますでしょうけれども、我々のほうにご相談いただければ、ある程度のところは回答ができます。そういったこともまとめてご相談に応じておりますので、そういった点で区民サービスに努めている、今そういった状況です。","id":"exchange-153"},{"speaker":"阿部委員","kind":"提案","question":"窓口で例えば遺産相続などの解説を受けるときに、しばしば、ちょっと過不足があるというようなことを伺っております。そういう意味で、区民サービスの向上になるのではないかということでご提案をしていますとの意見を述べました。","respondent":"梶戸籍住民課長","answer":"ただいまの事例ですと、いろんな書類の中で不足分があったというようなお話もあります。こちらで対応していますので、もしそういったことがございましたら、これからも勉強して進めてまいりたいと思います。","id":"exchange-154"},{"speaker":"若林委員","kind":"意見","question":"予算書、これを議会がこうやって約１週間かけて審査をする。いわゆる議決に耐え得るだけの何か工夫、そういったものが私は必要かなというふうに思いましたので、冒頭にご答弁をお願いしたいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては、今回いろいろ旧西五反田職員待機寮の活用について検討してまいりました。そうしたご理解とご了解等をいただいた後に、速やかにこういった事務を執行できるようにということで当初予算に計上させていただいたものです。","id":"exchange-155"},{"speaker":"若林委員","kind":"意見","question":"事前調査という今言葉がありませんでしたけれども、午前中ではそこら辺の言葉が盛んに使われていたと思います。今のご答弁では、私としてはもう一歩納得のできるご説明があってしかるべきかなというふうに思いますので、もう一言お願いいたしますとの意見を述べました。","respondent":"日下部企画部長","answer":"私どもの答弁ですね、ちょっと説明が必ずしも十分でなかった点があろうかと思いますが、今、行革担当課長が答弁申し上げました。先ほどもご質問にありました、調査検討というようなことも含めて、何とぞご理解いただきたいというふうに思います。","id":"exchange-156"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、前回所管別のそれぞれ評定１から５まで、どういうふうな所管別の人数になっているのか、これを確認させてほしいと求めました。ここら辺もなかなか事務事業概要等、ここら辺はあまり出てこない部分ですので、その目的も含めてご答弁をほしいと求めました。","respondent":"堀越人事課長","answer":"客観的継続的に勤務実績を把握いたしまして、職員の能力、それから職務能率の向上に資することを目的としております。それから態度、業績等を５段階評価によって評価をしていると、こういう内容のものです。","id":"exchange-157"},{"speaker":"若林委員","kind":"質問・要望","question":"ですので、この評定１とか評定２の方が、また当然お仕事ですから、区役所の中でチームワークでされていると思います。評定１が何名いたりとか、そういう職員のお一人お一人であっていただきたいという意味で、全体的にお考えをお聞きしたいと思います。","respondent":"堀越人事課長","answer":"冒頭目的でもご説明させていただきましたように、活用、人材を育成していくという観点でやっていくのが基本的な考え方です。評定２と評定１の職員に対しても的確な指導、適切な指導を行って、人事課が指導して対応しています。","id":"exchange-158"},{"speaker":"若林委員","kind":"質問・要望","question":"去年と今年、特に来年度の監査のお仕事、これがどういうふうになっていくのかというのをご答弁ほしいと求めました。内容につきましては、監査の目的、それから代表的な定期監査や行政監査といった一連の流れについて、内容とか説明をほしいと求めました。","respondent":"鷹倉監査委員事務局長","answer":"定期監査あるいは行政監査等いろいろな１年間を通じて事務があるわけですけれども、監査に臨んで、そういう場にもなっているのかなと。冒頭に申し上げたとおり、区政の発展により寄与していけるようなテーマを見つけながら意見等を提出していきたいと、このように考えてあります。","id":"exchange-159"},{"speaker":"若林委員","kind":"確認","question":"そこで、今度は区長部局のほうになるんでしょうか。ここの確認と、１回指摘を受けた、自分たちで改善しなかったことは報告しない。","respondent":"榎本企画財政課長","answer":"財務監査等がありますので、その部分の指摘は全部各所管で改善方法を見つけてどういうふうに改善したかというのを報告しているというのが全体です。","id":"exchange-160"},{"speaker":"須藤委員","kind":"質問","question":"１５１ページの国際交流推進事業に関係して、品川区国際友好協会の設立時期と目的をお知らせください。ここと税務との関係がどういう仕組みになるのか、そのあたりを、これをやったことによるメリットというのは何かあるのかどうか説明を求めました。","respondent":"今井協働・国際担当課長、梶戸籍住民課長","answer":"その後昭和６１年に外務大臣の許可を受け、そして財団法人品川区国際友好協会と東京都の指摘を受けて名称を変更して現在に至っております。設立の趣旨は、国際間の親善交流は区が直接行うよりも、民間同士でやることが望ましいと… 外国人に関係する法律、あと住民基本台帳法の改正によりまして、今年の７月９日から外国籍の方にも住民基本台帳法上の適用になるという形です。その中で、世帯主あるいは扶養されている方等もはっきりしてくるという形を考えてあります。","id":"exchange-161"},{"speaker":"須藤委員","kind":"質問","question":"私立学校の外国人の保護者の支援というのが昭和５５年の議会の請願でという話だけども、何でこの３国だけ特別にというのは、いかがでしょうか。その前の税金というのは全然わからないよという仕組みになっていたんじゃないかと思うんだけども、そのあたりはいかがでしょうか、説明を求めました。","respondent":"高森税務課長、諸岡総務課長","answer":"６月８日、９日、１０日ぐらいが普通徴収で課税される状況になってあります。会社の事務経理的な職員を窓口にして、課税された後に徴収いただくというふうな形で、さまざまな形で徴収に努力しています。 外国人学校児童への保護者補助金等の件ですけれども、国際友好協会とも今後そういう措置ができましたので、十分連携を図りながら進めていきたいというふうに思っております。","id":"exchange-162"},{"speaker":"須藤委員","kind":"質問","question":"防災対策費で質問させてもらいますが、今日は質問を聞いていると、モデル地区をこれから決めてくるという話になっている。火災による問題が非常にあったわけですから、これだけ頑張っているよと見せるいいあれになると思うんですけども、いかがか尋ねました。","respondent":"濱野区長","answer":"都の木造住宅密集地域整備事業に対する一つのアピールとして、さまざまなことが考えられるわけです。行政効果の問題と、東京都に対するＰＲ効果という点で勘案しながら、研究をさせていただきたいというふうに思っております。","id":"exchange-163"},{"speaker":"須藤委員","kind":"質問・要望","question":"今日はずっと１日防災にかなり質問がいろいろあったんだけども、道筋をしっかりつくっていただければと思いまして、これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":121839,"voices":409}},{"id":"h24-20120309-3","meetingId":"h24-c-budget","date":"2012年3月9日","dateIso":"2012-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"それから２０３ページ、２０５ページの成年後見センターと、成年後見にかかわるところで質問をさせてほしいと求めました。高齢者世帯の安否確認事業で、一方では消防庁型というんですか、今増えたり減ったりの理由とをお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"消防庁方式ですけれども、こちらは平成元年から実施している事業でございまして、現在は新規の方は受けていないという形になっております。警備会社がご本人のところに向かうと同時に、鍵を開けて救急車を待つと、こういう大きな違いがあります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"でしたら、やはりこのシステムを民間型でやられるんだったらば、早急に民間型に統一してやられたほうがいいのではないかなと思います。昨年の一般質問でしたんですけれども、どのような形でそういった孤立死防止の働きをされているのかなということをお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"さまざまな形で対応していかないといけないということで、区でもこういったハードによる対応と、町会でできる対応をしていただくということで。平成２３年度１年で見ますと、１３町会が新たに参加いただいているということで、さまざまな形での対応をとっているところです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"それからまた、ガス会社、水道とか電気会社との連携を進めてほしいと求めました。もう１つ、２１９ページの障害者の緊急通報システムというのは、これはどうなっているんか尋ねました。","respondent":"永尾障害者福祉課長","answer":"障害者の緊急通報システムにつきましては、委員ご指摘のとおり、消防庁型になっております。日ごろから障害の程度によって協力員の方との連携というのも必要な部分もありますので、このままの消防庁型で進めていきたいと考えております。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、成年後見制度のことでお伺いさせてほしいと求めました。やはり、潜在的な被後見人数というのは品川区内でどう考えられているか尋ねました。","respondent":"原高齢者福祉課長","answer":"１７６件という形で、平成１４年度から実施していますけれども、そういった状況です。現在、成年後見センターが法人の後見人になっているのが１３７件というところで、申立を含めて区と連携をとって実施をしています。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"大体、それだけ大勢の、約８,０００人とおっしゃいました。予算がついていますけれども、どういったことを今行われているのか、市民後見人を含めて区としてのお考えはどういうふうになっているのか尋ねました。","respondent":"永尾障害者福祉課長、原高齢者福祉課長","answer":"平成２２年度については１件ということで、数が少なくなっております。親御さんが高齢化していく中でやはり１人になってしまう障害の方も出てくると思われますので、ニーズは高まっていくのではないかと推測できます。成年後見センターと一緒に支援員として、成年後見センターがやっている事業に参加してもらい、一緒に活動してもらう中で経験を積んでもらう。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"この成年後見制度を進めていくのが必要だと思っています。こういった現状、ちょっと時間がないですけれども、どうなっているのかなということをお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"所得のない方への対応というご質問かと思いますけれども、こちらは社会福祉協議会で給付金等をいただいておりますので、そういった工夫の中で対応しています。","id":"exchange-006"},{"speaker":"鶴委員","kind":"提案","question":"２１３ページの熱中症等予防対策事業でありますけれども、これは昨年度６月補正で３４２万が計上されて、さまざま提案もさせていただきました。","respondent":"原高齢者福祉課長","answer":"今年度の予算として増えているところですけれども、昨年度は在宅介護支援センターを中心に対応してまいりました。平成２４年度につきましても同様にそういった対応を各所管で考えていくところです。","id":"exchange-007"},{"speaker":"鶴委員","kind":"提案","question":"ちょっと時間の関係で、提案にしますけれども、厚生委員会の中でもさまざま提案をさせていただいたんですけれども、まず、名称ですね。どうか一考をしていただきたいと、これは提案ですので、お願いいたしますとの意見を述べました。","respondent":"安井子育て支援課長","answer":"基本的には保健センターで保健師とか助産師が回っているんですけれども、回りにくい部分を児童センターで扱うという形になっております。本来の趣旨としては、やはり訪問の際に渡すということで、こちらのほうを若干予算を下げさせていただいた次第です。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問・要望","question":"いろいろお声をお聞きする中で、どうしても外に出られない、１人で子育てされているお母さんって今非常に多いと思うんですね。だれがどの資格の方が訪問するかというところをもう一回教えていただきたいなというところと、あと、民生費の視点で教えてほしいと求めました。","respondent":"安井子育て支援課長","answer":"９０％とか、今後あわせて表記していって、誤解のないようにしてまいりたいと考えています。ここら辺は改善します。","id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"文言的な部分の確認でありますけれども、平成２３年７月１日号でありますけれども、説明部分はほぼ同じだったんですね。最低２週間ぐらいに拡大できる、教えていただきたいと思うんですけれども、お考えをお願いしますとの意見を述べました。","respondent":"安井子育て支援課長","answer":"回数を増やせないかということですけれども、そちらを見ながら、ちょっと研究していかなければいけないというところかなと考えています。どのぐらいのニーズがあるのかを調査した上で、そこら辺を検討する形になろうかと思います。","id":"exchange-010"},{"speaker":"向委員","kind":"質問","question":"これは２１１ページとかに入るんでしょうか、ちょっとそのあたりでお尋ねしたいんですが、このあたりに入ってくることになるのでしょうか。ちょっとそのあたりを説明するよう求めました。","respondent":"原高齢者福祉課長","answer":"福祉カレッジで認知症の特別講座ということで、支援する側が認知症を理解して正しいケアをしていくという形で、まずは実施している事業があります。それから、認知症サポーターの関係ですけれども、こちらは国で全国の認知症サポーター養成ということで実施しています。","id":"exchange-011"},{"speaker":"向委員","kind":"質問","question":"では、認知症サポーターに関しては１点だけ、最後にお伺いしたいんですが、区内の企業とか、そういう団体向けにアプローチはありますか。ちょっとそのあたり、簡単にお願いします。","respondent":"原高齢者福祉課長","answer":"地域の方と、企業、それから例えば、生命保険の方々ですね、地域に回りますので、そのときに認知症の方を理解していただくという形でもやっています。","id":"exchange-012"},{"speaker":"向委員","kind":"質問・要望","question":"続きまして、２１７ページの補装具費ですね。大体どのぐらい時間がかかるのかなとか、そういった概要を教えていただいてもよろしいか尋ねました。","respondent":"永尾障害者福祉課長","answer":"その申請をいたしましたら、判定につきましては基本的には東京都心身障害者福祉センターで判定を行います。早いものでは２カ月から３カ月ですけれども、ものによってはその体に合わせなくてはならないので、半年以上かかるケースもあります。","id":"exchange-013"},{"speaker":"向委員","kind":"質問・要望","question":"希望がなかなかかなえられないという意見を伺ったりすることもあって、一方、このあたりも慎重に対応を続けていっていただきたいなと思います。種類が大きく分かれて３つあると思うんですが、後見の人数が何人いるとか、そこら辺の内訳がわかれば説明を求めました。","respondent":"原高齢者福祉課長","answer":"保佐とかそういった類型の種類はちょっと手元になくて大変申しわけございません。ただ、件数としては先ほど申し上げた中の一部が、そういった類型になるということでとらえているところです。","id":"exchange-014"},{"speaker":"向委員","kind":"質問","question":"どうして内訳とかをお尋ねしたかったかというと、ほかの区の方とかほかの自治体の方にも品川区、すごいねというお話をよく伺います。補助とか保佐とか、そこら辺の申立に対しての区のお考えというのを今日はちょっとお伺いしたいんですけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"そういう相談の中で、そういったところが少し対応が難しくなってきているという場合については、こういったところも含めてご相談をしていくです。この方は財産的にはどこが課題になるかというところを見きわめる中で、それぞれの個別ケースに対応した対応をしています。","id":"exchange-015"},{"speaker":"向委員","kind":"質問・要望","question":"なので、そのあたり、ご本人の保護と本人の意思のバランスというのは難しいとは思うんですけれども、頑張っていただきたいなと思います。ご本人の財産をどうやって横領されずにとか、どういうふうに活用していこうかなと、もしそういった考えがあれば説明を求めました。","respondent":"原高齢者福祉課長","answer":"こういったところは国の流れを十分注意しながら行くということが現段階での考え方です。非常に心配な部分ですから、そういうできる形を品川区、あるいは社会福祉協議会で講じているところです。","id":"exchange-016"},{"speaker":"向委員","kind":"意見","question":"高齢者の方の後見プラス知的障害の方とか精神障害の方の成年後見というのも内容が全然、色合いが違うというのが浮き彫りになってきていると思います。ご苦労も多分にあると思いますが、引き続き先進的な品川区ということでアピールと活動、ご尽力をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は、本日は２３７ページの保育園運営費全体に関してと、２４３ページのすくすく赤ちゃん訪問事業についてお伺いしたいと思います。なぜこの精神障害者保健福祉手帳の級数が入所基準の点数に加えられていないのか、ご説明をお願いしたいと思います。","respondent":"吉岡保育課長","answer":"精神障害についてはこの入所基準表をお持ちかご覧かと思うんですけれども、その心身障害の欄の上に疾病という欄がございまして、そちらで精神的な障害による保育の必要性についてはカウントをしています。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"意見","question":"精神障害者保健福祉手帳が登場したのも１９９５年でありまして、いまだに他の障害者に比べて、画然とした差が残っている面があります。身障手帳・愛の手帳と同程度の支援を行うことを強くお願いしたいと思いますが、区の見解を説明するよう求めました。","respondent":"吉岡保育課長","answer":"今後の検討の課題として、今お話があった精神障害者保健福祉手帳の活用も含めて、今後の課題として検討していきたいと思ってあります。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"すり合わせとか、同等のパンフレットとか、これは実際行っている事業そのものは全く同じなんでしょうか。ご質問します。","respondent":"安井子育て支援課長","answer":"お持ちしているもの自体は全く一緒で、すべて保健センター等で利用する先ほど申しましたグッズ類はうちで用意しているという形になっております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"保健師だとか、あるいは児童センターの方が行うすくすく赤ちゃん訪問事業のときに保護者の方に十分な啓発というのが非常に大切な機会になってきます。ぜひこの中にワクチンを啓発するパンフレットも含めていただきたいということをちょっとお願いしたいと思いまして、いかがか尋ねました。","respondent":"矢野品川保健センター所長","answer":"確かに委員ご指摘のロタウイルスのワクチンは２カ月前から接種しなければ、このすくすく赤ちゃん訪問ではおおむね２カ月までは、その中で聞かれた場合にきちんと対応できるよう研修には今後努めてまいりたいと考えています。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ありがとうございました。衛生でまた質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"確認","question":"質問ですけれども、一次で入れなかった５００人の方、保護者の状況がわかったら教えてください。不承諾の５００人に対して、区には認可保育園に入園をさせる義務があると思っていますけれども、ここの点も確認したいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"児童福祉法におきまして、市町村に保育の実施の義務があるということは書かれております。あわせて家庭的保育事業の実施も始めておりまして、認証保育所、家庭的保育事業などをあわせた形で総合的に対策をとっていきたいと考えております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大ざっぱにも３００人ぐらいの方が今年も入れない状況にあると思います。プラスさまざまな施策ということで、６１人に対して５５７人拡大してどうして５００人も入れないのかという、この辺をご説明ほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"その後、改めて０歳でお申し込みになる方、あるいは１歳以降にまた仕事を始めようとお申し込みになる方などが申し込んでこられます。ですので、６１人を解消すればいいとは区としても思っておりませんので、これだけの数の拡大を図っております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとここは、だから、私はこのギャップをどうとらえていらっしゃるのかなというのが１つです。ぜひ先に進めることを考えていただきたいんですが、いかがか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"認可保育園が保育の実施の中心軸であることは認識しております。認証保育所、家庭的保育事業そのほか多様な施策で、待機児童につきましては少しでも減らす努力をしていきたいと考えております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは一般質問したので要望にとどめておきます。希望の園の食材の放射能の測定をぜひやっていただきたいんですが、いかがか尋ねました。","respondent":"吉岡保育課長","answer":"区立保育園で実施をしましたのは、むしろ安全という認識をしているんですけれども、念のために検査をしているという位置づけです。とりあえず、今現在のところは区立保育園での検査ということで考えておりますので、ご理解をいただきたいと思います。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"さいたま市で親子３人の方が餓死をした痛ましい事件もありましたけれども、また、命が守られたのではないかなと悔やまれる事件であったと思います。申請書を見えるところに置いてほしい、区民に周知をしてほしいと思いますが、いかがか尋ねました。","respondent":"平澤生活福祉課長","answer":"これに対応するということで、区内のガス、私どもの施設をご紹介くださいというご案内を差し上げたところです。ご案内を、福祉事務所がこちらですよという、そちらのＰＲをさせていただいたほうがより有効ではないかなと考えているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"広く区民の方々にこの制度を理解していただくという意味での周知をしていただきたいのと、必要な人に相談の窓口につながるようになってほしい。そういった意味ではパンフレットを置くとか、申請書、ぜひ置いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"引き続きましては２４８ページの生活保護費の中の医療扶助費について質問させてほしいと求めました。確認の意味で、現状の欠員の状況、この辺をはじめにお伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"あるいは母子世帯等の相談等に応じての対応、行政と連携しながら地域のためにしていただく、こういったところが主な中身です。主任児童委員につきましては２６名の中で１名の欠員です。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"この母子家庭の方、中学１年生の娘さんが１人いらっしゃる母子家庭の方ですけれども、お母さんが急に体調が悪くなって夜、入院をする事態となったと。区としてのどういった体制、どういう体制がとれているのか、この辺をまずお伺いしたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、時間帯によって、確かに役所に連絡がとれない時間帯があります。深夜帯に起きた場合には深夜の救急が対応をまずしていただく中で、また、その後の対応をしていくといった現実的な対応をとっているところです。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"こういったときに民生委員の方は大変にどうしていいのかということで、やはり苦慮してしまう、立ち往生するという状況があります。２４時間までは行かないにしても、夜はもうちょっと遅く９時ぐらいまでとか、この点についていかがお考えか尋ねました。","respondent":"原高齢者福祉課長","answer":"さまざまなケースというんですか、対応というか、状況の判断が必要になってこようかと思います。状況に応じて、そういったところも使っていただきながら、対応していく形にはなってあります。","id":"exchange-031"},{"speaker":"塚本委員","kind":"意見","question":"そこからつないでとかという話があるかもしれませんけれども、そのときにつながらないとか、つかまらないとかという事態もあるかと思います。もう一歩、そこを踏み込んで体制を整えていくというふうにすべきかと思いますが、もう一度ご答弁をお願いしたいと思いますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"そういった中で、それから深夜・休日等における負担の軽減ということで、特に緊急を要す場合の対応が民生委員としては一番困る部分かと思います。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"２日に１回以上、高頻度で３カ月以上続けて通院した頻回通院者というんですか、とにかく全国で１万８,２１７人に上ると。数字もお願いしたいんですけれども、現状の状況ですね、どのようになっているか教えてほしいと求めました。","respondent":"平澤生活福祉課長","answer":"それで、改善していただいた方が１０名強ということでございまして、今も指導を続けているという状況です。折り返し、また嘱託医と相談している部分も含んですので、ご理解をお願いいたします。","id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"この新聞記事の中でもう１つあるんですけれども、車で送迎するなど、手厚いサービスをするということもちょっと触れられております。どのようにされているか、何かご答弁できることがあれば、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"平澤生活福祉課長","answer":"ちょっと私のほうでご説明が漏れている部分がありますので、まず、医療扶助の話からさせていただきたいところなんですが。先ほどご説明いたしましたとおり、こちらにつきましては、そういうことでご理解いただきたいと考えています。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"あれば、それはやはり非常に制度の運営上に大きな支障を来す問題だと思いますので、少し注意をしてほしいと求めました。ざっくりとした質問で申しわけないかもしれないですけれども、ちょっとざっくりで申しわけないですが、答弁ほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"げんき品川におきまして、就労支援を実際に行っております。発達障害者も含めたすべての障害者の方々の就労の支援を今後進めていきたいと考えております。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"もう１点、２３９ページ、この点で伺っていきたいと思います。それを伺いたいのと、あと、ここ何年かの推移もあわせて伺えればと思います。","respondent":"原高齢者福祉課長","answer":"福祉カレッジはさまざまなメニューで実施をしています。例えば、ケアマネジメントコースでございましたら、３０名のところ３０名の参加をいただいているです。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"申込者なんかはかなり上回るかとも聞いているので、その辺の今の現状を改めて伺えればと思います。そこだけお願いします。","respondent":"原高齢者福祉課長","answer":"平成２３年度は４８名の申し込みで３８名ということで、ここ数年、申し込みが上回っていると。ちなみに平成２４年度ですけれども、平成２４年度はさらに申し込みが増えまして、５４名のところを４０名です。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問・要望","question":"質問に移りますが、推測も含めて、一般論なのか伺いたいのが１つ。そういう中で、品川区のものづくりとの連携、仕組みなどは検討されているのか、伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"なかなかものが大きかったり、費用が高いということで、うまくいかなかったこともあります。こんな経験を活かしながら、今後も進めていきたいと思っているところです。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"提案","question":"そして上位者への、これは過去に自民党が提案したという経緯も聞いていますが、上位者が本当に勉強したいという意欲は当然高い。そういったことも一つ案としてあるのかなと思いますので、この２点、ちょっとご見解を伺えればと思いますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"休憩室の部分ですけれども、この辺は今後の中で福祉カレッジを実施しております社会福祉協議会とちょっと調整ができればと考えているところです。区内の社会福祉法人でもそういったところを一部実施しているというところは把握しています。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"確認","question":"その中で、現状、その理念、実践、変わりがないかの確認。預けるから、参加型プラスセレクト型へという２つの柱というものが表現されていますが、この点をまず最初に伺いたいと思います。","respondent":"吉岡保育課長","answer":"ぷりすくーる西五反田は今、ご質問にもございましたように、平成１６年６月に区の新しい形の就学前の乳幼児教育施設として建設をしたものです。","id":"exchange-040"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中では、今後のどう発展していくかというのは大きな注目がありますし、期待もあるでしょう。そういう中での見解を伺えればと思います。","respondent":"吉岡保育課長","answer":"検証というお話ですけれども、品川区の乳幼児教育については、このぷりすくーるをはじめとして、区立の幼保一体施設もあります。第２、国で検討されております新システムに基づきますこども園の動向、十分検討していくべきものと考えています。","id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは２１２ページの障害者福祉費に関連して、今現在の品川区の中高生の障害者の対策についてちょっとお伺いをしたいと思います。障害をお持ちの方の人数がわかれば教えていただきたい、できれば中高生の障害者の人数がわかれば教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"知的障害者の方で、愛の手帳所持者ですけれども、約１７０人です。身体障害者手帳をお持ちの方については、約５０人程度ということになっております。","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問・要望","question":"今現在、知的障害者が１７０人、身体障害者の方で５０人ということですが、その中高生が利用できるプログラムが今、品川区でどれぐらいあるのか、そのプログラムの利用できる内容がどういったものがあるのか、できれば具体的に教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"こちらは小学生から高校生まで放課後を過ごす場として実施をしています。そういう目的があった場合に移動支援ということで、支援者が付き添って、そういう楽しみを行うという事業を実施しております。","id":"exchange-043"},{"speaker":"大倉委員","kind":"質問・要望","question":"利用者数の中で最大数でどのくらいの方が受け入れられるのかというのを教えてほしいと求めました。そこをお願いします。","respondent":"永尾障害者福祉課長","answer":"少ないときでは、本当に２人、３人というときもあります。多いときで大体１０人前後という状況になっております。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば、今、ティーンズプラザとかがあると思うんですが、そういったところでの障害者の利用とかというのは可能なんでしょうか。そういった場合に、例えば、来た場合には、受け入れるのが難しいとかという問題点があれば、ちょっと教えてほしいと求めました。","respondent":"安井子育て支援課長","answer":"さまざまな事業をやっておりますけれども、ミュージカルをやっておりまして、そこの中に何人か参加されているという話は聞いております。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問・要望","question":"全体で２２０人いる中で、そういったお考えがあるのか、ちょっとお聞かせほしいと求めました。","respondent":"安井子育て支援課長","answer":"特に極端に介助が必要であるとか、そういうことでなければ、自由に参加していただいて構わないと私どもは考えております。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問","question":"例えば、そういった部分で、もっとこうしてほしい、ああしてほしいという、利用したいんだけれどもという声が区に届いていたりとかということはありますか尋ねました。","respondent":"永尾障害者福祉課長","answer":"障害のあるお子さんまたは親御さんからのご要望ですけれども、特に直接的なものは聞いておりません。はお母様方が独自に文化センター等をお借りして、いろいろな催し物をやったりとか、そういうことでの工夫はよく聞いております。","id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"まずは１館、２館、ちょっとお考えをお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"区のさまざまな施設でのご利用ですけれども、障害者の方が健常の方とともに過ごすことは非常に大事なことになっております。区といたしましても、そういう施設での受け入れ、物理的な部分はありますけれども、そういうことを進めてきたいと考えております。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういった部分では障害者の方が安心して親御さんも一緒に住める品川区にしてほしいと求めましたので、ぜひよろしくお願いいたしたいと思います。３月２６日に品川区就業センターがオープンして、そこで生活保護受給者とのどういった関係、目標があれば目標も教えてほしいと求めました。","respondent":"平澤生活福祉課長","answer":"これまでの支援の中で、私どもで統計をとってまいりまして、支援をして、結局就労に結びついた方ですけれども、半年以内に就労した人は７割です。したがいまして、保護開始の申請時からすぐ集中的に就労支援をしていこうという案を今考えております。","id":"exchange-049"},{"speaker":"大倉委員","kind":"意見","question":"半年で７割ぐらいの方がまた就労にということなんですが、すごい大切な連携だと思いますので、これからもぜひ強力に頑張ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"藤原委員","kind":"質問・要望","question":"保育園運営でお伺いしますが、教えていただきたいのと、改めてこの制度の意義と目的についてお伺いします。平成２４年度の予算で人口は調べていきますよ、今現時点でわかる、また考えている見通しについてお伺いします。","respondent":"原高齢者福祉課長、間部高齢者いきがい課長、伊崎待機児童対策担当課長","answer":"この３１４件のうちに３０６件、この３０６件については親族が財産管理をしていたケースであるという報道がされたところです。認知症の高齢者が増える… 私たちもそういう点では多様な支援ということも行っておりまして、オカリナとか、こういった演奏会の支援もしたところです。今後につきましても… 乳幼児人口に関しましては、以前の調査から平成２７年度をピークとして微増、微減になるだろうと考えております。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"事故がないために、改めて品川区と社会福祉協議会はどういうふうに連携して仕組みをつくっていくのかお伺いします。どういう考えを持って、お考えがあれば、教えてほしいと求めました。","respondent":"原高齢者福祉課長、伊崎待機児童対策担当課長","answer":"そういった中で、区と社会福祉協議会が連携しながら、事故のないような取り扱いをしていかないといけないと考えています。行政、こういったところが連携をして中身をチェックする… 今後の人口動態、需要についてもあるが、今後の保育園の数について、どう考えていくのかというご質問です。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"調査していっていただきたいと思うんですが、保育園をどういうふうにしていくかという答弁がないので、どの辺で判断するのかと伺ったので、何か答弁いただくよう求めました。","respondent":"伊崎待機児童対策担当課長","answer":"人口動向、保育需要の動向も含めまして、いつの時点でということも含めて、来年以降調査研究していきたいと考えています。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは２１３ページの高齢者見守り事業と、その前のページの緊急通報システムなどにかかわって、ちょっとご質問します。孤立死された方が平成２２年度には２５件、平成２３年度の時点でもわかる範囲で教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"それから平成２３年の孤立死の件数ですけれども、区で把握しています。この１月末で１１件、昨年は年間で２５件だですけれども、こういった数字です。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区全体でこういった事業を広げて見守っていくということですけれども、しかしながら、孤立死をされてしまう方が１１件、平成２３年度１月末であったということですけれども、なぜそこまで至ったのかという実態や特徴などをもしつかんでいたら、教えていただきたいんですが。","respondent":"原高齢者福祉課長","answer":"これは中で倒れているのではないかということで、親族の方に連絡をし、その中で一緒になって対応したです。緊急通報システムとか、あるいは民生委員の対応、こういったことが１件でも少なくなるよう対応していきたいと考えているところです。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはりそういった場所に来られずに、地域とのコミュニティーを失っているという方がやはり孤立死にもつながっていくのかなと思うんですね。品川区として、そういったなかなか外に出られないとか、そういう状況の方の実態把握なんかはされているんか尋ねました。","respondent":"原高齢者福祉課長","answer":"ご案内をするとともに、やはりかかわりが必要だというところを把握する中で日常の民生委員活動の中で気にかけながら対応していくといったところです。何か異常を感じたときには対応していくといった、地域を巻き込んでの対応が必要だととらえ、対応しています。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この人は心配だというふうに集まっている件数が実際あれば教えていただきたいのと、にこにこ訪問サービスというんですか、区の補助がどれだけ入っていたかを教えていただきたいんですが。","respondent":"原高齢者福祉課長","answer":"それから、ヤクルトの、にこにこ訪問の関係ですけれども、こちらについては、現在配布させていただいているのが１５０名強です。社会福祉協議会の事業ですので、区で全額を補助しているという形になっているところです。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"意見","question":"希望の濃淡はあれ、１万件あったということで、本当にこういった孤立死や、また介護というところでも、これからもさらに広がってくのかなと思うんですけれども、あと、ヤクルトのにこにこ訪問のところで、全額というのは大体実際幾らなのかを聞かせてくださいとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"平成２２年度の決算額ですけれども、２３４万円です。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、そしてにこにこ訪問、これも２３４万ですよね。ですので、こういったこともやめずにやはり広げていくということを進めていっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"見守りというのは、さまざまな形で対応していくです。にこにこ訪問も今まではその一つであったかと思いますけれども、新たな形での町会の見守りを含めて対応してきております。","id":"exchange-059"},{"speaker":"金野委員","kind":"質問","question":"高齢者住宅の運営費、まず予算額についてお聞きいたします。これは多分大井林町が入っていることかなと理解しておりますけれども、借上型は微妙に減というところですが、まずその増減の要因を示すよう求めました。","respondent":"間部高齢者いきがい課長","answer":"区は従来、高齢者のための住宅ということで、借上型と建設型で対応してきたところです。借上型の部分、１億１,８００万円ほどあるわけですけれども、このほとんどは借り上げの賃料です。","id":"exchange-060"},{"speaker":"金野委員","kind":"確認","question":"増減の中身というよりは、ちょっと要因を伺ったんですが、では、それはそれとして、建設型と借上型、今ご説明がありました。条例によって指定管理ということで定められておりますけれども、そうすると、この指定管理者の行う業務、これをまず確認したいと求めました。","respondent":"間部高齢者いきがい課長","answer":"指定管理者の業務ですが、基本的には建物の保全ですね。それと入居者にかかわる管理人業務です。","id":"exchange-061"},{"speaker":"金野委員","kind":"質問","question":"今のご答弁でいくと、管理人と保全、いわゆる保全という中に全部含まれたとご答弁をされたということでしょうか。いわゆる居住空間の整備、環境の整備だとか、それから施設の整備だとかというところも入っての保全という理解でよろしいのか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"建物全般の共用部分等の保全です。","id":"exchange-062"},{"speaker":"金野委員","kind":"質問・要望","question":"それぞれ、大体２１年から１９年くらい築年数がたつんでしょうか。あるいは居住環境というところでは個々の要望によって対応するのか、あるいは建物、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"これについては、現在の入居者が退所された場合について、次の方が入るまでには一定のリフォームをかけてあります。この費用についても区が対応しているです。","id":"exchange-063"},{"speaker":"金野委員","kind":"確認","question":"ここの所管にお声が入っていらっしゃるかどうかの確認も含めてですけれども、いわゆるここの居住空間、１階の高齢者の住宅のところというのは。このような現状があるんですが、どのように把握されていますか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"カビについてはいろいろな考え方がありますが、換気の励行について、お知らせをしてまいりたいと感じているところです。ガーデンの部分については特に指定管理者からの報告がございませんので、申しわけないんですが、強く認識しているところではございません。","id":"exchange-064"},{"speaker":"金野委員","kind":"質問・要望","question":"今のご答弁で行きますと、なかなか現状は把握されていないのかなという感じがいたします。指定管理ですから、それで対処されてきたというのはどうかなという感じがいたしますが、いかがか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"どうしても古い建物になりますと、頻回の換気ということが原則で、入居者のそういった対応が一番だです。そういった機会にあわせて調査をして、対応がとれるものがあれば、建物的な対応については考えてまいりたいと思います。","id":"exchange-065"},{"speaker":"山内委員","kind":"質問","question":"私から生活保護費と、それから２０３ページの福祉サービスの評価・向上、このあたりを伺いたいと思います。金銭管理支援、これが１,０００万円の予算で運営がされるということですが、そのあたりの生活保護総務費に関することをちょっとお伺いします。","respondent":"平澤生活福祉課長","answer":"金銭管理支援ですけれども、こちらにつきましては平成２４年度から実施させていただきたいということで予算計上させていただいたところですが。こういう方の金銭管理を支援するために、民間事業者に委託いたしまして、こちらの支援をするという事務です。","id":"exchange-066"},{"speaker":"山内委員","kind":"質問","question":"その中で、そういった就職をするためのいわゆるアドバイザーというんですか、そういったことを行政で具体的に行っているところがあると。こういったことを今、品川区ではそういった特に仕事の意欲を見せている方にはそういったアドバイスをしているのかどうかという現状を説明するよう求めました。","respondent":"平澤生活福祉課長","answer":"委員ご指摘のとおり、若い人、稼働年齢世帯に対する就労支援というのは大変重要な課題であると認識しています。これにつきましては、私ども、ハローワークのＯＢを４名、今雇用しておりまして、専門的な立場から支援をしています。","id":"exchange-067"},{"speaker":"山内委員","kind":"質問","question":"我々にとって医療のいわゆる高額というんですか、そういったものを受けなくてはならないときには、大きな負担になる。そういったときに、なかなか返す言葉がないので、役所はどのようにとらえているのかを伺いたいと思います。","respondent":"平澤生活福祉課長","answer":"生活保護に関する医療扶助につきましては、基本的には保険対象が基本です。保険以外、委員ご指摘の、例えば、先端医療とか、どうしても必要な場合には１件ずつ厚生労働省に協議になります。","id":"exchange-068"},{"speaker":"山内委員","kind":"質問","question":"これがどういうことかというと、調剤薬局に関しては原則１カ所にし、不必要な診療を抑制するといった取り組みをするということ。品川区でも６４億という予算を組んで、多分、それについて何か意見があったら説明を求めました。","respondent":"平澤生活福祉課長","answer":"私どもではどういう取り組みができるのかということだと思うんですけれども、年間で１１万件ほどありますが、それを全件チェックしています。","id":"exchange-069"},{"speaker":"山内委員","kind":"質問・要望","question":"２０３ページの福祉サービス評価・向上に移りたいと思いますけれども、これは障害者の施設というものはないのかということを伺いたいと思います。この第三者評価というものはどういったもので、どういった形で行われているのか、それとも抜き打ちで行くのかということを伺います。","respondent":"永尾障害者福祉課長、原高齢者福祉課長、吉岡保育課長","answer":"第三者評価受審支援ですけれども、障害者につきましては平成２４年度は該当がないということで、この予算には載ってございません。民間評価事業所という… サービスの質の向上の取り組みですけれども、大きく２つございまして、ちゃんと法令遵守をしているかどうかです。お互いにどういったところができている… 平成２４年度は１４園分、これも３年に１度の実施ということで、障害者とほぼ同様です。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"３年やってどうだったのかという検証を一度していただいて、２０５町会やるようになったときに、すごく有用なことかもしれません。ぜひ検証していただいて、また再延長ということがあるかもしれないので、研究を引き続きお願いしたと思いますが、その辺はいかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"そういったこの３年間の中でも、自分の町会ではこういう工夫でできるのではないかということで、この間進めてきております。自分たちのまちをどういうふうにしたら守っていけるかということを研修会の中の一コマということで、グループ討議を通じて実施をしています。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問・要望","question":"先にお知らせいただきたいのが平成２１、この２４１ページになるんでしょうか、この辺の人数の推移というのを教えてほしいのと。いろいろ教えてくれている方々に謝礼を払っているというイメージで見ていて、委託費という形で記載すべきだと思いますが、その辺お願いします。","respondent":"安井子育て支援課長","answer":"でないと、急に委託業者ができないという場合に対応ができないという可能性があるということで、３つのグループに分けて委託を出しています。","id":"exchange-072"},{"speaker":"渡部委員","kind":"意見","question":"いないよというのは関係なくて、そこに児童センターがあるよということで、２５館あると思うんです。その辺、お願いしますとの意見を述べました。","respondent":"安井子育て支援課長","answer":"そういう形で基本的には今現在、４人はこの事業をやるためには必要だという話でやっております。それで、人員配置とか金額等、事業内容のプレゼンをやってもらいまして、チェックしていく形になっております。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"３７万３,０００円のこの事業は、そしてその団体の人数、規模はどれぐらいのものでしょうか。説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"高齢者の知恵とか経験の伝承ということも受けるいい機会だということで、そういうことを目的に実施をしているものです。この事業につきましては、品川区高齢者クラブ連合会に昭和６１年より委託して、実施をしております。","id":"exchange-074"},{"speaker":"木村委員","kind":"意見","question":"この予算書には１１４クラブと書いてありますけれども、１万２,０００名という大きな団体です。平成２３年度も同じ予算額ですが、今よりももっと違った何か成果を期待するか、何かわかればお願いしますとの意見を述べました。","respondent":"間部高齢者いきがい課長","answer":"なお、平成２３年度につきましても、現在のところ、ほぼ前年同様の推移です。成果ということであれば、やはり、地域のつながりがここで生まれる、今風に言うと、地域のきずなづくりにも寄与するものだと考えています。","id":"exchange-075"},{"speaker":"木村委員","kind":"質問","question":"地域とのつながり、大変いいことだと思いますので、これからもぜひお願いしますが、１食当たり小学校で聞いた話ですと３００円ですか。どうして、中学校では今まで１校しかできていなかったのか、その原因が何かわかればお願いします。","respondent":"間部高齢者いきがい課長","answer":"当然、学校のご協力によりまして実施をするということでございまして、日程に組み込んでいただくという形で行ってあります。約２５名から３０名の高齢者の方が学校に伺うわけでありまして、ある学年が当日そこにいない状況の中での対応を望まれるということがあります。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問・要望","question":"それはまた要望としてお願いいたします。趣味と健康ですから、区としてこの事業の目的、私が今言ったことでよろしいか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"委員ご指摘のとおりの目的で行っているものでございまして、詳細については２１１ページに、いろいろな事業について記載をしています。外出機会を増やしまして、地域における孤立防止のためという目的も持ちまして実施をしています。","id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"飲まない、吸わない、金賭けないの３つのルールを守り、脳を活発に働かせ、指を使うことにより健康を維持させるため、大変すばらしいとの解説でした。そして、ほかにも将棋、囲碁、そういうものもありますが、どこに今、大きな違いがあるのか、もしありましたら、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"３人寄ればかしましいといいますか、井戸端会議もそうですけれども、男性のほうが下を向いている方が多いのかなという印象を受けているところです。","id":"exchange-078"},{"speaker":"木村委員","kind":"質問","question":"３月２５日にきゅりあんで全国大会が開かれるということ、２６日には品川区の大会があるということなので、大変な盛り上がりを見せていると思います。そういう意味でも、女性の方々の参加が今大変に多くなったということでありますけれども、その比率がわかれば最後教えてくささい。","respondent":"間部高齢者いきがい課長","answer":"現在の登録者の状況を見ますと、男性が１６５名、女性が４５４名ということで、男女の比率については、３対７で女性が多いという現状です。","id":"exchange-079"},{"speaker":"浅野委員","kind":"質問","question":"参酌標準が６５％ということであります。平成２３年度は随分挑戦的なこともやられたということは伺っておりますが、平成２４年度の特筆すべき施策がありましたら、説明を求めました。","respondent":"榎本高齢者医療担当課長","answer":"委員ご質問の特定健康診査受診率の来年度の想定ですが、５４％程度の受診率を考えてあります。普段実施していただいている医療機関の方々、それから地域の方々との共同ということで、進めてまいりたいと考えています。","id":"exchange-080"},{"speaker":"浅野委員","kind":"質問","question":"平成２４年度も前年度比の約１割アップで、４.２億円が上がっているわけですが、この傾向はこれからもそのまま続いていくだろうと読まれております。そのような見通し、またシミュレーションなどをされたことがあるのかどうか、お伺いします。","respondent":"榎本高齢者医療担当課長","answer":"現在、厚生労働省の検討会におきましてインセンティブの検討もなされてあります。４つの方策ということで、６５％を基準にするのか、もう少し下げた受診率から段階的にやるのかということを検討しています。","id":"exchange-081"},{"speaker":"浅野委員","kind":"質問","question":"区におきましては認知症専門チームを設けて、在宅での支援を含めまして、困難なケースにも対応しているということは伺っております。ちょっと衛生費にかかって申しわけございません。","respondent":"矢野品川保健センター所長","answer":"自立支援医療費の中で高齢期精神障害、それに関しましては、自立支援医療費は平成２２年度３,３９７件中７５件です。ただ、心の健康相談の中で認知症について、保健センターで実際に対応いたしました件数が１７０件です。","id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"こちらの２つの原因がありますけれども、また、認知症の方への支援というものをぜひとも進めていってほしいと求めました。受け取った場合には、歳入のどこに入るのか教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"一方、品川区の住民が区外の保育所に通う、いわば委託ですけれども、こちらは延べ人数で予算上５２０人、３,７００万円余を見込んでいるところです。","id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"過去にもなかなか質問で出ていなかったので、改めてお伺いしたんですけれども、ぜひともこれからも支援をしていってほしいと求めました。細かいところでは、単価とか、そういうところまで伺いたかったのですけれども、これについてはまた別の機会にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"吉田委員","kind":"確認","question":"私は２１３ページ、２３５ページの入院助産費、２４３ページの児童センター事業についてお伺いしたいと思います。確認ですが、今までの対象者が４月以降広げられるということを、その辺をちょっとお伺いしたいと思います。","respondent":"間部高齢者いきがい課長","answer":"過去の２０年ほどを見てみましても、家具の転倒が主な被災ということで、多くの方が被害をお受けになったです。要介護３以上の６５歳以上の方、または障害２級以上のある世帯の方も広げるということで、この分の増です。","id":"exchange-085"},{"speaker":"吉田委員","kind":"確認","question":"広げられるということは、ちょっと心強いんですけれども、今まで、平成２０年度から２１、２２、２３年度とちょっと昨日件数をお伺いしたんですけれども、確認の意味でそこだけちょっとお願いできますか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"今までの実績につきましては、平成２０年度が１０７件、平成２１年度が１０５件、平成２２年度が１０５件、平成２３年度につきましては２月末現在で１８４件ということで、例年の２倍程度になっているという現状です。","id":"exchange-086"},{"speaker":"吉田委員","kind":"質問","question":"それを考えますと、要するに限度額が２万円だとここに書いていらっしゃいますけれども、一体、これは２万円いってしまうのではないか。その辺はどうお考えか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"Ｌ字金具、賃貸住宅の場合につきましては家主の許可が必要だということで、賃貸の方はこのポール式を選ばれていることが多いというのが現状です。","id":"exchange-087"},{"speaker":"吉田委員","kind":"質問・要望","question":"全員につけていただきたいんですけれども、でも、対象者に対してはどんどん利用して防災対策をしてほしいと私は思うんですよ。その辺を最後に一つお伺いしたいんですが。","respondent":"間部高齢者いきがい課長","answer":"従来どおりですけれども、それに伴いまして、別に消防署を通じての周知というのを今まで力を入れてやってきました。対象の拡大ということがありますので、改めて民生委員等を通じまして、さらに一層の周知に努めてまいります。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問・要望","question":"２３５ページの入院助産費ですけれども、こちら、平成２３年度が１２４万５,０００円。これの金額についてのご説明と、この費用はどんな方を対象としているかということをご質問させてほしいと求めました。","respondent":"安井子育て支援課長","answer":"金額にして、こちらは何とか内部で一応流用等をさせていただいて、対応しようという考えですけれども、約３３０万円ちょっとですね。これから生まれそうだという方が３人ぐらい、予約というわけではないんですけれども、出産予定ということで既に聞いております。","id":"exchange-089"},{"speaker":"吉田委員","kind":"質問","question":"１回の出産に今は６０万円ぐらいかかるとお伺いしたんですけれども、その辺はお伺いしたいのと、これはどこからの情報であるかということですよね。今までかかっていた病院をそのままかかれるのか、それとも指定の病院に移らなければならないのかということをちょっとお願いします。","respondent":"安井子育て支援課長","answer":"生活保護の世帯が３９万円という負担はちょっと難しいということで、全員がということで、生活福祉課からこちらへ回ってくるケースです。それで、３件というものも、そういう相談の方がいらっしゃったです。","id":"exchange-090"},{"speaker":"吉田委員","kind":"質問","question":"言い方がおかしいですかね、その辺を何かありましたら、お願いします。","respondent":"安井子育て支援課長","answer":"さらにそういったものを考えているということで、国なり都なりの助成もありまして、区単独でこれをやっているということではありません。これは全国的にやっている制度になっております。","id":"exchange-091"},{"speaker":"吉田委員","kind":"質問","question":"指導員謝礼等ということを私もちょっとお伺いしたかったので、よくわかりました。そこで、最後にここにティーンズプラザに関しての予算がないんですけれども、その内容を説明するよう求めました。","respondent":"安井子育て支援課長","answer":"それを単独に事業としてやっているというわけでは必ずしもございませんので、それぞれの施設に応じてやっている部分がいろいろ違います。","id":"exchange-092"},{"speaker":"吉田委員","kind":"質問","question":"予算書に入っていなかったものですから、ちょっとなくなってしまったのかなと思って心配していました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう中で、１つだけ考え方を伺いたいんですが、任意後見をどう考えていくのか。この前もいろいろ質問で出てきましたけれども、伺うところによると、考え方を教えていただきたい。","respondent":"原高齢者福祉課長","answer":"任意後見の契約件数は４２件ということで、こちらのほうも法定後見とあわせて大事にしながら、心配事に対して対応できるような取り組みをしています。","id":"exchange-094"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺はあわせてお伺いしたいのと、どうしても包括、まず皆無に等しいぐらいの紹介はまずない。本当に現実だと思って、一度伺ったら、そこら辺のところを改めてもう一度どうしたらいいかということをお聞かせ願いたい。","respondent":"原高齢者福祉課長","answer":"区の中でこの２０カ所が基本的な在宅介護支援センターの枠組みということで、先ほどの１３地区を展開で進めてまいりました。それにしましても、社会福祉法人を中心として、民間の居宅あるいは指定サービス事業者と連携をとりながら、今後も進めていきたいです。","id":"exchange-095"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望します。だけどこうするぞとか、いろいろ考えがあると思うんですが、そこら辺をここの部分は聞かせていただきたい。","respondent":"原高齢者福祉課長","answer":"今までの長い実績、これは十分、私ども評価をしながら、これから先々、高齢者がさらに増えてまいります。５法人を中心に、さまざまな力のある法人あるいは事業者と連携しながら、また区民のサービス向上に努めていくという考え方です。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これでそこはやめておきますが、保育園の部分で１つだけ伺っておきます。ここら辺の幼児教育という考え方をどういうふうに区は思っていらっしゃるのか、そこら辺、分けて話をしていただきたい。","respondent":"吉岡保育課長","answer":"０歳で生まれてから就学の６歳までの間、獲得すべき能力ですとか、よりよい育ちができるように育てていくのが幼児教育の基本だろうと思っています。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけどＭ字ラインがあったりいろいろあって、待機児解消もある。具体的に伺いますので、後でやらせていただきますので、いつかやらせてもらいますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"これでまずお尋ねするのは、そういった機会やスペースがあるとお聞きしたのですが、その点についてお尋ねします。東京都の認証保育所の事業実施要領で、こういうルールでというのが定員に関してお聞きしているんですが、その点についてのご説明をお願いします。","respondent":"間部高齢者いきがい課長、吉岡保育課長","answer":"４月に入居予定者の施設見学、その入居説明会のときにも、高齢者クラブの方々とお話を現在させていただいてあります。主に１階の食堂部分につきましては、現在、指定管理者のさくら会とその詳細については打ち合わせをしています。 定員が６名から２９名となってございまして、いずれも０・１・２歳のいわゆる乳児が、定員の半分以上になるように設定をするのが義務づけられているという中身です。","id":"exchange-099"},{"speaker":"高橋委員","kind":"質問・要望","question":"乳児が２分の１ということなんですが、仮にそれを超えてしまった場合は、認証保育所はどうなってしまうんでしょうか。どのような東京都からの状況になるんか尋ねました。","respondent":"宍戸施設整備課長、吉岡保育課長","answer":"東日本大震災の影響で、躯体工事が約１カ月遅れてしまいました。なるべく丁寧な説明に努めて行わせていただいているところです。 ご説明をしました定員の関係について、１２０％までは弾力化ができるということになってありますけれども、東京都のほうから当然是正をするようにという指導が入るということになります。","id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"平成２４年度に向けて都からの指導が入ったのか、これは質問がほかの委員からもあったんですが、平成２４年度の次ですね。そういうところで、認証保育所に関して今、ちょっとお尋ねしたような状況はいかがか尋ねました。","respondent":"吉岡保育課長","answer":"今年度については、園側が枠を拡大することによって、もともとの２分の１以上という基準を超えないようにという形で対応をはかりました。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、国民健康保険と、後期高齢者医療と、介護保険について質問をさせてほしいと求めました。品川区の中でこの職業構成がどうなっているのか、こういうところがどれくらいあるのかについて、まずお聞かせほしいと求めました。","respondent":"本城国保医療年金課長","answer":"被用者の方が３２％程度、無職の方が３６％程度ということになっていますので、類似に近いということも考えているところです。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"大もとで言えば、本来であれば被用者保険に入るべきところが、国民健康保険のほうにどんどん流れ込んできているという状況があると思います。週２０時間以上働いている人は被用者保険に入れるべきだという方向を出していますけれども、そこら辺の認識ということではいかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"制度発足時に約２割であった被用者保険の方が、昭和５０年代から６０年代にかけてから３０％ということで、そのような形で落ちついているところです。かなりの部分は国民健康保険制度に対する支援ということでございまして、今の検討の中でも、その推移を区としても見ているです。","id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、ぜひとも区のほうでも、機会があるごとにそういう改善の方向を求めていただきたいと思っています。平成２２年度、その２つの保険料、そして値上げがその３年間でどれくらいになるのかということを示してほしいと求めました。","respondent":"本城国保医療年金課長","answer":"もし経過措置がなかった場合に幾らになるかという意味で平成２５年度をとらえると、３４万７,８４０円ほどになってきまして、１５万３,７００円程度ということになっているです。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうところでは、本当にこの値上げを抑えていくということで、あらゆる手段を使っていただきたいなと思っているところです。委員会の中でも要望いたしましたけれども、平成２５年度に経過措置が切れるとしたら、その額を教えてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"１つは、平成２４年度については、約３億８,０００万円ということになっております。経過措置実施のためにそれだけの財源が投入されているですが、ただ経過措置につきましては。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは高額療養費のほうをこの分を減らして賦課総額のほうに入れているわけですから、一般財源の額としては、強く要望したいと思います。特別な理由がないのに払っていないと確認をして出すようにというのが厚生労働省の通知ですから、その確認ができていない場合は、いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"品川区の場合は資格証を発行するにあたっては、最終的には必ず訪問して、すべての状況を把握するために努めております。その方を含めて何件かの資格証発行になっているところですが、制度の公平な運営の観点から、そのような形で運営しています。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"会えていないということは確認がされていないということなので、会えない場合は出さないということにしてほしいと求めました。手遅れで命を落とすという方が一人も出ないという思いで、出さないという思いで取り組んでいただきたいと、改めて要望したいと思います。","respondent":"榎本高齢者医療担当課長","answer":"２点目の急激な保険料負担のある段階の層という部分のご質問です。担当課長会もしくはそういったところで、今後も引き続きそのことにつきましては要望していきたいと考えています。","id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９段階から１３段階になったということで、これは３年前のときにかなりこちらでも要望させていただいて、本当に第一歩でしかないと思っています。この問題では、品川区がどういう認識をされているか、ちょっとお伺いします。","respondent":"原高齢者福祉課長","answer":"は介護保険ですので、皆様に負担をいただきながら運営をするというのが前提です。そういった中で、今回は９段階を多段階ということで工夫もさせていただきましたし、それぞれの所得に応じた負担ということで設定したところです。","id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２,０００万円の方は、後期高齢者に比べても３分の１ということで、かなり逆進性が強いです。ぜひこれは改めていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"山元委員","kind":"質問","question":"２３９ページのオアシスルーム運営費、時間があれば２１１ページの高齢者支え愛・ほっとステーション事業をお聞きしたいと思います。１６カ所シルバーセンターがありますけれども、１６カ所全部やっていらっしゃるのか、その辺も説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"このサービスは１６館すべての館で実施をしています。５０年以上の歴史があるんですが、平成になる前からの、既にもう二十数年続いているサービスだということで認識をしています。","id":"exchange-110"},{"speaker":"山元委員","kind":"質問","question":"決算書を見ましたら、年間で２,８１６人の方がこのマッサージを受けていると書いてありました。現実、資料によりますと、東品川だけは月４回ということで、それ以外のところは月１回になるんか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"このマッサージサービスの実施の状況ですが、委員ご指摘のとおり、東品川シルバーセンターにつきましては月４回です。そういう形で実施をしているというものです。","id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"月に１回だと、月１回、教えてほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"それが２人ですので、年で換算すると３,０００人近くのご利用があるということで、比較的好評なサービスだと認識しています。施術者１人に対しまして、１日４時間の勤務になりますけれども、１万１,０００円の報酬をお支払いしています。","id":"exchange-112"},{"speaker":"山元委員","kind":"質問","question":"１日４時間で１万１,０００円というと、いいアルバイトになるかなという気はしますが、これはいつごろからこの１万１,０００円というのはスタートなさったんか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"この１万１,０００円の単価につきましては、ちょっと手元に詳しい資料がございませんけれども、ここ１０年ほどについては、このままずっと据え置いているという状況です。","id":"exchange-113"},{"speaker":"山元委員","kind":"質問","question":"よくよく考えますと、３０分１,３００円か１,４００円、マッサージというのはどうなのかなと思います。非常に生活が厳しいということで、その辺の金額的なことも相談をされましたが、将来的にこの金額を上げる予定はないんか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"就業の場を提供するということで、今風に言えば一種の社会貢献的な意味合い、ボランティア的な意味合いの事業だと考えています。ただ毎年お願いをして実施をしておりますし、ちょうど平成２４年度に向けて現在、団体のほうの意向については確認をしてみたいと考えています。","id":"exchange-114"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がありませんので、２３９ページのオアシスルーム運営費のことについてご質問させてほしいと求めました。ちょっと前と場所が変わったような気がしたので、その辺の流れというか、事情といいますか、教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"オアシスルームのお問い合わせです。今、それから荏原保健センター内で荏原保育園がやっているものが１カ所と、もともとは区内にそれなりにまんべんなくということで配置しています。","id":"exchange-115"},{"speaker":"山元委員","kind":"質問","question":"ちょっと美容院へ行きたいとか、病院へ行きたいとか、いろいろなことで利用なさっているかと思いますが、このオアシスルーム７カ所は、年間どのくらいの人数が利用なさっているか、説明を求めました。","respondent":"吉岡保育課長","answer":"１万人を超える人数、平成２０年度が１万９００人、それから１万７００人、１万８００人と来まして、今年も１月までで９,６００人なので、大体１万人ちょっと超えるぐらいという数です。","id":"exchange-116"},{"speaker":"山元委員","kind":"質問・要望","question":"いろいろな用事で預けたいと思うんですが、どうしても間近にないもので、これはどういうことなのかというご相談を受けました。その辺、どういうふうに思っていらっしゃるのか、教えてほしいと求めました。","respondent":"吉岡保育課長","answer":"確かに八潮地区にないのは認識しています。この体制で運営しておりますので、場所の配置等につきましては、今後の課題として検討させていただきたいと考えています。","id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"私は、２３７ページの保育園大規模改修、介護保険特別会計で５２７ページの在宅介護者研修・支援事業についてお伺いいたします。それから今後、保育園の大規模改修の計画が続いていくのかどうか、具体的にあれば説明を求めました。","respondent":"吉岡保育課長","answer":"平成２４年度に計画をしております小山台保育園ですが、こちらは園舎の改修、それから厨房の改修ということで計画しています。それぞれ計画の年次、それから建物の状況をそれぞれ勘案しました中で、順次必要な改修を行っていく計画です。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"それから、昨年も大規模改修がありました。そこでも当事者の意見として、蓄積されたものを資料として残されているのかどうか、２点説明を求めました。","respondent":"吉岡保育課長","answer":"閉鎖をして改修工事をするということはできませんので、換気ですとか、それでも一定の音あるいはにおいとかが出るようなことはあったと考えています。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"区としてはずっと計画的に行っているわけですから、子どもに対する注意事項というものを蓄積されるべきと思いますが、もう一度お願いします。","respondent":"吉岡保育課長","answer":"施設整備課のほうの技術職員の手も借りながら実施をしていますので、それらを踏まえながら工事の計画を立て、施工するということで行ってあります。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問","question":"抗原抗体反応が起きてしまえば、新しい保育園をつくるときには、１週間以上の換気が必要であるということで取り組まれていると思います。自分で不調を訴えられない子どものために、そういったマニュアルはきちんと整備していく必要があると思いますけれども、いかがか尋ねました。","respondent":"吉岡保育課長","answer":"さまざまな声を聞き取ってですけれども、園は当然、工事を実施する前に、保護者の方にご説明する会を設けてご説明をしております。それぞれ組織としてのノウハウとして蓄積されていると考えていますので、それを活用しながら、今後もきちんと運営をしていきたいと思ってあります。","id":"exchange-121"},{"speaker":"井上委員","kind":"質問・要望","question":"これはぜひ検討していただいて、せっかくの工事ですから、子どもたちを守っていただきたいということを強く要望しておきます。どうして移行する必要があったのか、説明を求めました。","respondent":"原高齢者福祉課長","answer":"いきいきと日常生活を送る中で、できるだけ介護の状態にならないということを考えながら、介護予防事業というものを実施してきたところです。","id":"exchange-122"},{"speaker":"井上委員","kind":"質問","question":"予防事業ということが介護保険に移行しなければできないのではなくて、一般財源でも十分そういう必要性はあって、その辺もできるのではないか。一般財源でできないのかという、移さなければならない事業ではないと思うんですけれども、その辺のお考えを説明するよう求めました。","respondent":"原高齢者福祉課長","answer":"保険料への影響ですけれども、こちらのほうは給付費の３％の枠の中でという大きなスキームがあります。その範囲の中で調整をさせていただいた中での対応ということで、これによって保険料が昨年から増えるという状況にはなっていないです。","id":"exchange-123"},{"speaker":"井上委員","kind":"提案","question":"２０１０年の決算特別委員会で提案いたしました在宅介護者への支援のニーズ調査が、大変評価をしているところです。回収にこだわって取り組んでいただいたのか、その辺をお伺いいたしますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"ただ、そこを生かして直接介護している方々の状況をこちらのほうにも届けてもらいたいということで、実施させていただきました。そういった中で、在宅介護支援センターのほうが改めてこれについて出してくださいという働きかけをしたところではございません。","id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"参加をする方たちも少ないというよりも、定数が少なかったわけですから、これでは毎回同じ通知かなと思われる方もいらっしゃったと思います。今回参加された方のアンケートと、その結果などを区はどのように分析をしていらっしゃって、どのようなことが評価としてわかったのか説明を求めました。","respondent":"原高齢者福祉課長","answer":"２時間、３時間の時間ではありますけれども、リフレッシュができたという意見をちょうだいしています。こういった意見にも区のほうでは耳を傾けながら、今後も施策の充実に取り組んでいきたいと考えているところです。","id":"exchange-125"},{"speaker":"井上委員","kind":"提案","question":"ただ１点、このアンケートの中身なんですけれども、本人支援のニーズ調査が必要であるということで、私たちは提案をさせていただきました。その軽減というだけで、その方たちの支援は区が行うことではないと考えているのか、その辺の区の見解を説明するよう求めました。","respondent":"原高齢者福祉課長","answer":"そういった意味では、介護する方がいかにその介護を続けられるかというところが、大変重要かと考えています。そういった意味では、そういった取り組みの中で、区のほうでもそこの趣旨に合致するような取り組みをしていきたいと考えているところです。","id":"exchange-126"},{"speaker":"井上委員","kind":"質問","question":"どういった内容のレベルアップが図られているのかということと、質問をしてしまいますが、それについても具体的な事業内容を説明するよう求めました。","respondent":"原高齢者福祉課長","answer":"あわせてそういった中で応援講座ということで実施をしているものです。災害対策支援事業ですけれども、こちらのほうは３・１１を受けまして、水等を備蓄するということで実施をしています。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"全体の目的と、その成果をどう考えられているのかということの、区の見解をお聞きします。福島県産の食材使用の変動があるのかどうかをお聞きします。","respondent":"原高齢者福祉課長、間部高齢者いきがい課長、吉岡保育課長","answer":"各地域がそれぞれの工夫の中で、自分たちの町会の高齢者を含めた見守り活動をできる形で実施していくということの、大きな成果です。今後についても… こういう考え方からすれば、今後はより一層充実させることによって、高齢者が地域で元気でいきいきと。こういうことを目指して実施をしていきたいと考えて… 保育園では１１月から各保育園を順次食材の放射能の検査をしています。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、地域の形でいろいろな動きが出てきて、いいことについては広げる。なので、福島県の食材がどういう変動になっているのか、それは把握されていますか。","respondent":"原高齢者福祉課長、間部高齢者いきがい課長、吉岡保育課長","answer":"助成金の件ですけれども、各町会にこのために１０万円を３年間、またそれ以後、５万円を２年間継続といった形での助成をしています。ただ６５歳、７５歳になった場合に、そういう目的に沿って我々はいろいろな事業を展開しております。生きる喜びということであって、そういった観点から… 福島県産のお米以外の食材については、メニューの中で使った食材の中には、福島県産のお米と野菜が何種類か入っていたかと記憶しています。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"検査結果というのがどうとらえられるのか、それから国でやっている指針、こういう風評被害というのは抑えられないのではないかと思ってあります。それに対しての区の対応、これからの考え方を説明するよう求めました。","respondent":"吉岡保育課長","answer":"風評被害につきましては、私どもでも起こしてはならないと考えていますし、きちっとしたご説明を保護者の方にこれまでもしてきたつもりです。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひとも被災者支援という形やこの風評被害、これは非常にこれから大切です。しっかりと対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"３点目、２２９ページ、４点目は老人保健施設についてお伺いしたいと思います。この数字が出てきた、いろいろたたき台の中で出てきたと思いますけれども、２年間延長と５万円の根拠をお教え願いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう気持ちの中で参加いただき、実際にやって、その中で対応していくということで取り組んでいただいているところです。初期の対応では少し事務経費等々がかかるんだけれども、そういうお話もちょうだいしまして、また継続性という中で２年間を継続するということで。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"今、２３町会、１割ちょっと超えましたけれども、これはどこでコーディネートしているんでしょうかね。おそらく地域センターだと思うんですが、その辺の考え方と、地域センターですと、２３ですから、相当数に偏りがあるんじゃないかと思うんですね。","respondent":"原高齢者福祉課長","answer":"コーディネートですけれども、まずは高齢者福祉課の施策ということで実施しています。町会と地域センターの関係、それから区と地域センター、こういったところの連携の中でこの事業は進めさせていただいているところです。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"３月１日から７日まで火災予防運動で、一生懸命消防署、消防団が頑張ってきたところです。障害者のみの世帯、身体障害者手帳２級以上の障害者のいる世帯となっていますけれども、この世帯数をお聞かせほしいと求めました。","respondent":"間部高齢者いきがい課長","answer":"家具転倒防止対策助成の該当する世帯数ですが、従来の対象世帯につきましては、３万３,５５０世帯です。今回、対象が広がると、５万２,８２５世帯ということで、今回の拡大によりまして、１万９,２７５世帯の増ということになるものです。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"今、伺いましたら５万２,０００世帯。ですから、これをつけるにあたって、おそらく２人来ているのかな。","respondent":"間部高齢者いきがい課長","answer":"そういう関係で、基本取付け、これは調査を含んでということで、１件当たり３,７００円ということなんです。ただ、１時間増すごとに１,６００円ということですから、たくさんつけたとしても５,０００円前後がシルバー人材センターの人件費相当分だです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"そういうことを検討されることはないんでしょうか。その辺のことを考慮されているのかどうか、その辺の考え方をお聞きしたいと思います。","respondent":"間部高齢者いきがい課長","answer":"そういうお願いは改めてしていきたいと思っていますが、危険なこともありますので、この制度を使っていっていただくというのも一つの考えです。いろいろなところに我々も出かけていきますので、広く、再度この点については周知をしてまいりたいと考えています。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"ですから、広く考えた場合には、そういうふうにしたほうが、例えば自分の家の中は汚いから見られたくないという家はたくさんあるんですね。その１日でどれだけ人命が助かるかと思うと、もう一度お考えを聞きたいと思います。","respondent":"間部高齢者いきがい課長","answer":"高齢者クラブの会員間でということは共助にあたると思います。通常の助成金の範囲内でのご協力ということであれば、積極的にお願いをしてまいろうかなと考えているところです。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"微妙でまだ言いたいんですが、ほかがありますので、この辺にしておきます。次に、保育事業助成に関連してですけれども、ここ数年の保育児童の受け入れ枠拡大についてお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"今年につきましては、４月で３７８人の認可保育園の定員の受け入れ増ということで図っております。この４月に前年比で１５２人増、平成２３年は前年比で７８人増という形で、合わせまして５００人から６００人単位での定員増を図っているところです。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"そんな中では、保育の主体性そのものも認可保育園から認証保育所、何といったって駅前ですから、預けてすぐ乗れるということで、これは便利だと。そんな人のためには認証保育所、先ほども定員の３・４・５歳か尋ねました。","respondent":"吉岡保育課長","answer":"認証保育所の制度のこれからの変更といいますか、設立のときがもともとが乳児に対する保育需要の受け皿という感じでつくられたものです。","id":"exchange-139"},{"speaker":"松澤委員","kind":"確認","question":"認証保育所については、実はうちのほうの戸越銀座商店街の真ん中に、建物は建築確認で保育所と書いてあるんですね。これのいきさつ、どういう形で保育園が入るようになったのか、その点についてお聞きしたいと思います。","respondent":"伊崎待機児童対策担当課長","answer":"区といたしまして、この床をどのように有効活用していくかというところを検討いたしました結果、今。その後、開設に向けて事業者の公募を図って、事業者が決定したところです。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"大いに期待したいと思うんですが、再開発の中でこのような話し合いが進んでいるところがほかにはあるんでしょうか。お聞きしたいと思います。","respondent":"三宅都市開発課長","answer":"子育て支援施設の導入の検討を説明しておりまして、現在、設置の方向で基本設計を進めているところです。運営方法や規模等については検討中でございまして、これから詰めていくという状況です。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問・要望","question":"私たちも老人保健施設はもう一つつくるべきだという考え方も持っていますが、品川区の老人保健施設、なかなかできません。これについて、品川区として老人保健施設についてどう考えているのかについてお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"老人保健施設につきましては現在、南大井の老人保健施設１カ所という状況です。区においても、老人保健施設についてはもう一カ所必要という認識の中で、早い段階でこの計画が実現できるようにということで考えているところです。","id":"exchange-142"},{"speaker":"松澤委員","kind":"確認","question":"実は品川区はこのようなことを議会で発表する中で、品川区で老人保健施設をやりたいなと声も出ているんですね。このような声が実際届いているのかどうか、確認だけしておきたいと思います。","respondent":"原高齢者福祉課長","answer":"特別養護老人ホームのニーズ、それから老人保健施設のニーズを含めて、区のほうでも考えているところですけれども、話として少し出たり引っ込んだりという状況です。","id":"exchange-143"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２１３ページの家具転倒防止対策助成、２３３ページの家庭的保育事業、保育ママ、２４６ページの生活保護費でお伺いします。平成２２年度は２５名、平成２３年度は１月末で１１名ということなんですが、教えてほしいと求めました。","respondent":"間部高齢者いきがい課長、伊崎待機児童対策担当課長、平澤生活福祉課長","answer":"そういう分類については資料をつくってございませんので、手元にないという状況です。単身が１１７件ということで、単身者が６０… 従前課題としてとらえておりました保育ママの密室性や保育の質については、巡回指導などで対応が図れていると考えております。今年度… 定義といたしまして、平成２３年度中に高齢者福祉課や在宅介護支援センターが関与した緊急対応の事例ということで、１１件です。","id":"exchange-144"},{"speaker":"武内委員","kind":"質問・要望","question":"合わせますと３１名ということで、なぜこれを質問したかというと、二カ月で立て続けに生活保護を受けている方が亡くなったりしているんですね。この方はちょっとという方がいたら、ぜひやってもらいたいなと思うんですけれども、説明を求めました。","respondent":"間部高齢者いきがい課長、伊崎待機児童対策担当課長、平澤生活福祉課長","answer":"基本的には突っ張り棒型といいますか、ポール型をつけることが多いということで、大体の件数は見ることができます。このポール式をつけた場合は… その点につきましては、保育ママの事業費の構成自体が年間の補助額で考えておりますので、事業の運営していただいているものと理解をしております。… 委員ご指摘のとおり、ケースワーカーを通じて、心配なものには周知してまいりたいと考えております。","id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"それだけに心理をはじめさまざまな専門性が求められると思うんですけれども、その点についてどう考えておられるか、まず初めに伺います。常設型、移動式とあるようですけれども、その点についてお尋ねします。","respondent":"安井子育て支援課長、永尾障害者福祉課長","answer":"児童センターの職員についてですけれども、児童厚生員ということで、児童についてのある程度の知識や経験を備えているという者を、委託先も含めて職につかせているという意味においては、専門性はあると考えております。 磁気ループの公共の施設での設置状況ですけれども、移動式、常設式とも現在は設置しておりません。","id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"一刻も早く設備するべきだと思うんですけれども、１台でも２台でも備えるべきだと考えていますので、その点についての見解を伺いたいと思います。委託を拡大するのではなく、改めてなぜ委託なのか、委託で問題点は解消されてきているのかということについての見解を伺いたいと思います。","respondent":"宍戸施設整備課長、安井子育て支援課長","answer":"難聴者用補助設備である磁気ループシステムですが、五反田文化センターの大ホールにおきまして、固定式のものを設置しております。東京都福祉のまちづくり条例に整備基準等がありますので… 児童センターの委託館についてのお話ですけれども、こちらについては委託の仕様書等でそこら辺を確保していく。","id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"１つはあるということで、ほかの施設を使う部分では対応できないわけですから、対応をぜひしていただきたいと考えています。その点についての見解を改めて、直営と一部委託での利用者に対しての差があっていいのかどうか、ここについても伺います。","respondent":"宍戸施設整備課長、安井子育て支援課長","answer":"磁気ループの設置ですが、新設あるいは大規模改修にあわせて設置するということで考えております。それと平塚小学校跡施設のホールですが、東京都福祉のまちづくり条例に基づきまして設置する方向です。 そういう意味において、利用しにくいということはないと考えております。そういったものも教えていくのが児童センターの仕事でもありますので、そこら辺はしっかりはっきりとさせて行っていくように指導してまいります。","id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"それから移動型の磁気ループですけれども、それはぜひ買っていただきたいと考えていますが、その点だけお願いします。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"そしてまた、進めるにあたって、介護、看護の事業所や、品川区だけでなく、他の自治体との連携も必要だと思いますが、いかがでしょうか。ご見解を説明するよう求めました。","respondent":"原高齢者福祉課長","answer":"２４時間対応定期巡回・随時対応の事業の取り組みかと思います。日中帯は、連携型ということで実施していく、そういったスキームづくりで展開していく予定で考えているところです。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問・要望","question":"今現在、苦労されている方が本当に切実に求めていることだと思うんですが、実際、意気込みとして、これは費用もかかると思います。何年ぐらいできちっと普及をさせていこうかとお考えなのか、もしその辺の展望もありましたら示すよう求めました。","respondent":"原高齢者福祉課長","answer":"は現在、モデル事業を実施している方に対して、こういったサービスの継続を４月以降、どんな形で考えているかというところでとらえているところです。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"ただ、これらの事業に逆に参加しない方が、私は圧倒的に多いのではないかと思うんですが、その点、どうでしょうか。もし割合でもわかるようでしたら示すよう求めました。","respondent":"原高齢者福祉課長","answer":"その中でさまざま取り組みがあります。今度、二次予防対象者の把握事業ということで少し取り組みをしながら、参加されない方への促しをさらに強めていきたいと思っているところです。","id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"そして、またそれに対してこういう案が本当はあるんだけどとか、何かそういう施策はお考えでしょうか。こういうことをやってもっと普及させるんだという、また別の事業でもいいんですが、何かお考えがあるんか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"品川区の高齢者人口は７万人ということからすれば、そのような比率だと考えています。いろいろな機会をとらえて周知していくことが大切だと思っていますので、こういう考え方で、なお一層の周知に努めていきたいと思います。","id":"exchange-153"},{"speaker":"阿部委員","kind":"質問・要望","question":"一部すくすく赤ちゃん訪問もからめながら伺いたいと思います。将来的なことも含めて、３歳から５歳児、幼児期と認証保育所の関係について区がどう考えていらっしゃるか、説明を求めました。","respondent":"吉岡保育課長、矢野品川保健センター所長","answer":"先ほどちょっと申し上げましたように、３・４・５歳の幼児期の教育の面では、若干弱い面もあろうかなとは思っております。認証の０・１・２歳が終わった子が、今後、十分検討していかなくてはいけない課題だとは認識しています。産後うつにつきましては、すくすく赤ちゃん訪問において、エジンバラ式産後うつ質問票というものを用いております。","id":"exchange-154"},{"speaker":"阿部委員","kind":"質問・要望","question":"経験の浅い方、あるいは雇用などの関係で、この保育士の質の確保というのをどのように考えていらっしゃいますでしょうか。それぞれの企業において、品川区としても一定の水準は担保すべきではないかと思いますので、その辺の区としてのお考えをお願いいたします。","respondent":"吉岡保育課長、矢野品川保健センター所長","answer":"私立保育園、保育ママも含めていろいろありますので、保育士の質の確保というのは重要なことだと認識はしています。資格は担保されていると考えていますが… 通常の４カ月健診等のフォローで済むものですが、確かにその後、継続的支援が必要なものもあります。保育園のことについては、長期的に必要であれば… 保育園の通常の入園のほかに、一時保育という一時的にお預かりする制度もありますので、そのような制度もご活用いただきたいと思ってあります。","id":"exchange-155"},{"speaker":"阿部委員","kind":"質問・要望","question":"これは要望です。それから品川児童学園については、代表質問でも伺いましたけれども、相談機能の拡大ということで歓迎をしております。","respondent":"永尾障害者福祉課長","answer":"家族支援につきましては、面談の件数については９２件、新規の申込者については７２件という状況になっております。心理の相談員を１人ということになっております。","id":"exchange-156"},{"speaker":"阿部委員","kind":"質問","question":"今後、それを拡大する、環境改善を図るようなご予定はありますでしょうか。その中で、将来像としてより効果的ではないかと思うのですが、そのあたりの区のお考えをお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"実施しております場所につきましては、現在かなり手狭な状況になっておりまして、もう少し広い場所はないかということで探しています。そういうことも含めながら、また、障害またほかの福祉的なものも含めながら、今後検討していきたいと考えています。","id":"exchange-157"},{"speaker":"阿部委員","kind":"質問・要望","question":"発達障害に関する一貫したセンターというのも、ぜひ１カ所でセンターとして機能するような、そんな場所になったらと期待しております。最後は要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう考え方でいいかどうかと、来年度のこの地域福祉計画を推進していくという、どう動かしていくか等についてのご説明をほしいと求めました。あわせて今後、認証保育所の補助のあり方について、お考えをお聞きしておきたいと思います。","respondent":"原高齢者福祉課長、吉岡保育課長","answer":"どういう形で介護予防事業を進めていくか、またその３％の範囲でどのように進めていくかという、複数の事業をその枠の中で移行させていただいたです。まず１つは、学識経験者… それからあと、開設のほうも来年度はまた２カ所の開設を予定しておりますので、その開設の準備の関係等の経費も増要因の一つかなと考えています。","id":"exchange-159"},{"speaker":"若林委員","kind":"質問・要望","question":"要するになぜ介護保険の中にこの３つ、納得できるご説明をもう一回いただきたいという趣旨ですので、地域福祉計画はわかりました。もう少し補助のあり方を全体的に考えてみようとか、こういう待機児童対策として見られないかなと思いますので、そこに一言ずつ。","respondent":"原高齢者福祉課長、吉岡保育課長","answer":"説明を先ほどからさせてもらっているところですけれども、こちらのほう、先ほど３％の財源というお話をさせていただきました。給付費の３％の範囲でという話の中で、どういった事業を展開するのがより効果的か… 月に１６０時間以上の契約という枠をはめておりますので、全くの就労以外のことで１６０時間の契約をするというのもなかなか考えられないところがありますけれども、十分検討しながら進めていきたいと思ってあります。","id":"exchange-160"},{"speaker":"須藤委員","kind":"質問・要望","question":"２０３ページの特別会計繰出金に関連して、国民健康保険、後期高齢者医療、介護保険の特別会計との関連を聞かせてほしいと求めました。ここのとり方というのは、ほかの２３区の自治体も同じような計算、繰入金というのはそういう形で入ってきているのかどうか。","respondent":"本城国保医療年金課長、榎本高齢者医療担当課長、原高齢者福祉課長","answer":"法定分として、完全に法律上に則ったものと、その他不足分を補うという意味のその他繰出金があります。その他分については… 東京都におきましては、東京都内の関係自治体で、特別対策で同様に繰入金として入れております。介護保険特別会計の関係ですけれども、介護保険のほうは法定分で給付費の１２.５％ということで決まってあります。","id":"exchange-161"},{"speaker":"須藤委員","kind":"質問","question":"東京都は２３区特別区でやっているんですけれども、後期高齢者ですと、約半分が一般会計から持ち出しの数字ですよね。一般会計から繰り出しが３５億円という数字でというふうに思っているんですけれども、言った２３区特別区で今、いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"広域化としては、具体的には財政等を国民健康保険について、都道府県単位化するです。場合によっては、いかんによってはどういう影響が出てくるかというのは、これからよく注視していかなければいけないところだと思っているところです。","id":"exchange-162"},{"speaker":"須藤委員","kind":"質問","question":"２２７ページの小規模介護施設整備費は、この前も一般質問でさせていただいたんだけれども、いわゆる文化スポーツ振興課というのがあるわけですよね。そのあたりは児童センター事業というのが、これまでずっと今後ともいくのかどうか、そのあたりを説明するよう求めました。","respondent":"原高齢者福祉課長、安井子育て支援課長","answer":"今のところ、１ユニット９名ということで実施設計、基本設計を予定しています。中延三丁目のほうは、土地を借りて、こちらについてもグループホームをつくるということで検討をしています。 現在、児童センターのあり方について、事業の内容も含めて、さまざま議論をしている段階です。さまざまなところを見ながら整理していくという関係とか、地域との関係とか、いろいろ検討しています。","id":"exchange-163"},{"speaker":"須藤委員","kind":"質問・要望","question":"小規模はグループホーム、何人ぐらいの方を、どういう仕組みのものを考えているか、教えほしいと求めました。もう少し全体で絵をかいてくれると、児童センターに無理にくっつけるだけではなくていいんじゃないかと思うんだけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長、久保田行財政改革担当課長","answer":"１ユニット９名ということで考えてあります。中延三丁目のほうは、土地をお借りしてという形で、今のところ、３ユニット２７名ということでのグループホームを予定しています。 児童センターのあり方の検討というご質問でしたけれども、多世代が多様に使えるような施設のあり方というものの検討を進めていきたいということで、検討を進めているところです。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=970#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":127642,"voices":397}}]);
